def platform_name(env=None):
    """Texto corto para el banner: en qué app corre DLpy."""
    env = os.environ if env is None else env
    app = (env.get("APPNAME") or "").lower()
    return ("a-Shell mini" if "mini" in app else "a-Shell") + " · iOS"
def machine_name():
    try:
        import platform as _pl
        return _pl.machine() or "?"
    except Exception:
        return "?"
def device_label(machine=None):
    """1.6.7: el dispositivo que detecta el script («iPad13,8» → «iPad», «iPhone15,2» → «iPhone», «iPod…» → «iPod»); sin dato claro, «equipo»."""
    m = (machine if machine is not None else machine_name()) or ""
    for name in ("iPhone", "iPad", "iPod"):
        if m.lower().startswith(name.lower()):
            return name
    return "equipo"
def ios_documents_dir(home=None):
    """Resuelve el Documents real de a-Shell sin asumir que HOME apunta a la raiz del sandbox.

    Algunas versiones/contextos exponen HOME como el propio Documents. En ese caso se evita
    Documents/Documents. Si una ejecucion anterior ya creo esa ruta anidada y contiene datos
    de DLpy, se conserva para no separar ni perder la configuracion existente.
    """
    root = os.path.abspath(os.path.expanduser(str(home or os.path.expanduser("~"))))
    if os.path.basename(os.path.normpath(root)).casefold() != "documents":
        return os.path.join(root, "Documents")
    nested = os.path.join(root, "Documents")
    legacy_data = os.path.join(nested, "dlpy_files")
    legacy_config = os.path.join(legacy_data, CONFIG_NAME)
    return nested if os.path.isdir(legacy_data) or os.path.isfile(legacy_config) else root
def ios_library_dir(home=None):
    """Resuelve la carpeta Library hermana de Documents aunque a-Shell haya redefinido HOME."""
    root = os.path.abspath(os.path.expanduser(str(home or os.path.expanduser("~"))))
    if os.path.basename(os.path.normpath(root)).casefold() == "documents":
        return os.path.join(os.path.dirname(root), "Library")
    return os.path.join(root, "Library")
def env_file_path(home=None, hide=None):
    """Dónde se guardan las DLPY_* dentro de Documents/dlpy_files. Con `hide` devuelve el nombre solicitado;
    sin él conserva el archivo visible/oculto que ya exista."""
    folder = os.path.join(ios_documents_dir(home), "dlpy_files")
    shown, hidden = os.path.join(folder, CONFIG_NAME), os.path.join(folder, hidden_name(CONFIG_NAME))
    if hide is not None:
        return hidden if hide else shown
    a, b = os.path.isfile(shown), os.path.isfile(hidden)
    if a != b:
        return shown if a else hidden
    return hidden if hide_files_parse(os.environ.get(HIDE_FILES_KEY)) else shown
ENV_FILE = env_file_path()
