def shortcut_text_by_id(text_id, lang=None):
    """2.0.9: texto del atajo por ID estable en `lang` (nunca por el texto en español). La tabla embebida es la fuente hasta que los .mo la traigan: si el .mo aún no tiene la clave, t_display caería al español, así que la tabla manda primero y el .mo solo se consulta si la tabla no trae el idioma."""
    code = lang_effective(lang or LANG)
    table = SHORTCUT_TEXTS_FALLBACK.get(code) or {}
    if text_id in table:
        return table[text_id]
    es = SHORTCUT_TEXT_ES.get(text_id)
    if es is None:
        return ""
    if code == "es":
        return es
    try:
        hit = t_display(es, lang=code, _debug=False)
    except Exception:
        hit = es
    return hit if hit else es
def shortcut_texts_for(code):
    """2.0.9: {ID: texto} del atajo en `code` (cae a es si el idioma no está en la tabla)."""
    code = lang_effective(code or LANG)
    return {i: shortcut_text_by_id(i, lang=code) for i in SHORTCUT_TEXT_IDS}
def shortcut_texts_payload(code=None, all_langs=False):
    """2.0.9: payload de --shortcut-texts. Sin idioma pedido: el efectivo (DLPY_LANGUAGE; si aún no se eligió, el del dispositivo vía $LANG, si no es). Con all_langs: texts_by_lang con los 13 idiomas."""
    if code is None:
        code = lang_effective(LANG)
        if lang_ask_pending():
            dev = lang_parse((os.environ.get("LANG") or os.environ.get("LANGUAGE") or "").split(".")[0].replace("_", "-"))
            if dev in SHORTCUT_TEXTS_FALLBACK:
                code = dev
    else:
        code = lang_effective(lang_parse(code) or code)
        if code not in SHORTCUT_TEXTS_FALLBACK:
            code = "es"
    out = {"dlpy": "shortcut-texts", "schema": 1, "version": VERSION, "lang": code,
           "lang_name": (LANG_NAMES.get(code) or code), "texts": shortcut_texts_for(code)}
    if all_langs:
        out["texts_by_lang"] = {c: shortcut_texts_for(c) for c in SHORTCUT_TEXTS_FALLBACK}
    return out
def print_shortcut_texts(args=None):
    """2.0.9: `python dlpy.py --shortcut-texts [lang]` / `--shortcut-texts-all`: una línea de JSON ASCII y nada más (sin banner ni animaciones), como --idiomas."""
    args = list(args or [])
    all_langs = any(a[:1] in DASHES and a.lstrip(DASHES).lower().split("=")[0] in ("shortcut-texts-all", "sc-texts-all", "shortcuttexts-all") for a in args)
    lang = None
    for a in args:
        s = a.lstrip(DASHES)
        if "=" in s and s.split("=", 1)[0].lower() in ("shortcut-texts", "sc-texts", "shortcuttexts"):
            lang = s.split("=", 1)[1] or None
    if lang is None:
        for i, a in enumerate(args):
            if a[:1] in DASHES and a.lstrip(DASHES).lower().split("=")[0] in ("shortcut-texts", "sc-texts", "shortcuttexts"):
                nxt = args[i + 1] if i + 1 < len(args) else None
                if nxt and not nxt.startswith("-") and lang_parse(nxt) in SHORTCUT_TEXTS_FALLBACK:
                    lang = nxt
                break
    sys.stdout.write(json.dumps(json_clean(shortcut_texts_payload(lang, all_langs=all_langs)), ensure_ascii=True, separators=(",", ":")) + "\n")
    sys.stdout.flush()
    return 0
def wants_shortcut_texts(args):
    """2.0.9: ¿se pidió --shortcut-texts / --shortcut-texts-all (alias --sc-texts)? Acepta rayas largas («—shortcut-texts»)."""
    return any(a[:1] in DASHES and a.lstrip(DASHES).lower().split("=")[0] in ("shortcut-texts", "shortcut-texts-all", "sc-texts", "sc-texts-all", "shortcuttexts", "shortcuttexts-all") for a in (args or []))
def _lang_select_text(code):
    """«Seleccione idioma» en `code`: del motor (clave en español)."""
    return t_display("Seleccione idioma", lang=code)
def languages_payload(current=None):
    """`--idiomas`: todos los idiomas disponibles para que Atajos arme la lista de elegir.
    «lang_labels» es lo que se ve (bandera + nombre, sin código y SIN el idioma actual); «lang_map» es el diccionario etiqueta → código
    (Atajos busca ahí lo que se eligió) y «lang_codes» va en paralelo a «lang_labels»; «lang_command» es el comando que guarda la elección
    (--config DLPY_LANGUAGE=código). «lang_current» / «lang_current_name» / «lang_title» dicen cuál está activo."""
    cur = current or LANG or DEFAULT_LANG
    langs = [{"code": c, "flag": LANG_FLAGS.get(c, ""), "name": LANG_NAMES.get(c, c), "english": t_display(LANG_NAMES.get(c, c), lang="en"),
              "label": ("%s %s" % (LANG_FLAGS.get(c, ""), LANG_NAMES.get(c, c))).strip(), "current": False,
              "set_text": t_display("Idioma establecido", lang=c)} for c in LANG_CODES if c != cur]
    return {"version": VERSION, "lang_current": cur, "lang_current_name": LANG_NAMES.get(cur, cur), "lang_default": DEFAULT_LANG,
            "lang_count": len(langs), "lang_ask": LANG_ASK, "lang_title": "%s: %s" % (t_display("Idioma actual", lang=cur), LANG_NAMES.get(cur, cur)),
            "lang_labels": [l["label"] for l in langs], "lang_codes": [l["code"] for l in langs],
            "lang_map": {l["label"]: l["code"] for l in langs}, "lang_list": langs,
            "lang_command": "--config DLPY_LANGUAGE=<code>",
            "lang_set": t_display("Idioma establecido", lang=cur),
            "lang_set_map": {c: t_display("Idioma establecido", lang=c) for c in LANG_CODES},
            "lang_set_texts": [t_display("Idioma establecido", lang=c) for c in (l["code"] for l in langs)], "shortcut_texts": {i: shortcut_text_by_id(i, lang=cur) for i in SHORTCUT_TEXT_IDS}, "shortcut_texts_lang": cur}
def print_languages():
    """`python dlpy.py --idiomas` (alias `--langs`): una línea de JSON ASCII en la salida y nada más (sin banner ni animaciones)."""
    sys.stdout.write(json.dumps(json_clean(languages_payload()), ensure_ascii=True, separators=(",", ":")) + "\n")
    sys.stdout.flush()
    return 0
def wants_languages(args):
    """¿Se pidió --idiomas / --langs? Acepta rayas largas («—idiomas»)."""
    return _wants(args, "idiomas") or _wants(args, "langs")
def set_lang(raw, quiet_msg=False):
    """1.7.0: cambia el idioma en esta ejecución y lo deja en DLPY_LANGUAGE (lo guarda la configuración).
    2.0.6: confirma en verde (mint) con «Idioma establecido» en el idioma aplicado, salvo quiet_msg."""
    global LANG
    code = lang_parse(raw) or DEFAULT_LANG
    LANG = code
    os.environ["DLPY_LANGUAGE"] = code
    if not quiet_msg:
        try:
            msg = t_display("Idioma establecido", lang=code)
            if SCENE.get("on"):
                scene_status(t_display("Idioma") + " · " + msg)
                SCENE["label_ok"] = True
            else:
                _say("mint", msg, "✓")
        except Exception as _ign:
            ignore("set_lang: aviso idioma", _ign)
    return code
_LOCALE_COMMA = frozenset({"pt", "fr", "de", "it", "ru", "pl"})
