def is_threads_link(link):
    """ÚNICA definición: True si el enlace es de Threads (host threads.net / threads.com, con o sin
    subdominio). Sin esquema, también vale threads.net/... hostname (no netloc): quita puerto,
    usuario y mayúsculas, y el sufijo con punto evita threads.net.evil.com / evilthreads.net."""
    try:
        s = str(link or "").strip()
        if not s:
            return False
        u = s if "://" in s else "https://" + s.lstrip("/")
        host = (urllib.parse.urlparse(u).hostname or "").lower()
        return host in ("threads.net", "threads.com") or host.endswith(".threads.net") or host.endswith(".threads.com")
    except Exception:
        return False
def is_threads_link_cases():
    """(enlace, esperado) para is_threads_link: 14 casos (positivos, subdominio, puerto, mayúsculas,
    ataques de sufijo y negativos)."""
    return [
        ("https://www.threads.net/@hexeofzakka/post/Df86YEuE_pC", True),
        ("https://threads.net/t/Df86YEuE_pC", True),
        ("https://www.threads.com/@hexeofzakka/post/Df86YEuE_pC", True),
        ("threads.net/@usuario/post/ABC", True),
        ("threads.com/t/ABC", True),
        ("https://sub.threads.net/@usuario/post/ABC", True),
        ("https://mobile.threads.com/t/ABC", True),
        ("https://THREADS.NET/@usuario/post/ABC", True),
        ("https://threads.net:443/@usuario/post/ABC", True),
        ("https://threads.net.evil.com/@usuario/post/ABC", False),
        ("https://evilthreads.net/@usuario/post/ABC", False),
        ("https://nthreads.net/@usuario/post/ABC", False),
        ("https://www.youtube.com/watch?v=ABC", False),
        ("", False),
    ]
def check_is_threads_link():
    """(ok, fallos): comprueba los 14 casos + None, sin red y sin levantar. fallos = [(enlace, esperado, obtenido), ...]."""
    fallos = []
    for link, want in is_threads_link_cases():
        try:
            got = is_threads_link(link)
        except Exception as _ign:
            got = f"excepción: {type(_ign).__name__}"
        if got is not want:
            fallos.append((link, want, got))
    try:
        got_none = is_threads_link(None)
    except Exception as _ign:
        got_none = f"excepción: {type(_ign).__name__}"
    if got_none is not False:
        fallos.append((None, False, got_none))
    return (not fallos, fallos)
def sc_list_args(args, mode=None):
    """1.9.9: con DLPY_DIRECT_LIST activo, --scb (también con raya larga o «=valor») se quita y la ejecución sigue el flujo de --shortcutpick sin valores
    (lista normal) o con v=more (lista completa): el script lista directo, con el estilo de la escena, y descarga. --scm no se toca aquí (ver sc_list_scm_json).
    Sin --scb, o apagado, devuelve `args` tal cual."""
    mode = sc_list_mode() if mode is None else mode
    if not mode:
        return list(args)
    out, hit, has_pick = [], False, False
    for a in args:
        name = a.lstrip("-\u2013\u2014").lower().split("=")[0] if a[:1] and a[:1] in "-\u2013\u2014" else ""
        if name == "scb":
            hit = True
            continue
        has_pick = has_pick or name == "shortcutpick"
        out.append(a)
    if not hit:
        return list(args)
    if not has_pick:
        out.append(SC_LIST_FLAG + ("=v=more" if mode == "all" else "="))
    return out
def sc_list_scm_json(link=None):
    """1.9.9 con DLPY_DIRECT_LIST activo --scm no analiza (corre en «Ejecutar comando», sin pantalla donde listar): responde al instante que el atajo siga con --scb, que sí abre a-Shell y lista ahí. No es error: `ok: True`, `status: "scb"`."""
    return {"dlpy": "shortcutmode", "schema": 1, "ok": True, "status": "scb", "version": VERSION, "link": link or "",
            "error_code": "sc_list", "message": "Lista directa: sigue con --scb.", "use_scb": True, "sc_list": sc_list_mode()}
def threads_scb_args(args):
    """2.0.8 + Threads en --scb: como DLPY_DIRECT_LIST, la lista abre directo en terminal (tipo 'more'):
    --scb se quita y la ejecucion sigue el flujo de --shortcutpick (lista normal). Sin --scb + Threads,
    devuelve los args tal cual."""
    try:
        has_scb = any(a[:1] in "-\u2013\u2014" and a.lstrip("-\u2013\u2014").lower().split("=")[0] == "scb" for a in args)
        has_threads = any(is_threads_link(a) for a in args)
        if not (has_scb and has_threads):
            return list(args)
        return sc_list_args(args, mode="short")
    except Exception:
        return list(args)
