def _subprocess_stream_kind(value, pipe, devnull, stdout_target=False):
    """Clasifica streams Popen admitidos; no degrada silenciosamente objetos de archivo."""
    import subprocess
    if value is None:
        return "inherit", None
    if value == pipe:
        return "pipe", None
    if value == devnull:
        return "devnull", None
    if stdout_target and value == subprocess.STDOUT:
        return "stdout", None
    raise NotImplementedError("a-Shell no admite este tipo de stream de subprocess: " + repr(value))
def run_tool(args, *, capture_output=False, text=False, timeout=None, input=None,
             stdin=None, stdout=None, stderr=None, cwd=None, encoding=None,
             errors=None, check=False, universal_newlines=None, shell=False, env=None,
             executable=None, **unsupported):
    """Adaptador de subprocess.run para herramientas integradas en a-Shell.

    iOS/a-Shell no puede crear procesos hijos normales. En su lugar usa ios_system/os.system,
    temporales dentro del sandbox y redirecciones del intérprete. `timeout` se acepta para
    compatibilidad de API, pero NO puede cancelar ios_system: las llamadas iOS deben ser locales
    y acotadas o usar el timeout propio de la herramienta (por ejemplo -rw_timeout de FFmpeg).
    Las opciones Popen que exigen crear/configurar un proceso hijo se rechazan explícitamente.
    Nota: `timeout` solo se conserva por compatibilidad; ios_system no ofrece cancelación de
    proceso desde esta capa. Por tanto, el llamador no debe usarlo como garantía de interrupción.
    """
    import subprocess
    if unsupported:
        raise NotImplementedError("Opciones de ejecución no compatibles: " + ", ".join(sorted(unsupported)))
    if not _in_ashell():
        return subprocess.run(args, capture_output=capture_output, text=text,
                              timeout=timeout, input=input, stdin=stdin, stdout=stdout,
                              stderr=stderr, cwd=cwd, encoding=encoding, errors=errors,
                              check=check, universal_newlines=universal_newlines,
                              shell=shell, env=env, executable=executable)
    if executable is not None:
        raise NotImplementedError("executable= no está soportado por ios_system")
    if capture_output and (stdout is not None or stderr is not None):
        raise ValueError("stdout/stderr no pueden combinarse con capture_output")
    text_mode = bool(text or universal_newlines or encoding or errors)
    if input is not None and stdin not in (None, subprocess.PIPE):
        raise ValueError("stdin no puede combinarse con input salvo subprocess.PIPE")
    if input is not None and not text_mode and isinstance(input, str):
        raise TypeError("input debe ser bytes cuando text=False")
    if capture_output:
        out_kind, err_kind = "pipe", "pipe"
    else:
        out_kind, _ = _subprocess_stream_kind(stdout, subprocess.PIPE, subprocess.DEVNULL, True)
        err_kind, _ = _subprocess_stream_kind(stderr, subprocess.PIPE, subprocess.DEVNULL, True)
    in_kind, _ = _subprocess_stream_kind(stdin, subprocess.PIPE, subprocess.DEVNULL)
    if input is not None:
        in_kind = "file"
    token = uuid.uuid4().hex
    base = os.path.join(WORK_ROOT, ".tool_" + token)
    os.makedirs(WORK_ROOT, exist_ok=True)
    out_file = base + ".out" if out_kind == "pipe" else ("/dev/null" if out_kind == "devnull" else None)
    err_file = base + ".err" if err_kind == "pipe" else ("/dev/null" if err_kind == "devnull" else None)
    in_file = base + ".in" if in_kind == "file" else ("/dev/null" if in_kind == "devnull" else None)
    try:
        if input is not None:
            payload = input.encode(encoding or "utf-8", errors or "strict") if isinstance(input, str) else bytes(input)
            with open(in_file, "wb") as fh:
                fh.write(payload)
        elif stdin == subprocess.PIPE:
            in_file = "/dev/null"
        rc = _ashell_run_argv(args, stdout_path=out_file, stderr_path=err_file,
                              stdin_path=in_file, cwd=cwd, stderr_to_stdout=(err_kind == "stdout"),
                              shell=shell, env=env)
        out = None
        err = None
        if out_kind == "pipe":
            with open(out_file, "rb") as fh:
                raw = fh.read()
            out = raw.decode(encoding or "utf-8", errors or "replace") if text_mode else raw
        if err_kind == "pipe":
            with open(err_file, "rb") as fh:
                raw = fh.read()
            err = raw.decode(encoding or "utf-8", errors or "replace") if text_mode else raw
        result = subprocess.CompletedProcess(args, rc, out, err)
        if timeout is not None:
            dbg("run_tool iOS: timeout no cancelable en ios_system", {"timeout": timeout, "command": str(args)[:120]})
        if check and rc:
            result.check_returncode()
        return result
    finally:
        for path in (out_file, err_file, in_file):
            if path and path != "/dev/null":
                with quiet("run_tool cleanup", OSError):
                    os.remove(path)
class _AShellThreadProcess:
    """Proceso cooperativo para mostrar progreso mientras ios_system ejecuta FFmpeg.

    a-Shell no ofrece a Python un Popen/PID normal. El comando se ejecuta una sola vez en un
    hilo; el hilo principal solo observa los ficheros -progress y de error. No se finge cancelación.
    """
    def __init__(self, args, stdout_path, stderr_path, cwd=None):
        self.args = args
        self.returncode = None
        self.error = None
        self._thread = threading.Thread(target=self._run,
            args=(args, stdout_path, stderr_path, cwd), name="dlpy-ios-tool", daemon=True)
        self._thread.start()
    def _run(self, args, stdout_path, stderr_path, cwd):
        try:
            self.returncode = _ashell_run_argv(args, stdout_path=stdout_path,
                                                stderr_path=stderr_path,
                                                stdin_path="/dev/null", cwd=cwd)
        except Exception as exc:
            self.error = exc
            self.returncode = 127
            try:
                with open(stderr_path, "a", encoding="utf-8") as fh:
                    fh.write("\nDLpy iOS command error: " + repr(exc))
            except OSError:
                pass
    def poll(self):
        return None if self._thread.is_alive() else self.returncode
    def wait(self, timeout=None):
        import subprocess
        self._thread.join(timeout)
        if self._thread.is_alive():
            raise subprocess.TimeoutExpired(self.args, timeout)
        return self.returncode
    def terminate(self):
        return None
def install_ytdlp_ashell_compat(yt_dlp):
    """Adapta yt-dlp Popen.run a ios_system, respetando shell, streams y el retorno de yt-dlp."""
    if not _in_ashell():
        return False
    try:
        from yt_dlp import utils as ytdlp_utils
        popen_cls = getattr(ytdlp_utils, "Popen", None)
        if popen_cls is None or getattr(popen_cls, "_dlpy_ashell_compat", False):
            return bool(popen_cls)
        def _ashell_popen_run(cls, *args, **kwargs):
            if not args:
                raise TypeError("Popen.run necesita argv")
            if len(args) > 1:
                raise NotImplementedError("Popen.run posicional adicional no soportado en a-Shell")
            command = args[0]
            timeout = kwargs.pop("timeout", None)
            input_data = kwargs.pop("input", None)
            text_mode = kwargs.pop("text", kwargs.pop("universal_newlines", False))
            stdout = kwargs.pop("stdout", None)
            stderr = kwargs.pop("stderr", None)
            stdin = kwargs.pop("stdin", None)
            cwd = kwargs.pop("cwd", None)
            encoding = kwargs.pop("encoding", None)
            errors = kwargs.pop("errors", None)
            shell = kwargs.pop("shell", False)
            env = kwargs.pop("env", None)
            executable = kwargs.pop("executable", None)
            if kwargs:
                raise NotImplementedError("Popen.run de yt-dlp pidió opciones no soportadas: " + ", ".join(sorted(kwargs)))
            text_mode = bool(text_mode or encoding or errors)
            result = run_tool(command, text=text_mode, timeout=timeout,
                              input=input_data, stdin=stdin, stdout=stdout,
                              stderr=stderr, cwd=cwd, encoding=encoding, errors=errors,
                              shell=shell, env=env, executable=executable)
            empty = "" if text_mode else b""
            return (result.stdout if result.stdout is not None else empty,
                    result.stderr if result.stderr is not None else empty,
                    result.returncode)
        popen_cls.run = classmethod(_ashell_popen_run)
        popen_cls._dlpy_ashell_compat = True
        return True
    except Exception as exc:
        ignore("install_ytdlp_ashell_compat", exc)
        return False
def native_clear(fallback=None, mode=None):
    """ÚNICO punto de borrado de la consola:"""
    if _scm_run() or not sys.stdout.isatty():
        return False
    if ux_on():
        return False
    ok = False
    try:
        sys.stdout.flush()
        mseq = clear_mode_seq(mode or CLEAR_MODE)
        if mseq is not None:
            sys.stdout.write(mseq)
            sys.stdout.flush()
            return True
        if NATIVE_CLEAR and not _NATIVE_CLEAR_BAD[0]:
            ok = sh_run("clear") == 0
            if not ok:
                _NATIVE_CLEAR_BAD[0] = True
        if not ok:
            sys.stdout.write(CLEAR_SEQ if fallback is None else fallback)
            sys.stdout.flush()
            ok = True
        if PURGE_SEQ:
            sys.stdout.write(PURGE_SEQ)
            sys.stdout.flush()
    except Exception:
        return False
    return ok
def wait_terminal_ready(timeout=3.0, force=False):
    """Desde un Atajo, a-Shell arranca el script antes de que su ventana tenga tamaño (ioctl 53x0, LINES=0)"""
    try:
        if not sys.stdout.isatty() or (_scm_run() and not force):
            return False
        end = time.monotonic() + timeout
        prev = None
        while True:
            cur = None
            for _st in (sys.stdout, sys.stderr, sys.stdin):
                try:
                    _sz = os.get_terminal_size(_st.fileno())
                except (OSError, ValueError, AttributeError):
                    continue
                cur = (_sz.columns, _sz.lines)
                break
            if cur is None:
                return False
            if cur[0] >= 20 and cur[1] >= 5 and cur == prev:
                return True
            if time.monotonic() >= end:
                return False
            prev = cur if (cur[0] >= 20 and cur[1] >= 5) else None
            time.sleep(POLL_TERM)
    except Exception:
        return False
