# ───────────────────── [UX0b] Compartido UX ↔ UIM: fundido + deslizamiento (antes ruido y glitch) ─────────────────────
SITE_GLITCH = "▒░#@%&$/\\|<>=+*"
GLITCH = _flag_env("DLPY_GLITCH_EFFECT", True)
def _fade_out(cell, q):
    """Celda que se apaga: mismo glifo, color hacia negro. q 0→1 en la ventana de fundido."""
    if cell is None or not cell[0] or not isinstance(cell[1], tuple):
        return cell
    q = max(0.0, min(1.0, float(q)))
    return (cell[0], mix(cell[1], BLACK, q), cell[2])
def _fade_in(cell, q):
    """Celda que entra: mismo glifo (el final, desde el principio), color desde negro. q 0→1."""
    if cell is None or not cell[0] or not isinstance(cell[1], tuple):
        return cell
    q = max(0.0, min(1.0, float(q)))
    return (cell[0], mix(BLACK, cell[1], q), cell[2])
def _rn(s):
    """Ruido determinista 0–1 (la intro se ve igual en cada ejecución)."""
    s = math.sin(s * 127.1) * 43758.5453
    return s - math.floor(s)
def _fg(c):
    return f"\x1b[38;2;{c[0]};{c[1]};{c[2]}m"
def _bg(c):
    return f"\x1b[48;2;{c[0]};{c[1]};{c[2]}m"
