def _hex_rgb(h):
    return tuple(int(h[i:i + 2], 16) for i in (1, 3, 5))
def site_theme(host, ext=""):
    """(nombre, sigla, color 1, color 2) del sitio. Los que no tienen diseño propio usan un color sacado del nombre."""
    for doms, name, sig, c1, c2 in SITE_THEMES:
        if _host_is(host, doms):
            return name, sig, _hex_rgb(c1), _hex_rgb(c2)
    import colorsys
    parts = [p for p in str(host).split(".") if p and p not in ("www", "m")]
    base = parts[-2] if len(parts) >= 2 else (parts[0] if parts else "")
    name = (str(ext or "").strip() or base or "Sitio")[:14]
    name = name[:1].upper() + name[1:]
    h = sum((i + 1) * ord(ch) for i, ch in enumerate(name.lower())) % 360
    def hls(hh, s, l):
        r, g_, b_ = colorsys.hls_to_rgb(hh / 360.0, l, s)
        return (int(r * 255), int(g_ * 255), int(b_ * 255))
    return name, name[:2].upper(), hls(h, 0.85, 0.60), hls((h + 40) % 360, 0.80, 0.76)
def _is_foto_src(*srcs):
    """True si los srcs son una foto (no un video): algún dict marca foto (_idmm_image / _carousel_kind foto / format_note foto)
    o todos los formatos son imagen con vcodec none (imagen directa), y ninguno trae vcodec de video de verdad. El poster de un
    video no cuenta: ese dict trae vcodec de video, así que un video nunca se marca como foto. Un carrusel mixto video+foto
    tampoco (trae video y foto a la vez)."""
    found, has_video = False, False
    def walk(d):
        nonlocal found, has_video
        if not isinstance(d, dict):
            return
        if d.get("_idmm_image") or d.get("_carousel_kind") == "foto" or str(d.get("format_note") or "").lower() == "foto":
            found = True
        vc = str(d.get("vcodec") or "none").lower()
        if vc not in ("none", "", "unknown") and not d.get("_idmm_image"):
            has_video = True
        fmts = d.get("formats") or []
        if fmts and all(isinstance(f, dict) and str(f.get("ext") or "").lower() in _DIRECT_IMAGE_EXTS
                        and str(f.get("vcodec") or "none").lower() in ("none", "", "unknown") for f in fmts):
            found = True
        for f in fmts:
            walk(f)
    for s in srcs:
        walk(s)
    return found and not has_video
def site_mode(run):
    """Qué se baja: live, list, foto, audio, both (video con audio) o video (sin audio)."""
    info = getattr(run, "info", None)
    if info is None:
        if getattr(run, "is_foto", False):
            return "foto"
        v = str((getattr(run, "spick", None) or {}).get("v") or "").lower()
        return "audio" if v in ("audio", "audio_best") else "both"
    if info.get("is_live"):
        return "live"
    if (info.get("n_entries") or 0) > 1:
        return "list"
    if getattr(run, "is_foto", False) or _is_foto_src(getattr(run, "fmt", None), info):
        return "foto"
    if getattr(run, "kind", None) == "a":
        return "audio"
    if getattr(run, "selected", None) or has((getattr(run, "fmt", None) or {}).get("acodec")):
        return "both"
    return "video"
def site_theme_apply(run):
    """Fija (una sola vez por ejecución)"""
    if THEME["full"] is not None:
        return THEME["full"]
    if not (SITE_ANIM and USE_COLOR and TRUECOLOR):
        return None
    info = getattr(run, "info", None) or {}
    full = site_theme(_host(run.link), info.get("extractor_key") or info.get("extractor") or "")
    THEME["full"], THEME["a"], THEME["b"] = full, full[2], full[3]
    return full
def reset_site_state():
    """Entre dos descargas seguidas (menú de pendientes): la siguiente vuelve a elegir tema y etiqueta."""
    SESSION["tag"] = None
    THEME["a"] = THEME["b"] = THEME["full"] = None
def early_site_intro(run):
    """--shortcutpick:"""
    try:
        if getattr(run, "spick", None) is None:
            return
        args = getattr(run, "cli_args", None) or []
        if not args or not str(args[0]).strip():
            return
        link = str(args[0]).strip()
        run.link = link
        if scene_start(run):
            run.site_shown = True
            return
        was_quiet = QUIET["on"]
        if was_quiet:
            quiet_set(False)
        try:
            if site_intro(run):
                run.site_shown = True
        finally:
            if was_quiet:
                quiet_set(True)
    except KeyboardInterrupt:
        raise
    except Exception as _ign:
        ignore("early_site_intro", _ign)
