def conv_flow(gap):
    """1.6.3: celdas por segundo de los paquetes de la conversión para que crucen una vía de `gap` celdas en CONV_TRAVEL (nunca menos de CONV_FLOW)."""
    return max(CONV_FLOW, float(gap) / CONV_TRAVEL)
