class _SceneMute:
    """Envoltura de sys.stdout:"""
    def __init__(self, inner):
        self._inner = inner
        self.open = False
    def write(self, text):
        if self.open:
            return self._inner.write(text)
        return len(text) if text else 0
    def writelines(self, lines):
        for ln in lines:
            self.write(ln)
    def flush(self):
        if self.open:
            return self._inner.flush()
        return None
    def __getattr__(self, name):
        return getattr(self._inner, name)
class _SceneErrMute:
    """1.0.8: con la escena viva, stderr va al log, no a la pantalla."""
    def __init__(self, inner):
        self._inner = inner
        self.open = False
        self._buf = ""
        self._lock = threading.RLock()
    def write(self, text):
        if self.open:
            return self._inner.write(text)
        if not text:
            return 0
        with self._lock:
            *lines, self._buf = (self._buf + str(text).replace("\r", "\n")).split("\n")
        for ln in lines:
            ln = _ANSI_RE.sub("", ln).strip()
            if ln:
                log_shortcutmode_stderr("stderr: " + ln)
        return len(text)
    def writelines(self, lines):
        for ln in lines:
            self.write(ln)
    def drain(self):
        """Lo que quedó sin salto de línea también va al log."""
        with self._lock:
            rest, self._buf = _ANSI_RE.sub("", self._buf).strip(), ""
        if rest:
            log_shortcutmode_stderr("stderr: " + rest)
    def flush(self):
        if self.open:
            return self._inner.flush()
        return None
    def __getattr__(self, name):
        return getattr(self._inner, name)
def frame_gap(t, fps):
    """1.9.8: s hasta el siguiente límite de cuadro de un reloj que lleva `t` s a `fps` cuadros por segundo (entre 0,5 ms y un cuadro)."""
    fps = max(1.0, float(fps))
    return max(0.0005, min(1.0 / fps, (math.floor(t * fps + 1e-9) + 1) / fps - t))
def scene_refresh_slice(st, ymax, fps, period=0.35):
    """1.9.8: repintado de seguridad repartido: invalida unas pocas filas por cuadro (en rotación) y todas en `period` s, en vez de borrar toda la pantalla de golpe.
    2.0.8: con acumulador (filas fraccionarias por cuadro): a 60 fps y period largo toca una fila cada pocos cuadros, no una por cuadro. Devuelve las filas invalidadas."""
    ymax = max(1, int(ymax))
    acc = float(st.get("racc", 0.0)) + ymax / max(1.0, period * fps)
    n = int(acc)
    st["racc"] = acc - n
    cur = st.get("rcur", 1)
    for i in range(n):
        st["rows"].pop((cur - 1 + i) % ymax + 1, None)
    if n:
        st["rcur"] = (cur - 1 + n) % ymax + 1
    return n
def scene_ease(cur, tgt, rate, dt):
    """1.0.6:"""
    dt = max(0.0, min(0.25, float(dt)))
    return cur + (tgt - cur) * (1.0 - math.exp(-rate * dt))
