def is_bot_error(e):
    t = str(e).lower()
    return "not a bot" in t or "sign in to confirm" in t
def explain_bot_error():
    """Avisa del error de «no eres un bot» (repetir el intento no ayuda)."""
    m_err("YouTube pide comprobar que no eres un bot; no se puede analizar este enlace.")
    note("Actualiza yt-dlp (pip install -U yt-dlp) o inténtalo más tarde.")
def cli_like_opts(yt_dlp, argv):
    """Opciones de YoutubeDL que produciría la CLI de yt-dlp con `argv` (mismos valores por defecto:"""
    try:
        o = dict(yt_dlp.parse_options(list(argv)).ydl_opts)
    except (Exception, SystemExit) as e:
        dbg("parse_options falló", str(e))
        return None
    for k in _CLI_DROP:
        o.pop(k, None)
    return o
def user_argv():
    """Banderas extra de yt-dlp en bruto (DLPY_YTDLP_EXTRA_ARGS)."""
    raw = os.environ.get("DLPY_YTDLP_EXTRA_ARGS", "").strip()
    try:
        mine = shlex.split(raw) if raw else []
    except ValueError as e:
        m_warn(f"DLPY_YTDLP_EXTRA_ARGS inválido: {e}")
        mine = []
    return mine + js_runtime_args(mine)
ANALYSIS = {"stage": None, "t": None}
_IDMM_INFO_CACHE = {}
_CAROUSEL_INFO_CACHE = {}
def _carousel_cache_key(link):
    """clave del cache general del carrusel: el enlace base sin #dlpy_carousel=N (normalizado si es IDMM, tal cual si no)."""
    try:
        if is_idmm_link(link):
            return idmm_normalize_link(link)
    except Exception:
        pass
    return str(link or '').strip().split('#dlpy_carousel=')[0].split('#')[0].strip()
# --- 2.0.8 + Threads + carrusel mixto (video + foto) ---
def idmm_img_ext(url):
    """2.0.8 + Threads: extension de una foto (jpg por omision). 2.0.8 + imagen directa: tambien
    gif/bmp/tif/tiff/svg/heic/heif."""
    try:
        p = urllib.parse.urlparse(str(url or "")).path.lower()
        for e in (".jpg", ".jpeg", ".png", ".webp", ".avif", ".gif", ".bmp", ".tiff", ".tif", ".svg", ".heic", ".heif"):
            if p.endswith(e):
                return "jpg" if e == ".jpeg" else e.lstrip(".")
    except Exception:
        pass
    return "jpg"
_DIRECT_IMAGE_EXTS = ("jpg", "jpeg", "png", "webp", "gif", "avif", "bmp", "tif", "tiff", "svg", "heic", "heif")
_DIRECT_IMAGE_CT = {"image/jpeg": "jpg", "image/png": "png", "image/webp": "webp", "image/gif": "gif",
                    "image/avif": "avif", "image/bmp": "bmp", "image/x-ms-bmp": "bmp",
                    "image/tiff": "tiff", "image/svg+xml": "svg", "image/heic": "heic", "image/heif": "heif"}
def _direct_image_head_ext(url):
    """2.0.8 + imagen directa: extension por HEAD (Content-Type: image/*). None si no es imagen
    o falla. Solo se usa cuando la URL no trae extension (Discord, ?format=jpg, ...)."""
    try:
        import urllib.request
        req = urllib.request.Request(str(url), method="HEAD", headers={
            "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1",
            "Accept": "image/*,*/*;q=0.8"})
        with urllib.request.urlopen(req, timeout=10) as r:
            ct = (r.headers.get("Content-Type") or "").split(";")[0].strip().lower()
            return _DIRECT_IMAGE_CT.get(ct)
    except Exception:
        return None
def _direct_image_info(link, check_head=False):
    """2.0.8 + imagen directa: info estilo foto para una URL que ES una imagen, de cualquier sitio."""
    try:
        s = str(link or "").strip().split("#dlpy_carousel=")[0].split("#")[0]
        if not s or "://" not in s:
            return None
        u = urllib.parse.urlparse(s)
        if u.scheme not in ("http", "https") or not u.netloc:
            return None
        path = (u.path or "/").rstrip("/")
        ext = None
        for e in _DIRECT_IMAGE_EXTS:
            if path.lower().endswith("." + e):
                ext = "jpg" if e == "jpeg" else e
                break
        if ext is None and check_head:
            ext = _direct_image_head_ext(s)
        if ext is None:
            return None
        base = urllib.parse.unquote(os.path.basename(path) or "")
        if "." in base:
            base = base.rsplit(".", 1)[0]
        title = base or "imagen"
        return {"id": title, "title": title, "extractor_key": "DirectImage", "extractor": "DirectImage",
                "webpage_url": s, "original_url": str(link or ""), "webpage_url_domain": u.netloc,
                "uploader": "", "channel": "",
                "formats": [{"format_id": "img", "ext": ext, "vcodec": "none", "acodec": "none",
                             "width": None, "height": None, "url": s, "filesize": None, "protocol": "https",
                             "format_note": "imagen directa", "resolution": "imagen",
                             "_idmm_image": True, "_direct_image": True}],
                "thumbnails": [{"url": s}], "description": title, "duration": None}
    except Exception:
        return None
def is_threads_login_error(e):
    """2.0.8 + Threads: True si el error es login / privado."""
    low = str(e or "").lower()
    return any(k in low for k in ("login", "iniciar sesion", "iniciar sesión", "sign in", "private", "privado", "403", "forbidden", "cookies"))
def threads_normalize_link(link):
    """2.0.8 + Threads: Compartir -> forma que yt-dlp entiende.
    Ej: https://www.threads.com/@hexeofzakka/post/Df86YEuE_pC?xmt=...&slof=1
    ->  https://www.threads.net/@hexeofzakka/post/Df86YEuE_pC
    Quita ?xmt / &slof / #..., pasa threads.com -> threads.net y deja solo /@usuario/post/ID o /t/ID.
    """
    s = str(link or "").strip().strip("<>\"' ")
    if not s or not is_threads_link(s):
        return s
    s = s.split("#dlpy_carousel=")[0].split("#")[0]
    try:
        u = urllib.parse.urlparse(s if "://" in s else "https://" + s)
    except Exception:
        return s
    path = u.path or "/"
    m = re.match(r"^/(@[^/]+/post/[^/]+)(?:/.*)?$", path)
    if m:
        path = "/" + m.group(1)
    else:
        m2 = re.match(r"^/(t/[^/]+)(?:/.*)?$", path)
        if m2:
            path = "/" + m2.group(1)
        else:
            path = path.rstrip("/") or "/"
    return "https://www.threads.net" + path
def idmm_carousel_index(link):
    """2.0.8 + carrusel: N de '#dlpy_carousel=N' en un enlace sintetico de la cola (0 si no hay)."""
    try:
        m = re.search(r"#dlpy_carousel=(\d+)", str(link or ""))
        return int(m.group(1)) if m else 0
    except Exception:
        return 0
def is_unsupported_url_error(e):
    """2.0.8 + Threads: True si yt-dlp dijo Unsupported URL (ningun extractor casa con el enlace)."""
    return "unsupported url" in str(e or "").lower()
def explain_threads_unsupported(link):
    """2.0.8 + Threads: que hacer cuando ni yt-dlp ni el lector nativo pudieron leer el hilo."""
    norm = threads_normalize_link(link)
    m_err("Ni yt-dlp ni DLpy pudieron leer este hilo de Threads.")
    if norm and norm != str(link or "").strip():
        note(f"DLpy ya lo limpio a: {norm}")
    note("Puede ser privado, borrado, o que Threads pida iniciar sesion. Con DLPY_COOKIES_FILE apunta a un cookies.txt de threads.net.")
    note("Si el hilo es publico, actualiza yt-dlp: pip install -U yt-dlp (o --actualizar en DLpy) y vuelve a pegar el enlace.")
def idmm_cd_filename(cd):
    """2.0.8 + nombre original: nombre de Content-Disposition (threads.py): filename*=UTF-8''... o filename="..."."""
    try:
        if not cd:
            return None
        m = re.search(r"filename\*=UTF-8''([^;]+)", str(cd), re.IGNORECASE)
        if m:
            return m.group(1)
        m = re.search(r'filename="?([^";]+)"?', str(cd), re.IGNORECASE)
        if m:
            return m.group(1)
        return None
    except Exception:
        return None
def idmm_original_filename(raw, fallback_stem, target_ext):
    """2.0.8 + nombre original: el nombre ORIGINAL del archivo (threads.py): Content-Disposition o
    basename de la URL del CDN, sanitizado. Si la URL no trae nombre, respaldo = fallback_stem
    (el titulo, como antes). Ej: .../123456789_n.jpg?stp=... -> 123456789_n.jpg"""
    try:
        import unicodedata
        import urllib.parse
        _raw = str(raw or "")
        if "://" in _raw:
            _raw = os.path.basename(urllib.parse.urlparse(_raw).path)
        decoded = urllib.parse.unquote(_raw).strip()
        stem = os.path.splitext(os.path.basename(decoded))[0]
        stem = unicodedata.normalize("NFKC", stem)
        stem = re.sub(r"[^A-Za-z0-9._-]+", "_", stem)
        stem = re.sub(r"_+", "_", stem).strip("._-")
        if not stem:
            stem = str(fallback_stem or "threads_media")
        encoded = stem.encode("utf-8")
        if len(encoded) > 100:
            stem = encoded[:100].decode("utf-8", errors="ignore").rstrip("._-")
        if not stem:
            stem = str(fallback_stem or "threads_media")
        return f"{stem}.{target_ext}"
    except Exception:
        return f"{fallback_stem}.{target_ext}"
def idmm_unique_dest(work_dir, filename):
    """2.0.8 + nombre original: ruta unica en work_dir (threads.py get_unique_filepath): si existe, _1, _2..."""
    try:
        cand = os.path.join(work_dir, filename)
        if not os.path.exists(cand):
            return cand
        stem, ext = os.path.splitext(filename)
        n = 1
        while True:
            cand = os.path.join(work_dir, f"{stem}_{n}{ext}")
            if not os.path.exists(cand):
                return cand
            n += 1
    except Exception:
        return os.path.join(work_dir, filename)
def idmm_auto_pick(run):
    """2.0.8 + carrusel "t": (kind, fmt, raw) para un medio encolado, sin preguntar. Foto: su unico
    formato. Video: el mejor (auto_best). None si no hay formatos. Asi "t" baja TODOS, no solo el primero."""
    try:
        videos = list(getattr(run, "videos", None) or [])
        audios = list(getattr(run, "audios", None) or [])
        if getattr(run, "is_foto", False):
            if videos:
                return ("v", videos[0], "carrusel:auto")
            return None
        if videos:
            try:
                _ab = auto_best(audios, videos, getattr(run, "orig_ids", None), getattr(run, "can_merge", True))
            except Exception:
                _ab = None
            if _ab:
                return (_ab[0], _ab[1], "carrusel:auto")
            return ("v", max(videos, key=lambda f: (f.get("height") or 0, f.get("tbr") or 0)), "carrusel:auto")
        if audios:
            return ("a", audios[-1], "carrusel:auto")
        return None
    except Exception:
        return None
def idmm_download_media(url, dest, cookies_file=None):
    """2.0.8 + Threads: baja foto o video nativo por HTTP directo (con cookies.txt si lo hay). En streaming.
    Devuelve (ok, nombre_de_Content-Disposition o None) para guardar con el nombre original."""
    import http.cookiejar
    import urllib.request
    cj = None
    if cookies_file and os.path.isfile(str(cookies_file)):
        try:
            cj = http.cookiejar.MozillaCookieJar(str(cookies_file))
            cj.load(ignore_discard=True, ignore_expires=True)
        except Exception as _ign:
            ignore("threads_media_cookies", _ign)
            cj = None
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj) if cj else urllib.request.HTTPHandler())
    _ref = "https://www.instagram.com/" if "cdninstagram.com" in str(url) else "https://www.threads.net/"
    req = urllib.request.Request(str(url), headers={
        "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 17_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/17.0 Mobile/15E148 Safari/604.1",
        "Accept": "*/*",
        "Referer": _ref,
    })
    total = 0
    _cd_name = None
    with opener.open(req, timeout=60) as r:
        try:
            _cd = r.headers.get("Content-Disposition", "") if hasattr(r, "headers") else ""
        except Exception:
            _cd = ""
        if _cd:
            _cd_name = idmm_cd_filename(_cd)
        with open(dest, "wb") as fh:
            while True:
                chunk = r.read(1024 * 256)
                if not chunk:
                    break
                fh.write(chunk)
                total += len(chunk)
    if total <= 0:
        raise ValueError("archivo vacio")
    return (os.path.isfile(dest) and os.path.getsize(dest) > 0), _cd_name
def _threads_unescape(s):
    """Desescapa el HTML/JSON de Threads. 2.0.8 + entidades: og:title viene como &#x5c0f;&#x5e03;&#x4e01;&#x1f36e; (&#064;pudding10.14) y se mostraba tal cual. html.unescape PRIMERO (asi &amp;copy queda &copy; literal, no ©: doble decodificacion)."""
    s = str(s or "")
    try:
        import html as _html
        s = _html.unescape(s)
    except Exception:
        pass
    s = s.replace("\\/", "/").replace("\\u0026", "&").replace("\\u002F", "/").replace("&amp;", "&")
    s = s.replace('\\"', '"').replace("\\'", "'")
    return s
def _threads_variant_dims(block, um_start, um_end):
    """2.0.8 + carrusel: width/height del MISMO objeto JSON que la URL (no del bloque vecino).
    En video_versions cada variante es {"url": ..., "width": ..., "height": ...}. Buscar hacia
    atras cogia la variante anterior (720p en vez de 1080p) y elegia mal la mejor calidad.
    """
    try:
        fwd = block[um_end:um_end + 300]
        nxt = fwd.find('"url"')
        if nxt != -1:
            fwd = fwd[:nxt]
        wm = re.search(r'"width"\s*:\s*(\d+)', fwd)
        hm = re.search(r'"height"\s*:\s*(\d+)', fwd)
        if wm and hm:
            w, h = int(wm.group(1)), int(hm.group(1))
            if 0 < w <= 10000 and 0 < h <= 10000:
                return w, h
        bwd = block[max(0, um_start - 300):um_start]
        prev = bwd.rfind('"url"')
        if prev != -1:
            bwd = bwd[prev:]
        wm = re.search(r'"width"\s*:\s*(\d+)', bwd)
        hm = re.search(r'"height"\s*:\s*(\d+)', bwd)
        if wm and hm:
            w, h = int(wm.group(1)), int(hm.group(1))
            if 0 < w <= 10000 and 0 < h <= 10000:
                return w, h
    except Exception:
        pass
    return 0, 0
def _threads_near_dims(html, pos):
    """2.0.8 + Threads nativo: width/height cerca de una URL dentro del JSON (0,0 si no hay)."""
    try:
        win = html[max(0, pos - 400):pos + 400]
        wm = re.search(r'"width"\s*:\s*(\d+)', win)
        hm = re.search(r'"height"\s*:\s*(\d+)', win)
        w = int(wm.group(1)) if wm else 0
        h = int(hm.group(1)) if hm else 0
        if w > 10000 or h > 10000:
            return 0, 0
        return w, h
    except Exception:
        return 0, 0
def _threads_meta_content(html, prop):
    """2.0.8 + Threads nativo: content de <meta property=prop ...> o <meta content=... property=prop>."""
    for pat in (r'<meta[^>]+property=["\']' + re.escape(prop) + r'["\'][^>]+content=["\']([^"\']+)["\']',
                r'<meta[^>]+content=["\']([^"\']+)["\'][^>]+property=["\']' + re.escape(prop) + r'["\']'):
        m = re.search(pat, html, re.IGNORECASE)
        if m:
            return _threads_unescape(m.group(1)).strip()
    return ""
def idmm_dedup_key(url):
    """2.0.8 + Threads sin repetir: clave de un medio por RUTA del CDN, sin host ni query.
    El mismo medio lo sirve Threads desde varios hosts (scontent-mia3-1 / -2 / -3...) y con
    distinto ?... Dedup por URL exacta no los ve como el mismo y el carrusel lo contaba 2 veces.
    La ruta (/v/t51.2885-15/.../12345_n.jpg) si es unica por medio. Se quita el sufijo de tamano
    como en _threads_media_key, para que 2 calidades del mismo medio compartan clave.
    """
    try:
        path = urllib.parse.urlparse(str(url or "")).path or str(url or "").split("?")[0]
        stem, ext = os.path.splitext(path)
        stem = re.sub(r"[_\-](\d{2,4}x\d{2,4}|\d{3,4}p|\d{3,4})$", "", stem)
        stem = re.sub(r"_n$", "", stem)
        return stem + ext
    except Exception:
        return str(url or "")
def idmm_media_key(url):
    """2.0.8 + fix sobre-deteccion: clave del medio, sin tamano ni query.
    v1_720.mp4 y v1_1080.mp4 son el MISMO video (dos calidades). p1_1080.jpg es otro medio.
    Se quita ?... y sufijos _720 / -1080x1920 / _n, para que dos bloques del mismo medio (repetido
    en el HTML) o dos calidades del mismo video compartan clave y no se cuenten como 2 medios.
    """
    try:
        base = str(url or "").split("?")[0].split("#")[0]
        stem, ext = os.path.splitext(base)
        stem = re.sub(r"[_\-](\d{2,4}x\d{2,4}|\d{3,4}p|\d{3,4})$", "", stem)
        stem = re.sub(r"_n$", "", stem)
        return stem + ext
    except Exception:
        return str(url or "")
def _threads_gap_is_new_object(gap):
    """2.0.8 + fix sobre-deteccion: True si entre dos bloques hay un cambio de objeto JSON.
    Mismo objeto (poster del video): hueco = ", " o "}, " (una sola llave de cierre, sin "{" detras).
    Objeto nuevo (siguiente medio del carrusel): hueco con "}, {" , "}},", "}], [" o un "id"/"pk" nuevo.
    """
    try:
        g = str(gap or "")
        if re.search(r"\}\s*,\s*\{", g):
            return True
        if re.search(r"\}\}\s*,", g):
            return True
        if re.search(r"\}\s*\]\s*,\s*\[", g):
            return True
        if len(g) > 3000:
            return True
        return False
    except Exception:
        return False
def _threads_bad_url(u):
    """2.0.8 + Threads nativo: avatar / logo / icono, no es media del hilo."""
    low = str(u or "").lower()
    return any(k in low for k in ("profile_pic", "avatar", "sprite", "logo", "icon", "emoji",
                                  "profilepic", "/pp_", "150x150", "100x100", "48x48", "favicon",
                                  "t51.2885-19"))
def _threads_find_post_node(obj, target_code):
    """Port de threads.py find_post_node: busca EL post por su code, no cualquier medio del HTML.
    Recursivo: si un dict tiene code == target_code y trae media, es el post. Si no, baja por valores/listas.
    Sin target_code: primer nodo con carousel_media (el carrusel del post principal).
    Esto es lo que evita contar medios de otros hilos, relacionados, avatares o duplicados del HTML.
    """
    try:
        if isinstance(obj, dict):
            if target_code and obj.get("code") == target_code:
                if any(k in obj for k in ("carousel_media", "video_versions", "image_versions2")):
                    return obj
            if not target_code and obj.get("carousel_media"):
                return obj
            for val in obj.values():
                found = _threads_find_post_node(val, target_code)
                if found:
                    return found
        elif isinstance(obj, list):
            for item in obj:
                found = _threads_find_post_node(item, target_code)
                if found:
                    return found
    except Exception as _ign:
        diagnostic_report("A", f"Threads: buscar nodo del post: {type(_ign).__name__}: {_ign}")
        pass
    return None
def _threads_json_items(html, target_code):
    """Port de threads.py extract_media_from_json: [{kind, variants}] desde el JSON del post, no regex.
    1) Saca los <script type="application/json"> y hace json.loads de cada uno.
    2) Busca el nodo del post por code.
    3) items = carousel_media o [post_node] (1 item = 1 medio, el carrusel ya viene separado).
    4) Por item: SI tiene video_versions -> video (su image_versions2 es el poster, se ignora);
       ELIF tiene image_versions2 -> foto. El if/elif es lo que impide contar el poster como foto.
    Devuelve [] si no hay nodo (quien llama cae a og:, no a escanear todo el HTML).
    """
    try:
        raw = str(html or "")
        scripts = re.findall(r'<script[^>]*type=["\']application/json["\'][^>]*>(.*?)</script>',
                             raw, flags=re.DOTALL | re.IGNORECASE)
        post_node = None
        for raw_json in scripts:
            for _cand in (raw_json, html.unescape(raw_json) if hasattr(html, "unescape") else raw_json):
                try:
                    data = json.loads(_cand)
                except Exception:
                    continue
                post_node = _threads_find_post_node(data, target_code)
                if post_node:
                    break
            if post_node:
                break
        if not post_node:
            _all_scripts = re.findall(r"<script[^>]*>(.*?)</script>", raw, flags=re.DOTALL | re.IGNORECASE)
            for raw_json in _all_scripts:
                if raw_json in scripts:
                    continue
                for _cand in (raw_json, html.unescape(raw_json) if hasattr(html, "unescape") else raw_json):
                    try:
                        data = json.loads(_cand)
                    except Exception:
                        continue
                    post_node = _threads_find_post_node(data, target_code)
                    if post_node:
                        break
                if post_node:
                    break
        if not post_node:
            return []
        items = post_node.get("carousel_media") or [post_node]
        out, seen = [], set()
        for item in items:
            if not isinstance(item, dict):
                continue
            video_versions = item.get("video_versions") or []
            image_candidates = (item.get("image_versions2") or {}).get("candidates") or []
            if video_versions:
                variants = []
                for v in video_versions:
                    url = (v or {}).get("url") or ""
                    if url.startswith("http") and not _threads_bad_url(url):
                        variants.append({"url": url, "width": (v or {}).get("width") or None,
                                         "height": (v or {}).get("height") or None})
                if variants:
                    best_url = max(variants, key=lambda x: ((x.get("width") or 0) * (x.get("height") or 0)))["url"]
                    _dk = idmm_dedup_key(best_url)
                    if _dk not in seen:
                        seen.add(_dk)
                        out.append({"kind": "video", "variants": variants})
            elif image_candidates:
                variants = []
                for v in image_candidates:
                    url = (v or {}).get("url") or ""
                    if url.startswith("http") and not _threads_bad_url(url):
                        variants.append({"url": url, "width": (v or {}).get("width") or None,
                                         "height": (v or {}).get("height") or None})
                if variants:
                    best_url = max(variants, key=lambda x: ((x.get("width") or 0) * (x.get("height") or 0)))["url"]
                    _dk = idmm_dedup_key(best_url)
                    if _dk not in seen:
                        seen.add(_dk)
                        out.append({"kind": "foto", "variants": variants})
        return out
    except Exception:
        return []
def threads_parse_carousel(html, target_code=None):
    """2.0.8 + carrusel mixto: [{kind, variants:[{url,width,height}]}] en el orden del hilo.
    Cada bloque video_versions = 1 video (sus variantes son calidades, NO medios distintos).
    Cada bloque image_versions2 = 1 foto (sus candidates son calidades).
    Se escanean ambos tipos en orden de aparicion, asi un carrusel video+foto+video queda en orden.
    FIX sobre-deteccion (2.0.8):
    - Poster: cada video trae ADEMAS un image_versions2 con su miniatura DENTRO del mismo objeto
      JSON. Ese bloque NO es una foto aparte: se descarta si esta pegado a un video del mismo objeto
      (hueco sin cambio de objeto, ver _threads_gap_is_new_object).
    - Duplicados: el mismo medio aparece varias veces en el HTML (Relay, __NEXT_DATA__, embeds).
      Dos bloques que comparten clave de medio (misma URL base / mismo v1_720+v1_1080) se fusionan,
      no se cuentan como 2 medios.
    - og:image: si hay og:video, og:image es su poster, no una foto aparte.
    Sin bloques: respaldo con og:video / og:image, o URLs de CDN sueltas (con dedup por clave).
    """
    _json_items = _threads_json_items(html, target_code)
    if _json_items:
        return _json_items
    if target_code:
        _html_og = _threads_unescape(str(html or ""))
        _og_v = _threads_meta_content(_html_og, "og:video")
        if _og_v and not _threads_bad_url(_og_v):
            _w, _h = _threads_near_dims(_html_og, _html_og.find(_og_v))
            return [{"kind": "video", "variants": [{"url": _og_v, "width": _w or None, "height": _h or None}]}]
        _og_i = _threads_meta_content(_html_og, "og:image") or _threads_meta_content(_html_og, "og:image:url")
        _og_type = _threads_meta_content(_html_og, "og:type") or ""
        if _og_i and not _threads_bad_url(_og_i) and "video" not in _og_type.lower():
            return [{"kind": "foto", "variants": [{"url": _og_i, "width": None, "height": None}]}]
        return []
    raw = str(html or "")
    html = _threads_unescape(raw)
    raw_blocks = []
    for m in re.finditer(r'"video_versions"\s*:\s*\[(.*?)\]|"image_versions2"\s*:\s*\{\s*"candidates"\s*:\s*\[(.*?)\]', html, re.DOTALL):
        block = m.group(1) if m.group(1) is not None else m.group(2)
        kind = "video" if m.group(1) is not None else "foto"
        variants, seen = [], set()
        for um in re.finditer(r'"url"\s*:\s*"([^"]+)"', block or ""):
            url = um.group(1).strip().split('"')[0].split("'")[0]
            if not url.startswith("http") or _threads_bad_url(url):
                continue
            key = url.split("?")[0]
            if key in seen:
                continue
            seen.add(key)
            w, h = _threads_variant_dims(block or "", um.start(), um.end())
            variants.append({"url": url, "width": w or None, "height": h or None})
        if variants:
            raw_blocks.append({"kind": kind, "variants": variants, "start": m.start(), "end": m.end(),
                               "keys": {idmm_media_key(v["url"]) for v in variants}})
    kept = []
    for b in raw_blocks:
        dup = None
        for k in kept:
            if k["kind"] == b["kind"] and (k["keys"] & b["keys"]):
                dup = k
                break
        if dup is not None:
            have = {v["url"].split("?")[0] for v in dup["variants"]}
            for v in b["variants"]:
                if v["url"].split("?")[0] not in have:
                    dup["variants"].append(v)
                    have.add(v["url"].split("?")[0])
            dup["keys"] |= b["keys"]
            continue
        kept.append(dict(b))
    items = []
    for i, b in enumerate(kept):
        if b["kind"] == "foto":
            is_poster = False
            if i > 0 and kept[i - 1]["kind"] == "video":
                gap = html[kept[i - 1]["end"]:b["start"]]
                if not _threads_gap_is_new_object(gap):
                    is_poster = True
            if not is_poster and i + 1 < len(kept) and kept[i + 1]["kind"] == "video":
                gap = html[b["end"]:kept[i + 1]["start"]]
                if not _threads_gap_is_new_object(gap):
                    is_poster = True
            if is_poster:
                if i > 0 and kept[i - 1]["kind"] == "video":
                    kept[i - 1].setdefault("poster", b["variants"])
                elif i + 1 < len(kept) and kept[i + 1]["kind"] == "video":
                    kept[i + 1].setdefault("poster", b["variants"])
                continue
        items.append({"kind": b["kind"], "variants": b["variants"],
                      **({"poster": b["poster"]} if b.get("poster") else {})})
    if items:
        return items
    og_v = _threads_meta_content(html, "og:video")
    og_i = _threads_meta_content(html, "og:image") or _threads_meta_content(html, "og:image:url")
    if og_v and not _threads_bad_url(og_v):
        w, h = _threads_near_dims(html, html.find(og_v))
        return [{"kind": "video", "variants": [{"url": og_v, "width": w or None, "height": h or None}]}]
    _og_type2 = _threads_meta_content(html, "og:type") or ""
    if og_i and not _threads_bad_url(og_i) and "video" not in _og_type2.lower():
        return [{"kind": "foto", "variants": [{"url": og_i, "width": None, "height": None}]}]
    seen_keys = set()
    for um in re.finditer(r'https://[A-Za-z0-9._\-/]+(?:cdn|fbcdn|scontent)[^"\'\s\\]*\.(?:mp4|jpg|jpeg|png|webp)(?:\?[^"\'\s\\]*)?', html):
        url = um.group(0)
        if _threads_bad_url(url):
            continue
        key = idmm_media_key(url)
        if key in seen_keys:
            continue
        seen_keys.add(key)
        kind = "video" if ".mp4" in url.lower() else "foto"
        w, h = _threads_near_dims(html, um.start())
        items.append({"kind": kind, "variants": [{"url": url, "width": w or None, "height": h or None}]})
    return items
def threads_fetch_html(url, cookies_file=None, user_agent="browser"):
    """2.0.8 + Threads nativo: HTML del hilo (sigue redirecciones, con cookies.txt si lo hay). Devuelve (html, url_final).
    Headers como threads.py (iPhone iOS 18, en-US). user_agent="bot" usa facebookexternalhit/1.1,
    el segundo intento de threads.py: a los bots Threads les sirve og:video aunque pida login.
    """
    import http.cookiejar
    import urllib.request
    import urllib.error
    cj = None
    if cookies_file and os.path.isfile(str(cookies_file)):
        try:
            cj = http.cookiejar.MozillaCookieJar(str(cookies_file))
            cj.load(ignore_discard=True, ignore_expires=True)
        except Exception as _ign:
            ignore("threads_fetch_cookies", _ign)
            cj = None
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj) if cj else urllib.request.HTTPHandler())
    if user_agent == "bot":
        _headers = {"User-Agent": "facebookexternalhit/1.1"}
    else:
        _headers = {
            "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1",
            "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            "Accept-Language": "en-US,en;q=0.9",
            "Referer": "https://www.threads.net/",
        }
    req = urllib.request.Request(str(url), headers=_headers)
    try:
        with opener.open(req, timeout=20) as r:
            final = r.geturl()
            data = r.read()
    except urllib.error.HTTPError as e:
        if e.code == 404:
            raise ValueError("hilo no existe o fue borrado (404)")
        if e.code in (401, 403):
            raise ValueError("Threads pide iniciar sesion o el hilo es privado (403)")
        raise ValueError(f"Threads devolvio HTTP {e.code}")
    try:
        html = data.decode("utf-8", "ignore")
    except Exception:
        html = ""
    if not html or len(html) < 500:
        raise ValueError("Threads devolvio una pagina vacia")
    low = html.lower()
    _has_media = "video_versions" in low or "og:video" in low or "image_versions2" in low
    _login_url = "/login" in str(final or "").lower()
    if (_login_url or ("log in" in low and "threads" in low and len(html) < 20000)) and not _has_media:
        raise ValueError("Threads pide iniciar sesion (pagina de login)")
    return html, final
def _threads_code_from_url(url):
    """2.0.8 + poster no es foto: code del post desde una URL (threads.py: ultimo segmento de la
    URL final tras redirecciones). /@user/post/ID -> ID, /t/ID -> ID."""
    try:
        u = str(url or "").split("?")[0].split("#")[0].rstrip("/")
        m = re.search(r"/@[^/]+/post/([^/]+)$", u) or re.search(r"/t/([^/]+)$", u)
        if m:
            return m.group(1)
        return u.split("/")[-1] if u else ""
    except Exception:
        return ""
def threads_native_info(link, cookies_file=None):
    """2.0.8 + Threads nativo + carrusel: info estilo yt-dlp, con entries = 1 por medio.
    Un hilo con video+foto devuelve entries=[video, foto]; un hilo simple, entries=[video] o [foto].
    Cada entry lleva sus variantes como formats (calidades), asi el picker de carrusel y la descarga
    usan el mismo formato que yt-dlp usaria.
    """
    _orig_link = str(link or "").strip().split("#dlpy_carousel=")[0].split("#")[0]
    clean = threads_normalize_link(link)
    _variants = []
    for _v in (_orig_link, clean):
        if _v and _v not in _variants:
            _variants.append(_v)
    try:
        _u = urllib.parse.urlparse(clean)
        _com = "https://www.threads.com" + _u.path
        if _com not in _variants:
            _variants.append(_com)
    except Exception as _ign:
        diagnostic_report("A", f"Threads: variante threads.com: {type(_ign).__name__}: {_ign}")
        pass
    html, items, final_url = "", [], clean
    _pid0, _last_err = "threads", None
    _login_err = None
    for _ua in ("browser", "bot"):
        for _var in _variants:
            try:
                _html, _fin = threads_fetch_html(_var, cookies_file, user_agent=_ua)
            except Exception as _fe:
                _last_err = _fe
                if is_threads_login_error(_fe):
                    _login_err = _fe
                continue
            _code = _threads_code_from_url(_fin) or _threads_code_from_url(_var) or _threads_code_from_url(clean)
            _it = threads_parse_carousel(_html, target_code=_code)
            if _it:
                html, items, final_url, _pid0 = _html, _it, _fin, _code
                break
            if not html:
                html, final_url, _pid0 = _html, _fin, _code
        if items:
            break
    if not items:
        if _login_err is not None:
            raise _login_err
        if _last_err is not None and not html:
            raise _last_err
        return None
    m = re.search(r"/@([^/]+)/post/([^/]+)", clean) or re.search(r"/t/([^/]+)", clean)
    user = m.group(1) if (m and "/@" in clean) else ""
    pid = _pid0 or "threads"
    title = _threads_meta_content(html, "og:title") or _threads_meta_content(html, "twitter:title") or ""
    if not title:
        title = f"Threads @{user} - {pid}" if user else f"Threads - {pid}"
    _author = ""
    _mt = re.match(r"^(.*?)\s+on Threads\b", title)
    if _mt and _mt.group(1).strip():
        _author = _mt.group(1).strip()
    if not _author:
        _author = ("@" + user) if user else ""
    entries = []
    for i, it in enumerate(items, 1):
        if it["kind"] == "video":
            fmts = []
            for j, v in enumerate(sorted(it["variants"], key=lambda x: (x.get("height") or 0, x.get("width") or 0)), 1):
                fmts.append({"format_id": f"n{j}", "ext": "mp4", "vcodec": "h264", "acodec": "aac",
                             "width": v.get("width"), "height": v.get("height"), "url": v["url"],
                             "filesize": None, "protocol": "https",
                             "format_note": "video Threads (directo, sin yt-dlp)",
                             "resolution": f"{v.get('width')}x{v.get('height')}" if (v.get("width") and v.get("height")) else "video",
                             "_idmm_native": True})
            entries.append({"id": f"{pid}_{i}", "title": title, "extractor_key": "Threads", "extractor": "Threads",
                            "webpage_url": clean, "uploader": _author, "channel": _author, "formats": fmts,
                            "thumbnails": [], "description": title, "duration": None, "_carousel_kind": "video"})
        else:
            best = max(it["variants"], key=lambda x: ((x.get("width") or 0) * (x.get("height") or 0), x.get("width") or 0))
            fmts = [{"format_id": "img", "ext": idmm_img_ext(best["url"]), "vcodec": "none", "acodec": "none",
                     "width": best.get("width"), "height": best.get("height"), "url": best["url"],
                     "filesize": None, "protocol": "https", "format_note": "foto Threads",
                     "resolution": f"{best.get('width')}x{best.get('height')}" if (best.get("width") and best.get("height")) else "foto",
                     "_idmm_image": True, "_idmm_native": True}]
            entries.append({"id": f"{pid}_{i}", "title": title, "extractor_key": "Threads", "extractor": "Threads",
                            "webpage_url": clean, "uploader": _author, "channel": _author, "formats": fmts,
                            "thumbnails": [{"url": best["url"], "width": best.get("width"), "height": best.get("height")}],
                            "description": title, "duration": None, "_carousel_kind": "foto"})
    info = {"id": pid, "title": title, "extractor_key": "Threads", "extractor": "Threads",
            "webpage_url": clean, "original_url": str(link or ""), "webpage_url_domain": "threads.net",
            "uploader": _author, "channel": _author, "entries": entries,
            "formats": [], "thumbnails": [], "description": title, "duration": None}
    try:
        _IDMM_INFO_CACHE[clean] = info
    except Exception as _ign:
        diagnostic_report("A", f"Threads: guardar info en caché: {type(_ign).__name__}: {_ign}")
        pass
    return info
# --- 2.0.8 + carrusel mixto: items, picker y entrada unica ---
def _threads_is_video_url(url):
    """2.0.8 + poster no es foto: True si la URL es un video directo (.mp4/.mov/.webm)."""
    try:
        low = str(url or "").split("?")[0].split("#")[0].lower()
        return any(low.endswith(e) for e in (".mp4", ".mov", ".webm", ".m4v", ".mkv"))
    except Exception:
        return False
def _entry_has_video(entry):
    """2.0.8 + poster no es foto: True si la entry es un VIDEO. Su thumbnail/poster NO es una foto
    que se pueda bajar: es la miniatura de reproduccion del video. Sin esto, un video sin formatos
    detectados se marcaba como foto y DLpy bajaba su poster en lugar del video."""
    try:
        e = entry or {}
        if e.get("_carousel_kind") == "video":
            return True
        for f in (e.get("formats") or []):
            if (f or {}).get("vcodec") and (f or {}).get("vcodec") != "none":
                return True
        if _threads_is_video_url(e.get("url") or ""):
            return True
        if e.get("video_versions"):
            return True
        return False
    except Exception:
        return False
def _carousel_best_video_fmt(entry):
    """2.0.8 + carrusel: mejor formato de video de una entry (max altura, luego tbr)."""
    try:
        vids = [f for f in (entry.get("formats") or []) if f.get("vcodec") and f.get("vcodec") != "none"]
        if vids:
            return max(vids, key=lambda f: (f.get("height") or 0, f.get("tbr") or 0))
        _u = (entry or {}).get("url") or ""
        if _threads_is_video_url(_u):
            return {"format_id": "direct", "ext": _u.split("?")[0].rsplit(".", 1)[-1].lower() or "mp4",
                    "vcodec": "h264", "acodec": "aac", "width": None, "height": None, "url": _u,
                    "filesize": None, "protocol": "https", "format_note": "video directo",
                    "_idmm_native": bool((entry or {}).get("_idmm_native"))}
        return None
    except Exception:
        return None
def _carousel_foto_fmt(entry):
    """2.0.8 + carrusel: formato de foto de una entry (de formats, thumbnail o url).
    NUNCA devuelve el poster de un video como "foto": el thumbnail de una entry de video es la
    miniatura de reproduccion, no una foto del hilo. Antes, un video sin formatos detectados caia
    aqui, devolvia su poster y DLpy lo bajaba como imagen en lugar del video.
    """
    try:
        if _entry_has_video(entry):
            return None
        imgs = [f for f in (entry.get("formats") or [])
                if (f.get("ext") or "").lower() in ("jpg", "jpeg", "png", "webp", "avif",
                                                     "gif", "bmp", "tif", "tiff", "svg", "heic", "heif")
                and (not f.get("vcodec") or f.get("vcodec") == "none")]
        if imgs:
            f = max(imgs, key=lambda x: ((x.get("width") or 0) * (x.get("height") or 0), x.get("width") or 0))
            f = dict(f)
            f["_idmm_image"] = True
            return f
        thumbs = entry.get("thumbnails") or []
        if thumbs:
            t = max(thumbs, key=lambda x: ((x.get("width") or 0) * (x.get("height") or 0), x.get("width") or 0))
            if t.get("url"):
                return {"format_id": "img", "ext": idmm_img_ext(t["url"]), "vcodec": "none", "acodec": "none",
                        "width": t.get("width"), "height": t.get("height"), "url": t["url"], "filesize": None,
                        "protocol": "https", "format_note": "foto", "_idmm_image": True}
        url = entry.get("url") or entry.get("webpage_url") or ""
        if url and any(e in url.lower() for e in (".jpg", ".jpeg", ".png", ".webp",
                                                   ".gif", ".bmp", ".tif", ".tiff", ".svg", ".heic", ".heif")):
            return {"format_id": "img", "ext": idmm_img_ext(url), "vcodec": "none", "acodec": "none",
                    "width": None, "height": None, "url": url, "filesize": None,
                    "protocol": "https", "format_note": "foto", "_idmm_image": True}
    except Exception:
        pass
    return None
def carousel_items_from_info(info):
    """2.0.8 + carrusel: [{index, kind, entry, best_fmt, label}] o [] si no es carrusel.
    Funciona con yt-dlp (entries) y con el lector nativo (entries). Si solo hay 1 entry, [].
    Una foto se marca kind='foto' aunque yt-dlp la traiga como entry sin formatos de video.
    """
    try:
        entries = [e for e in (info.get("entries") or []) if isinstance(e, dict)]
        if len(entries) < 2:
            return []
        items = []
        _seen_urls = set()
        for i, e in enumerate(entries, 1):
            kind = e.get("_carousel_kind")
            if kind not in ("video", "foto"):
                kind = "video" if _carousel_best_video_fmt(e) else "foto"
            if kind != "video" and _entry_has_video(e):
                kind = "video"
            if kind == "video":
                best = _carousel_best_video_fmt(e)
                if not best:
                    continue
                label = f"Video {best.get('height')}p" if best.get("height") else "Video"
                if best.get("ext"):
                    label += f" · {best.get('ext')}"
                _u = idmm_dedup_key(best.get("url") or "")
                if _u and _u in _seen_urls:
                    continue
                if _u:
                    _seen_urls.add(_u)
                items.append({"index": i, "kind": "video", "entry": e, "best_fmt": best, "label": label})
            else:
                best = _carousel_foto_fmt(e)
                if not best:
                    continue
                w, h = best.get("width"), best.get("height")
                label = f"Foto {w}x{h}" if (w and h) else "Foto"
                if best.get("ext"):
                    label += f" · {best.get('ext')}"
                _u = idmm_dedup_key(best.get("url") or "")
                if _u and _u in _seen_urls:
                    continue
                if _u:
                    _seen_urls.add(_u)
                items.append({"index": i, "kind": "foto", "entry": e, "best_fmt": best, "label": label})
        return items if len(items) >= 2 else []
    except Exception:
        return []
def carousel_single_info(item, parent_info):
    """2.0.8 + carrusel: info de un solo medio (la entry), con titulo y extractor del padre.
    2.0.8 + autor: tambien hereda autor (uploader/channel/artist/creator) y URLs del padre si
    la entry no los trae. Sin esto, un medio encolado sin uploader salia con Artist vacio y el
    unico atributo visible era Software = DLpy (se leia como autor)."""
    entry = dict(item["entry"])
    if not entry.get("title"):
        entry["title"] = parent_info.get("title") or "video"
    if not entry.get("extractor_key"):
        entry["extractor_key"] = parent_info.get("extractor_key") or parent_info.get("extractor")
    for _k in ("artist", "creator", "uploader", "channel", "webpage_url", "original_url"):
        if not entry.get(_k):
            entry[_k] = parent_info.get(_k) or ""
    return entry
def carousel_pick(items, title=""):
    """2.0.8 + carrusel: pregunta que medios bajar. Devuelve [items] o None si se cancela.
    Acepta: 1  ·  1,3  ·  t / todos / all (todos)  ·  q (salir).
    Sin entrada interactiva (atajo/preset): devuelve None y quien llama usa el primero.
    """
    if QUIET.get("on"):
        return None
    n_v = sum(1 for it in items if it["kind"] == "video")
    n_f = sum(1 for it in items if it["kind"] == "foto")
    _status = t_display(f"{len(items)} medios: {n_v} video(s), {n_f} foto(s)")
    if SCENE.get("a"):
        try:
            ux_list_top(title or "Carrusel", _status)
        except Exception:
            m_block("Carrusel", [_status])
    else:
        m_block("Carrusel", [_status])
    for it in items:
        if SCENE.get("a"):
            print(paint(f"  {it['index']}", "orange", True) + paint(f" · {it['label']}", "white"))
        else:
            print(f"  {it['index']} · {it['label']}")
    if SCENE.get("a"):
        print(paint("  t", "orange", True) + paint(" · " + t_display("Todos"), "white"))
        print(paint("  q", "orange", True) + paint(" · " + t_display("Salir"), "white"))
    else:
        print("  t · " + t_display("Todos"))
        print("  q · " + t_display("Salir"))
    while True:
        try:
            r = timed_input(t_display("Medios (ej: 1, 1,3 o t)") + " ▸ ", None)
        except (EOFError, KeyboardInterrupt, OSError):
            return None
        if r is None:
            return None
        s = str(r or "").strip().lower()
        if s in ("q", "salir", "exit"):
            return None
        if s in ("t", "todos", "todo", "all", "0"):
            return list(items)
        try:
            _valid_idx = {it.get("index") for it in items}
            idxs = []
            for part in s.replace(";", ",").split(","):
                part = part.strip()
                if not part:
                    continue
                n = int(part)
                if n in _valid_idx:
                    idxs.append(n)
            if idxs:
                out, seen = [], set()
                for n in idxs:
                    if n in seen:
                        continue
                    seen.add(n)
                    _hit = next((it for it in items if it.get("index") == n), None)
                    if _hit is not None:
                        out.append(_hit)
                if out:
                    return out
        except Exception:
            pass
        print("  " + t_display("Escribe 1, 1,3, t (todos) o q (salir)."))
# --- IDMM Instagram: carrusel sin formatos de video ---
IDMM_CONTINUE = "__idmm_continue__"
def is_instagram_link(link):
    """IDMM Instagram: True si el enlace es de Instagram (instagram.com / instagr.am)."""
    try:
        h = urllib.parse.urlparse(str(link or "") if "://" in str(link or "") else "https://" + str(link or "")).hostname or ""
    except Exception:
        return False
    h = h.lower()
    return h in ("instagram.com", "www.instagram.com", "instagr.am", "www.instagr.am")
def _has_video_formats(info):
    """filtro formatos/IDMM: True si AL MENOS UN medio trae formato de video.
    Mixto (video + foto) cuenta como video: es camino normal, no IDMM. Foto-only (sin
    ningun video) devuelve False y el filtro decide IDMM / error segun el sitio.
    """
    try:
        info = info or {}
        entries = info.get("entries")
        if entries is not None:
            if not entries:
                return False
            return any(isinstance(e, dict) and bool(_carousel_best_video_fmt(e)) for e in entries)
        return bool(_carousel_best_video_fmt(info)
                    or any((f or {}).get("vcodec") not in (None, "none") for f in (info.get("formats") or [])))
    except Exception:
        return False
def _has_usable_media(info):
    """filtro formatos/IDMM: True si TODOS los medios son usables (video con formatos,
    o foto por thumbnail). Generaliza `_instagram_info_usable` a cualquier sitio.
    Un carrusel con alguna entry en None (yt-dlp #16951) NO es usable: es incompleto.
    Un info sin entries (un solo medio) se juzga por sus formatos / foto / url.
    """
    try:
        info = info or {}
        entries = info.get("entries")
        if entries is not None:
            if not entries:
                return False
            return all(isinstance(e, dict) and (_carousel_best_video_fmt(e) or _carousel_foto_fmt(e))
                       for e in entries)
        return bool(_carousel_best_video_fmt(info) or _carousel_foto_fmt(info)
                    or (info.get("formats") or []) or info.get("url"))
    except Exception:
        return False
def has_formats(info):
    """filtro binario: True si tiene formatos, False si no tiene.
    Tiene = al menos un medio trae formato de video (`_has_video_formats`). Una foto
    por thumbnail NO cuenta como formato: yt-dlp no le da formatos, es IDMM quien la
    baja por su URL de thumbnail. Por eso foto-only -> False -> IDMM.
    """
    return _has_video_formats(info)
def formats_or_idmm_filter(info, link):
    """filtro binario: "normal" | "idmm", nada mas.
    Tiene formatos -> "normal": usa yt-dlp tal cual. No tiene -> "idmm": IDMM lo resuelve.
    Para un sitio sin IDMM, "idmm" sin IDMM a donde caer termina en error
    "No video formats found" en el llamador, mismo resultado, sin tercer estado.
    `link` se conserva por compatibilidad con la llamada anterior, no decide.
    """
    return "normal" if has_formats(info) else "idmm"
def is_instagram_login_error(e):
    """IDMM Instagram: True si el error es login / privado."""
    low = str(e or "").lower()
    return any(k in low for k in ("login", "iniciar sesion", "iniciar sesión", "sign in", "private",
                                 "privado", "403", "forbidden", "cookies", "checkpoint", "suspicious"))
def is_idmm_link(link):
    """IDMM unificado: True si el enlace es IDMM (Instagram o Threads). El carrusel es IDMM, no Threads."""
    return bool(is_instagram_link(link) or is_threads_link(link))
def is_idmm_login_error(e):
    """IDMM unificado: True si el error es login / privado en Instagram o en Threads."""
    return bool(is_threads_login_error(e) or is_instagram_login_error(e))
def idmm_normalize_link(link):
    """IDMM: enlace limpio, igual para todos. Despacha al normalizador del sitio sin que el llamador sepa cual es."""
    if is_instagram_link(link):
        return instagram_normalize_link(link)
    if is_threads_link(link):
        return threads_normalize_link(link)
    return str(link or "").strip().split("#dlpy_carousel=")[0].split("#")[0]
def idmm_site_name(link=None, info=None):
    """IDMM: nombre del sitio para el mensaje de handoff, sin ramificar en el llamador."""
    ex = str((info or {}).get("extractor") or "").lower()
    if "instagram" in ex or is_instagram_link(link):
        return "Instagram"
    if "threads" in ex or is_threads_link(link):
        return "Threads"
    if (info or {}).get("_idmm_site"):
        return str(info.get("_idmm_site"))
    return "IDMM"
def idmm_scm_json(link=None, site="IDMM"):
    """IDMM: el handoff del atajo para IDMM (Instagram o Threads). No es un error: `ok: True`, `status: "scb"`, `message`. El atajo revisa `use_scb` y sigue con --scb sin mostrar "Aviso de error". Sin "(carrusel)": vale para 1 foto y para carrusel."""
    _site = str(site or "IDMM")
    return {"dlpy": "shortcutmode", "schema": 1, "ok": True, "status": "scb", "version": VERSION, "link": link or "",
            "error_code": "idmm_scb", "message": f"{_site}: sigue con --scb (IDMM lo baja todo).", "use_scb": True,
            "idmm": True, "idmm_site": _site}
def _instagram_kind(link):
    """IDMM Instagram: p / reel / tv / reels segun la URL (p por omision)."""
    try:
        s = str(link or "").strip().split("?")[0].split("#")[0].rstrip("/")
        m = re.search(r"/(p|reel|tv|reels)/[^/]+$", s)
        return m.group(1) if m else "p"
    except Exception:
        return "p"
def instagram_shortcode(link):
    """IDMM Instagram: codigo del post (/p/<codigo>/, /reel/<codigo>/, /tv/<codigo>/, /reels/<codigo>/)."""
    try:
        s = str(link or "").strip().split("?")[0].split("#")[0].rstrip("/")
        m = re.search(r"/(?:p|reel|tv|reels)/([^/]+)$", s)
        return m.group(1) if m else ""
    except Exception:
        return ""
def instagram_normalize_link(link):
    """IDMM Instagram: enlace limpio (sin query/fragmento, sin #dlpy_carousel=N)."""
    try:
        s = str(link or "").strip().split("#dlpy_carousel=")[0].split("#")[0]
        code = instagram_shortcode(s)
        if not code:
            return s.split("?")[0]
        return f"https://www.instagram.com/{_instagram_kind(s)}/{code}/"
    except Exception:
        return str(link or "")
def _instagram_info_usable(info):
    """IDMM Instagram: True si el info trae TODOS sus medios usables (video con
    formatos, o foto por thumbnail). Un carrusel con alguna entry en None (yt-dlp #16951)
    NO es usable: Stage 1 seria un carrusel incompleto y cae a Stage 2 (nativo, que trae
    todos los medios). Un info sin entries (un solo medio) se juzga por sus formatos.
    delega en `_has_usable_media` (misma regla, generalizada a cualquier sitio)."""
    return _has_usable_media(info)
def instagram_fetch(url, cookies_file=None):
    """IDMM Instagram: GET con cookies.txt si lo hay (igual que threads_fetch_html).
    Devuelve (texto, url_final). Login/privado/404 = ValueError con el motivo real."""
    import http.cookiejar
    import urllib.request
    import urllib.error
    cj = None
    if cookies_file and os.path.isfile(str(cookies_file)):
        try:
            cj = http.cookiejar.MozillaCookieJar(str(cookies_file))
            cj.load(ignore_discard=True, ignore_expires=True)
        except Exception as _ign:
            ignore("instagram_fetch_cookies", _ign)
            cj = None
    opener = urllib.request.build_opener(urllib.request.HTTPCookieProcessor(cj) if cj else urllib.request.HTTPHandler())
    req = urllib.request.Request(str(url), headers={
        "User-Agent": "Mozilla/5.0 (iPhone; CPU iPhone OS 18_0 like Mac OS X) AppleWebKit/605.1.15 (KHTML, like Gecko) Version/18.0 Mobile/15E148 Safari/604.1",
        "Accept": "application/json, text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
        "Accept-Language": "en-US,en;q=0.9",
        "Referer": "https://www.instagram.com/",
        "X-Requested-With": "XMLHttpRequest",
    })
    try:
        with opener.open(req, timeout=20) as r:
            final, data = r.geturl(), r.read()
    except urllib.error.HTTPError as e:
        if e.code == 404:
            raise ValueError("Instagram: el post no existe o fue borrado (404)")
        if e.code in (401, 403):
            raise ValueError("Instagram pide iniciar sesion o el post es privado (403). Con DLPY_COOKIES_FILE apunta a un cookies.txt de instagram.com.")
        raise ValueError(f"Instagram devolvio HTTP {e.code}")
    try:
        text = data.decode("utf-8", "ignore")
    except Exception:
        text = ""
    if not text or len(text) < 200:
        raise ValueError("Instagram devolvio una pagina vacia")
    low = text.lower()
    if ("login" in low and "instagram" in low and "shortcode_media" not in low
            and "display_url" not in low and "thumbnail_url" not in low):
        raise ValueError("Instagram pide iniciar sesion (pagina de login). Con DLPY_COOKIES_FILE apunta a un cookies.txt de instagram.com.")
    return text, final
def _instagram_find_media(data):
    """IDMM Instagram: el objeto shortcode_media dentro de un JSON (graphql.shortcode_media,
    data.shortcode_media, o un dict que ya es el medio). None si no hay."""
    try:
        if isinstance(data, dict):
            if isinstance(data.get("shortcode_media"), dict):
                return data["shortcode_media"]
            if isinstance(data.get("graphql"), dict) and isinstance(data["graphql"].get("shortcode_media"), dict):
                return data["graphql"]["shortcode_media"]
            if "display_url" in data or "edge_sidecar_to_children" in data:
                return data
            for v in data.values():
                if isinstance(v, (dict, list)):
                    hit = _instagram_find_media(v)
                    if hit is not None:
                        return hit
        elif isinstance(data, list):
            for v in data:
                hit = _instagram_find_media(v)
                if hit is not None:
                    return hit
    except Exception as _ign:
        diagnostic_report("A", f"Instagram: buscar shortcode_media: {type(_ign).__name__}: {_ign}")
        pass
    return None
def _instagram_best_display(node):
    """IDMM Instagram: la URL de foto de mayor resolucion del nodo (display_resources por
    config_width, o display_url). Devuelve (url, ancho, alto)."""
    try:
        res = node.get("display_resources") or []
        if res:
            best = max(res, key=lambda x: (x.get("config_width") or 0) * (x.get("config_height") or 0))
            if best.get("src"):
                return best["src"], best.get("config_width"), best.get("config_height")
        if node.get("display_url"):
            dims = node.get("dimensions") or {}
            return node["display_url"], dims.get("width"), dims.get("height")
    except Exception as _ign:
        diagnostic_report("A", f"Instagram: mejor display: {type(_ign).__name__}: {_ign}")
        pass
    return None, None, None
def _instagram_caption(media):
    """IDMM Instagram: texto del pie del post (edge_media_to_caption)."""
    try:
        edges = (media.get("edge_media_to_caption") or {}).get("edges") or []
        if edges:
            return (edges[0].get("node") or {}).get("text") or ""
    except Exception:
        pass
    return ""
def _instagram_items_from_media(media):
    """IDMM Instagram: [(kind, url, ancho, alto)] en orden, del shortcode_media.
    Carrusel = edge_sidecar_to_children.edges; si no, el propio medio."""
    out = []
    try:
        edges = (media.get("edge_sidecar_to_children") or {}).get("edges") or []
        nodes = [(e.get("node") or {}) for e in edges if isinstance(e, dict)] or [media]
        for node in nodes:
            if not isinstance(node, dict):
                continue
            if node.get("is_video"):
                url = node.get("video_url") or ""
                if url:
                    out.append(("video", url, None, None))
                    continue
            url, w, h = _instagram_best_display(node)
            if url:
                out.append(("foto", url, w, h))
    except Exception as _ign:
        diagnostic_report("A", f"Instagram: items del medio: {type(_ign).__name__}: {_ign}")
        pass
    return out
def instagram_native_info(link, cookies_file=None):
    """IDMM Instagram: info estilo yt-dlp, con entries = 1 por medio (igual que
    threads_native_info). Cadena: ?__a=1&__d=dis (JSON con shortcode_media) -> embed/captioned/
    (og:image / og:video, 1er medio) -> oEmbed (thumbnail_url, 1a foto). Login/privado =
    ValueError con el motivo real. Sin media = None."""
    clean = instagram_normalize_link(link)
    code = instagram_shortcode(link)
    if not code:
        return None
    kind = _instagram_kind(link)
    items, title, author = [], "", ""
    # --- Intento A: JSON del post ---
    try:
        text, _fin = instagram_fetch(clean + "?__a=1&__d=dis", cookies_file)
        try:
            media = _instagram_find_media(json.loads(text))
        except Exception:
            media = None
        if media:
            items = _instagram_items_from_media(media)
            title = _instagram_caption(media) or ""
            author = ((media.get("owner") or {}) or {}).get("username") or ""
    except Exception as _e:
        if is_instagram_login_error(_e):
            raise
        dbg("análisis falló", f"Instagram nativo ?__a=1: {_e}")
    # --- Intento B: embed (og:* = 1er medio) ---
    if not items:
        try:
            _embed_path = "embed" + "/" + "captioned" + "/"
            html, _fin = instagram_fetch(f"https://www.instagram.com/{kind}/{code}/" + _embed_path, cookies_file)
            og_video = _threads_meta_content(html, "og:video")
            og_img = _threads_meta_content(html, "og:image")
            og_title = _threads_meta_content(html, "og:title")
            if og_video:
                items = [("video", og_video, None, None)]
            elif og_img:
                items = [("foto", og_img, None, None)]
            title = og_title or ""
        except Exception as _e:
            if is_instagram_login_error(_e):
                raise
            dbg("análisis falló", f"Instagram nativo embed: {_e}")
    # --- Intento C: oEmbed (thumbnail_url = 1a foto) ---
    if not items:
        try:
            text, _fin = instagram_fetch(
                "https://api.instagram.com/oembed/?url=" + urllib.parse.quote(clean, safe="") + "&omitscript=true",
                cookies_file)
            thumb = (json.loads(text) or {}).get("thumbnail_url") or ""
            if thumb:
                items = [("foto", thumb, None, None)]
        except Exception as _e:
            dbg("análisis falló", f"Instagram nativo oEmbed: {_e}")
    if not items:
        return None
    if not title:
        title = f"Instagram @{author} - {code}" if author else f"Instagram - {code}"
    _author = ("@" + author) if author else ""
    entries = []
    for i, (kind2, url, w, h) in enumerate(items, 1):
        if kind2 == "video":
            fmts = [{"format_id": "n1", "ext": "mp4", "vcodec": "h264", "acodec": "aac",
                     "width": w, "height": h, "url": url, "filesize": None, "protocol": "https",
                     "format_note": "video Instagram (directo, sin yt-dlp)",
                     "resolution": f"{w}x{h}" if (w and h) else "video",
                     "_idmm_native": True}]
            entries.append({"id": f"{code}_{i}", "title": title, "extractor_key": "Instagram", "extractor": "Instagram",
                            "webpage_url": clean, "uploader": _author, "channel": _author, "formats": fmts,
                            "thumbnails": [], "description": title, "duration": None, "_carousel_kind": "video"})
        else:
            fmts = [{"format_id": "img", "ext": idmm_img_ext(url), "vcodec": "none", "acodec": "none",
                     "width": w, "height": h, "url": url, "filesize": None, "protocol": "https",
                     "format_note": "foto Instagram", "resolution": f"{w}x{h}" if (w and h) else "foto",
                     "_idmm_image": True, "_idmm_native": True}]
            entries.append({"id": f"{code}_{i}", "title": title, "extractor_key": "Instagram", "extractor": "Instagram",
                            "webpage_url": clean, "uploader": _author, "channel": _author, "formats": fmts,
                            "thumbnails": [{"url": url, "width": w, "height": h}],
                            "description": title, "duration": None, "_carousel_kind": "foto"})
    info = {"id": code, "title": title, "extractor_key": "Instagram", "extractor": "Instagram",
            "webpage_url": clean, "original_url": str(link or ""), "webpage_url_domain": "instagram.com",
            "uploader": _author, "channel": _author, "entries": entries,
            "formats": [], "thumbnails": [], "description": title, "duration": None}
    try:
        _IDMM_INFO_CACHE[clean] = info
    except Exception as _ign:
        diagnostic_report("A", f"Instagram: guardar info en caché: {type(_ign).__name__}: {_ign}")
        pass
    return info
def instagram_idmm_info(link, yt_dlp, extra, std):
    """IDMM Instagram unificado: solo el lector nativo, marcado con
    _instagram_idmm (el atajo la reconoce y sigue con --scb). El primer escaneo de
    yt-dlp en `analyze_link` YA es la Etapa 1 (en Instagram con `ignore_no_formats_error`),
    asi que aqui no se repite: repetirlo seria un 2o intento de yt-dlp. None si el nativo no trae medios."""
    clean = instagram_normalize_link(link)
    # --- IDMM: lector nativo (unico paso; el yt-dlp ya se hizo en analyze_link) ---
    _info2 = instagram_native_info(link, cookies_path())
    if _info2 is not None:
        _info2["_instagram_idmm"] = True
        _info2["_idmm"] = True
        _info2["_idmm_site"] = "Instagram"
        _IDMM_INFO_CACHE[clean] = _info2
        return _info2
    return None
def _drop_scb_arg(args):
    """IDMM Instagram: quita --scb (tambien --scb=valor o con raya larga) de los
    argumentos: la ejecucion sigue el flujo normal, como en threads_scb_args / sc_list_args."""
    out = []
    for a in (args or []):
        name = a.lstrip("-\u2013\u2014").lower().split("=")[0] if a[:1] and a[:1] in "-\u2013\u2014" else ""
        if name == "scb":
            continue
        out.append(a)
    return out
def idmm_info(link, yt_dlp, extra, std, orig_link=None, last=None):
    """IDMM: unico destino cuando yt-dlp no trae formatos. El llamador no ramifica por sitio: aqui se despacha a Instagram o Threads. Devuelve info o None. Login/privado lanza; Threads sin media + Unsupported URL lanza el motivo real."""
    if is_instagram_link(link):
        _ig = instagram_idmm_info(link, yt_dlp, extra, std)
        if _ig is not None:
            _ig["_idmm"] = True
            _ig["_idmm_site"] = "Instagram"
            return _ig
        return None
    if is_threads_link(orig_link or link) or is_threads_link(link):
        m_info(t_display("Threads") + ": yt-dlp no lo reconoce, se lee el hilo directo (IDMM)")
        _native = threads_native_info(orig_link or link, cookies_path())
        if _native and (_native.get("entries") or _native.get("formats")):
            dbg("análisis", "funcionó: Threads nativo (IDMM)")
            _native["_idmm"] = True
            _native["_idmm_site"] = "Threads"
            return _native
        dbg("análisis falló", "Threads nativo (IDMM): sin media en el HTML")
        if is_unsupported_url_error(last):
            raise ValueError(
                f"Threads: DLpy no pudo leer este hilo ({threads_normalize_link(link or orig_link)}). "
                "Puede ser privado, borrado o que Threads pida iniciar sesion. "
                "Con DLPY_COOKIES_FILE apunta a un cookies.txt de threads.net.")
        return None
    return None
ANALYZE_SLOW_SECS = 12.0
def analyze_link_timed(yt_dlp, link, quick=False, argv=None, secs=None):
    """analyze_link con tope de tiempo (SC_TIMEOUT): mismo patrón que collect_with_timeout (hilo daemon + join).
    Si el sitio no responde, falla con mensaje en vez de quedarse en «Analizando enlace» para siempre."""
    secs = SC_TIMEOUT if secs is None else secs
    if not secs or secs <= 0:
        return analyze_link(yt_dlp, link, quick=quick, argv=argv)
    box = {}
    def _work():
        try:
            box["v"] = analyze_link(yt_dlp, link, quick=quick, argv=argv)
        except BaseException as e:
            box["e"] = e
    th = threading.Thread(target=_work, daemon=True)
    th.start()
    _t0 = time.monotonic()
    _noted = False
    while True:
        th.join(0.25)
        if not th.is_alive():
            break
        _el = time.monotonic() - _t0
        if _el >= secs:
            break
        if not _noted and _el >= ANALYZE_SLOW_SECS:
            _noted = True
            try:
                ux_status("Analizando enlace · puede tardar más")
            except Exception as _ign:
                ignore("analyze_link_timed aviso", _ign)
    if th.is_alive():
        raise TimeoutError(f"análisis sin respuesta en {secs:g} s (DLPY_SHORTCUT_TIMEOUT={secs:g})")
    if "e" in box:
        raise box["e"]
    return box.get("v")
def analyze_link(yt_dlp, link, quick=False, argv=None):
    """Devuelve (info, base_opts). El PRIMER escaneo es siempre yt-dlp, un solo intento: normal en todos los sitios y con
    `ignore_no_formats_error` solo en Instagram (fotos y carruseles mixtos). Tiene formato -> flujo normal. No tiene -> IDMM
    (Instagram / Threads) o, si no es IDMM, la imagen directa como respaldo y, si no, el error de yt-dlp.
    Solo las cachés del carrusel (no son un escaneo: reutilizan uno ya hecho) pueden ir antes. IDMM despacha dentro."""
    if idmm_carousel_index(link):
        _ckey = _carousel_cache_key(link)
        _cached = _CAROUSEL_INFO_CACHE.get(_ckey)
        if _cached and (_cached.get('entries') or _cached.get('formats')):
            _stamp_cdn_expiry(_cached)
            dbg('análisis', 'funcionó: carrusel (caché general, sin volver a bajar)')
            ANALYSIS['stage'] = 'Carrusel (caché)'
            ANALYSIS['t'] = time.monotonic()
            return _cached, (cli_like_opts(yt_dlp, ['--no-playlist'] + (list(argv) if argv is not None else user_argv())) or {})
    if idmm_carousel_index(link) and is_idmm_link(link):
        _clean0 = idmm_normalize_link(link)
        _cached0 = _IDMM_INFO_CACHE.get(_clean0)
        if _cached0 and (_cached0.get("entries") or _cached0.get("formats")):
            _stamp_cdn_expiry(_cached0)
            dbg("análisis", "funcionó: IDMM (caché del carrusel, sin volver a bajar)")
            ANALYSIS["stage"] = "IDMM"
            ANALYSIS["t"] = time.monotonic()
            return _cached0, (cli_like_opts(yt_dlp, ["--no-playlist"] + (list(argv) if argv is not None else user_argv())) or {})
    if RUNTIME.get("idmm_continue") and is_idmm_link(link):
        # 2.0.8: --scb ya analizó este enlace en el atajo (shortcut_collect) y siguió con la interfaz normal: se reutiliza ese análisis una sola vez.
        RUNTIME.pop("idmm_continue", None)
        try:
            _hand = _IDMM_INFO_CACHE.get(idmm_normalize_link(link))
            if _hand and (_hand.get("entries") or _hand.get("formats")) and not _cdn_needs_refresh(_hand):
                _stamp_cdn_expiry(_hand)
                dbg("análisis", "funcionó: IDMM (análisis del atajo reutilizado, sin repetir el escaneo)")
                ANALYSIS["stage"] = "IDMM"
                ANALYSIS["t"] = time.monotonic()
                ux_set(link=idmm_normalize_link(link))
                return _hand, (cli_like_opts(yt_dlp, ["--no-playlist"] + (list(argv) if argv is not None else user_argv())) or {})
        except Exception as _ign:
            ignore("analyze_link reutilizar análisis del atajo", _ign)
    _orig_link = link
    if is_idmm_link(link):
        link = idmm_normalize_link(link)
    ux_set(link=link)
    extra = list(argv) if argv is not None else user_argv()
    _carousel_site = is_idmm_link(link)
    std = {"quiet": True, "no_warnings": True, "noplaylist": True, "socket_timeout": 20}
    if not DEBUG:
        std["logger"] = _QuietLog()
    _ig_scan = is_instagram_link(link)
    if _ig_scan:
        std["ignore_no_formats_error"] = True
    _ck = cookies_path()
    if _ck:
        std["cookiefile"] = _ck
    _ea = youtube_extractor_args()
    if _ea:
        std["extractor_args"] = _ea
    if DEBUG:
        std.update({"quiet": False, "no_warnings": False, "verbose": True})
    if quick:
        std.update({"socket_timeout": 10, "retries": 2, "extractor_retries": 1})
    if SCM["on"]:
        std.update({"socket_timeout": 2, "retries": 0, "extractor_retries": 0})
        if not getattr(yt_dlp.YoutubeDL, "_dlpy_abortable", False):
            _orig_urlopen = yt_dlp.YoutubeDL.urlopen
            def _urlopen(self, *a, **k):
                if SCM["abort"].is_set():
                    raise RuntimeError("análisis abortado")
                return _orig_urlopen(self, *a, **k)
            yt_dlp.YoutubeDL.urlopen = _urlopen
            yt_dlp.YoutubeDL._dlpy_abortable = True
    # --- UNICO intento yt-dlp ---
    base = (cli_like_opts(yt_dlp, extra) or {}) if extra else {}
    probe = {**base, **std}
    if _carousel_site:
        probe.pop("noplaylist", None)
    if SCM["abort"].is_set():
        raise RuntimeError("análisis abortado")
    _sc_mark("net")
    _t_n = time.time()
    info = None
    last = None
    try:
        with yt_dlp.YoutubeDL(probe) as ydl:
            info = ydl.extract_info(link, download=False)
        _sc_add("net", time.time() - _t_n)
        if info:
            dbg("análisis", "funcionó: yt-dlp (primer escaneo" + (", ignore_no_formats_error)" if _ig_scan else ")"))
            ANALYSIS["stage"] = "yt-dlp (ignore_no_formats_error)" if _ig_scan else "yt-dlp (primer escaneo)"
            ANALYSIS["t"] = time.monotonic()
            net_set("analyze", _t_n, True, None, str(info.get("extractor_key") or info.get("extractor") or "") or None)
    except KeyboardInterrupt:
        raise
    except Exception as e:
        _sc_add("net", time.time() - _t_n)
        last = e
        net_set("analyze", _t_n, False, err=net_err_text(e))
        dbg("análisis falló", f"yt-dlp (primer escaneo): {e}")
        if is_bot_error(e):
            raise
    # --- Filtro binario: tiene formato -> normal, no tiene -> IDMM ---
    if info:
        if formats_or_idmm_filter(info, link) == "normal":
            _stamp_cdn_expiry(info)
            return info, base
        if is_idmm_link(link) and _has_usable_media(info):
            info["_idmm"] = True
            _stamp_cdn_expiry(info)
            info["_idmm_site"] = idmm_site_name(link, info)
            try:
                _IDMM_INFO_CACHE[idmm_normalize_link(link)] = info
            except Exception as _ign:
                diagnostic_report("A", f"analyze_link: guardar info IDMM en caché: {type(_ign).__name__}: {_ign}")
                pass
            return info, base
        if last is None:
            last = ValueError("No video formats found (sin formatos de video ni medios usables)")
    # --- IDMM: un solo destino, sin ramificar por sitio ---
    if is_idmm_link(link):
        try:
            _idmm = idmm_info(link, yt_dlp, extra, std, orig_link=_orig_link, last=last)
        except KeyboardInterrupt:
            raise
        except Exception as _ide:
            if is_idmm_login_error(_ide):
                raise
            dbg("análisis falló", f"IDMM: {_ide}")
            if last is None:
                last = _ide
            _idmm = None
        if _idmm is not None:
            _stamp_cdn_expiry(_idmm)
            ANALYSIS["stage"] = "IDMM"
            ANALYSIS["t"] = time.monotonic()
            return _idmm, (cli_like_opts(yt_dlp, ["--no-playlist"] + extra) or {})
    _direct2 = _direct_image_info(link or _orig_link, check_head=True)
    if _direct2:
        _stamp_cdn_expiry(_direct2)
        dbg("análisis", "funcionó: imagen directa por HEAD (sin yt-dlp)")
        ANALYSIS["stage"] = "Imagen directa"
        ANALYSIS["t"] = time.monotonic()
        return _direct2, (cli_like_opts(yt_dlp, ["--no-playlist"] + (list(argv) if argv is not None else user_argv())) or {})
    raise last or RuntimeError("no se pudo analizar el enlace")
_RETRY_RE = re.compile(r"not available|expired|forbidden|\bhttp error (?:403|410)\b")
def _dl_ok(res):
    """1.7.1: ¿yt-dlp dejó al menos un archivo (requested_downloads con filepath)? Con ignoreerrors un fallo devolvía el análisis sin ruta y sin error."""
    try:
        return any((d or {}).get("filepath") for d in ((res or {}).get("requested_downloads") or []))
    except AttributeError:
        return False
RETRY_PAUSE = 1.0
CDN_MARGIN_DEFAULT = 600.0
CDN_REFRESH_WAIT = 30.0
_CDN_TS_MIN = 1_000_000_000
_CDN_TS_MAX = 4_102_444_800
def _cdn_margin():
    """segundos de margen proactivo (DLPY_CDN_EXPIRY_MARGIN, 600 por defecto; 0 = solo si ya caduco). Se lee en
    cada llamada para que --config y los tests lo cambien sin reiniciar."""
    try:
        v = _env_num("DLPY_CDN_EXPIRY_MARGIN", CDN_MARGIN_DEFAULT)
    except Exception:
        v = CDN_MARGIN_DEFAULT
    try:
        v = float(v)
    except Exception:
        return CDN_MARGIN_DEFAULT
    if not math.isfinite(v):
        return CDN_MARGIN_DEFAULT
    return min(max(v, 0.0), 86400.0)
def _cdn_url_expiry(url):
    """caducidad (epoch s) que el CDN declara en `url`, o None si no la declara o no es plausible.
    `oe` (Meta: Instagram / Threads) manda y se lee en HEX; si no hay `oe`, se prueba `ext` (Facebook) y
    `x-expires`, ambos en decimal. Un valor fuera de rango se trata como desconocido, nunca como caducado."""
    try:
        s = str(url or "").strip()
        if not s or "://" not in s:
            return None
        qs = urllib.parse.parse_qs(urllib.parse.urlparse(s).query, keep_blank_values=True)
        oe = (qs.get("oe") or [None])[0]
        if oe is not None:
            v = str(oe).strip()
            if v.lower().startswith("0x"):
                v = v[2:]
            if not v:
                return None
            try:
                ts = int(v, 16)
            except ValueError:
                return None
            return ts if _CDN_TS_MIN <= ts <= _CDN_TS_MAX else None
        for key in ("ext", "x-expires"):
            raw = (qs.get(key) or [None])[0]
            if raw is None:
                continue
            try:
                ts = int(str(raw).strip(), 10)
            except ValueError:
                continue
            if _CDN_TS_MIN <= ts <= _CDN_TS_MAX:
                return ts
        return None
    except Exception:
        return None
def _cdn_expiry_for_urls(urls):
    """minima caducidad declarada entre `urls` (None si ninguna la declara)."""
    best = None
    for u in (urls or []):
        ts = _cdn_url_expiry(u)
        if ts is not None and (best is None or ts < best):
            best = ts
    return best
def _cdn_iter_download_urls(info, _depth=0):
    """URLs de descarga de `info`: su `url`, las de sus `formats` y (max. 2 niveles) las de sus
    `entries`. Nunca las miniaturas: no deciden la descarga."""
    try:
        if not isinstance(info, dict) or _depth > 2:
            return
        u = info.get("url")
        if isinstance(u, str) and u:
            yield u
        for f in (info.get("formats") or []):
            if isinstance(f, dict):
                fu = f.get("url")
                if isinstance(fu, str) and fu:
                    yield fu
        for e in (info.get("entries") or []):
            if isinstance(e, dict):
                yield from _cdn_iter_download_urls(e, _depth + 1)
    except Exception:
        return
def _cdn_expiry_for_info(info):
    """minima caducidad declarada en las URLs de descarga de `info` (None si ninguna la declara)."""
    try:
        return _cdn_expiry_for_urls(list(_cdn_iter_download_urls(info)))
    except Exception:
        return None
def _cdn_expiry_for_choice(info, fmt_id):
    """caducidad de la URL del formato elegido (`fmt_id`), o None si no se encuentra o no declara `oe`/`ext`.
    Para un carrusel, busca en las `entries`: asi el medio 3 no se renueva porque el medio 1 caduca antes."""
    try:
        if fmt_id:
            stack = [info] if isinstance(info, dict) else []
            seen = 0
            while stack and seen < 512:
                cur = stack.pop()
                seen += 1
                if not isinstance(cur, dict):
                    continue
                for f in (cur.get("formats") or []):
                    if isinstance(f, dict) and str(f.get("format_id") or "") == str(fmt_id):
                        ts = _cdn_url_expiry(f.get("url"))
                        if ts is not None:
                            return ts
                for e in (cur.get("entries") or []):
                    if isinstance(e, dict):
                        stack.append(e)
    except Exception:
        pass
    return None
def _cdn_needs_refresh_url(url, now=None):
    """True si `url` declara caducidad y queda menos que el margen (o ya caduco). Sin `oe`/`ext`: False."""
    ts = _cdn_url_expiry(url)
    if ts is None:
        return False
    t = time.time() if now is None else now
    try:
        return (ts - float(t)) < _cdn_margin()
    except Exception:
        return False
def _cdn_needs_refresh(info, fmt_id=None, now=None):
    """True si hay que renovar el analisis ANTES de bajar: la URL del formato elegido caduca dentro del
    margen. Si el formato elegido no declara caducidad, se usa la minima de todas las URLs de descarga (conservador:
    puede renovar antes de lo necesario, nunca deja pasar una URL que se sabe caducada). Sin ninguna caducidad: False."""
    try:
        if not isinstance(info, dict):
            return False
        ts = _cdn_expiry_for_choice(info, fmt_id) if fmt_id else None
        if ts is None:
            ts = _cdn_expiry_for_info(info)
        if ts is None:
            return False
        t = time.time() if now is None else now
        return (ts - float(t)) < _cdn_margin()
    except Exception:
        return False
def _stamp_cdn_expiry(info):
    """anota en `info` (y en cada entry) su minima caducidad declarada como `_cdn_expiry` (None si no hay).
    Idempotente y sin lanzar: si algo raro hay en `info`, devuelve `info` tal cual. Las claves `_...` ya se usan
    en `info` (p. ej. `_idmm`), asi que yt-dlp las tolera igual que las demas."""
    try:
        if not isinstance(info, dict):
            return info
        info["_cdn_expiry"] = _cdn_expiry_for_info(info)
        for e in (info.get("entries") or []):
            if isinstance(e, dict):
                try:
                    e["_cdn_expiry"] = _cdn_expiry_for_info(e)
                except Exception as _ign:
                    diagnostic_report("A", f"_stamp_cdn_expiry: caducidad de entry: {type(_ign).__name__}: {_ign}")
                    pass
        return info
    except Exception:
        return info
class _SingleFlight:
    """coalescencia de renovaciones (single-flight) en un solo proceso: solo el primer llamador con una
    clave ejecuta `fn()`; los demas esperan su resultado (max. `timeout` s) y lo comparten, sin volver a extraer.
    Si el lider falla, los seguidores reciben SU MISMA excepcion (no reintentan por su cuenta). Si un seguidor
    agota la espera, devuelve None: el llamador sigue con el analisis previo y el reactivo cubre. Nunca se retiene
    el cerrojo mientras se espera: el cerrojo solo protege el diccionario de vuelos en curso."""
    def __init__(self):
        self._lock = threading.Lock()
        self._calls = {}
    def run(self, key, fn, timeout=None):
        if timeout is None:
            timeout = CDN_REFRESH_WAIT
        with self._lock:
            entry = self._calls.get(key)
            if entry is None:
                entry = {"event": threading.Event(), "result": None, "exc": None}
                self._calls[key] = entry
                leader = True
            else:
                leader = False
        if not leader:
            waited = entry["event"].wait(timeout)
            if not waited:
                return None
            if entry["exc"] is not None:
                raise entry["exc"]
            return entry["result"]
        try:
            res = fn()
            entry["result"] = res
            return res
        except Exception as e:
            entry["exc"] = e
            raise
        finally:
            entry["event"].set()
            with self._lock:
                if self._calls.get(key) is entry:
                    del self._calls[key]
_CDN_REFRESH_FLIGHT = _SingleFlight()
def _cdn_refresh_key(link):
    """clave single-flight de un enlace: la misma que la cache del carrusel (base sin #dlpy_carousel=N,
    normalizado si es IDMM), para que el medio 1 y el medio 2 del mismo carrusel compartan la renovacion."""
    try:
        return _carousel_cache_key(link)
    except Exception:
        try:
            return str(link or "").strip().split("#dlpy_carousel=")[0].split("#")[0].strip()
        except Exception:
            return str(link or "")
def run_download(ydl, yt_dlp, info, link, fmt_id, is_foto=False):
    """Descarga con el MISMO analisis que vio el usuario (asi los format_id coinciden). la vigencia NO
    se decide por edad (INFO_TTL eliminado) sino por la caducidad `oe`/`ext` que el CDN declara en la URL:
    - Proactivo: si la URL del formato elegido caduca dentro de DLPY_CDN_EXPIRY_MARGIN (600 s), se renueva UNA vez
      (extract_info download=False, single-flight) y se sigue con la info fresca, sin perder el format_id.
      Si esa renovacion falla o agota la espera, se intenta con el analisis previo: puede que siga bueno
      (el margen es conservador) y el reactivo cubre si no.
    - Primer intento: siempre con el analisis que hay (process_ie_result, sin re-extraer).
    - Reactivo: UN solo reintento si ese intento falla con 403/410 real o no devuelve archivo: renovacion
      single-flight (extract_info download=False) + process_ie_result con esa info fresca. Si la info fresca
      ya no trae el formato elegido, se usa esa MISMA info fresca con el formato de respaldo
      (process_ie_result, sin volver a extraer). Sin segundo intento ni segundo extract."""
    import copy
    def clone():
        try:
            return copy.deepcopy(info)
        except Exception as _ign:
            ignore("clone", _ign)
            return dict(info)
    def _fresh_extract():
        """UNA renovacion (extract_info download=False) compartida por single-flight. Devuelve la info
        fresca sellada, None si un seguidor agoto la espera (30 s), o propaga la excepcion del lider."""
        _key = _cdn_refresh_key(link)
        fresh = _CDN_REFRESH_FLIGHT.run(_key, lambda: ydl.extract_info(link, download=False))
        if fresh is None:
            return None
        _stamp_cdn_expiry(fresh)
        return fresh
    def _use_fresh(fresh):
        """sustituir `info` en su sitio por la info fresca (misma identidad: la cache del carrusel
        y run.info ven la info fresca sin reasignar). Devuelve True si se sustituyo."""
        try:
            if not isinstance(info, dict) or not isinstance(fresh, dict):
                return False
            info.clear()
            info.update(fresh)
            _stamp_cdn_expiry(info)
            try:
                _CAROUSEL_INFO_CACHE[_carousel_cache_key(link)] = info
            except Exception:
                pass
            ANALYSIS["t"] = time.monotonic()
            return True
        except Exception as _ign:
            ignore("use_fresh", _ign)
            return False
    _foto = bool(is_foto)
    try:
        if str((info or {}).get('_carousel_kind') or '').lower() == 'foto':
            _foto = True
        else:
            _fmts = (info or {}).get('formats') or []
            _sel = [f for f in _fmts if str(f.get('format_id') or '') == str(fmt_id or '')] if fmt_id else []
            _cand = _sel or _fmts
            if _cand and all(str((f or {}).get('vcodec') or '').lower() == 'none' and str((f or {}).get('acodec') or '').lower() == 'none' and str((f or {}).get('ext') or '').lower() in ('jpg', 'jpeg', 'png', 'webp', 'gif', 'avif', 'bmp', 'tif', 'tiff', 'svg', 'heic', 'heif') for f in _cand):
                _foto = True
    except Exception:
        _foto = False
    try:
        if _cdn_needs_refresh(info, fmt_id):
            dbg("renovación proactiva", "la URL del formato caduca dentro del margen oe/ext: se renueva antes de bajar")
            try:
                _fresh = _fresh_extract()
            except Exception as _pe:
                dbg("renovación proactiva falló", f"se intenta con el análisis previo: {_pe}")
                _fresh = None
            if _fresh is not None:
                _use_fresh(_fresh)
            else:
                dbg("renovación proactiva sin resultado", "se intenta con el análisis previo (single-flight en espera o sin info fresca)")
    except Exception as _ign:
        ignore("proactivo", _ign)
    try:
        res = ydl.process_ie_result(clone(), download=True)
        if _dl_ok(res):
            return res
        dbg("sin archivo con el análisis previo", "yt-dlp devolvió sin error y sin archivo")
    except yt_dlp.utils.DownloadError as e:
        dbg("fallo con el análisis previo", str(e))
        if not _RETRY_RE.search(str(e).lower()):
            raise
    b = RUNTIME["bar"]
    if b is not None and b.th:
        b.reset("Reanalizando el enlace")
    else:
        m_info("Reanalizando el enlace...")
    try:
        _fresh2 = _fresh_extract()
    except Exception:
        raise
    if _fresh2 is None:
        try:
            _fresh2 = ydl.extract_info(link, download=False)
            _stamp_cdn_expiry(_fresh2)
        except Exception:
            raise
    if _use_fresh(_fresh2):
        _fresh_info = info
        res = ydl.process_ie_result(clone(), download=True)
    else:
        _fresh_info = _fresh2
        try:
            res = ydl.process_ie_result(copy.deepcopy(_fresh2), download=True)
        except Exception:
            res = ydl.process_ie_result(dict(_fresh2), download=True)
    if _dl_ok(res):
        return res
    dbg("sin archivo tras reanalizar", "yt-dlp devolvió sin error y sin archivo")
    m_warn("El formato elegido ya no está disponible; se usa el mejor equivalente.")
    ydl.params["format"] = f"{fmt_id}/bv*+ba/b"
    return ydl.process_ie_result(dict(_fresh_info), download=True)
# ───────────────────── [J1] Modo atajo (--scm / --scb) ─────────────────────
SHORTCUT_SCHEMA = 1
DASHES = "-\u2013\u2014"
VALUE_FLAGS = {"shortcutpick"}
SC_ALL_MAX = 40
SC_MORE_IDS = ("more", "all", "todos", "ver_todos")
SC_URL_MAX = 30000
SC_TIMEOUT = _env_num("DLPY_SHORTCUT_TIMEOUT", 90.0)
SCM_TIMEOUT = _env_num("DLPY_SHORTCUT_JSON_TIMEOUT", 5.0)
SCM_HARD = _env_num("DLPY_SHORTCUT_HARD_TIMEOUT", 8.0)
SCM = {"on": False, "abort": threading.Event(), "thread": None}
SCM_UNWIND = 2.0
SC_TIMING = {}
SC_PHASE = [""]
def _sc_mark(phase):
    SC_PHASE[0] = phase
def _sc_add(name, secs):
    SC_TIMING[name] = round(SC_TIMING.get(name, 0.0) + secs, 2)
def _scm_unwind():
    """Segundos que se esperan al hilo tras un timeout: SCM_UNWIND, pero sin pasar de SCM_HARD (mínimo 0,2 s)."""
    if SCM_HARD <= 0:
        return SCM_UNWIND
    return max(0.2, min(SCM_UNWIND, SCM_HARD - (time.time() - BOOT_T0)))
def norm_args(args):
    """Las rayas largas que pone el teclado de iOS (– —)"""
    out = []
    for a in args:
        if a[:1] in ("\u2013", "\u2014") and a.lstrip(DASHES)[:1].isalpha():
            a = "--" + a.lstrip(DASHES)
        out.append(a)
    return out
def parse_cli(args):
    """(banderas, posicionales)."""
    flags, pos, args, i = {}, [], list(args), 0
    while i < len(args):
        a = args[i]
        i += 1
        lead = len(a) - len(a.lstrip(DASHES))
        if lead >= 2 or (lead == 1 and a[0] in "\u2013\u2014" and len(a) > 1):
            a = "--" + a[lead:]
        if not a.startswith("--"):
            pos.append(a)
            continue
        name, eq, val = a[2:].partition("=")
        name = name.lower()
        if not name:
            continue
        if name in VALUE_FLAGS:
            if not eq and i < len(args) and not args[i].startswith(("--", "\u2014", "\u2013")):
                val, i = args[i], i + 1
            flags[name] = val
        else:
            flags[name] = val if eq else True
    return flags, pos
def _wants(args, name):
    return any(a[:1] in DASHES and a.lstrip(DASHES).lower().split("=")[0] == name for a in args)
def wants_scm(args):
    """¿Se pidió --scm? Acepta rayas largas («—scm»)."""
    return _wants(args, "scm")
def wants_scb(args):
    """¿Se pidió --scb? Acepta rayas largas («—scb»)."""
    return _wants(args, "scb")
def parse_shortcut_pick(raw):
    """Lo que devuelve el atajo:"""
    if raw is None or raw is True:
        return None
    text = str(raw).strip().strip("\"'")
    if not text:
        return None
    vals = {}
    if text.startswith("{"):
        try:
            data = json.loads(text)
        except ValueError:
            return None
        if not isinstance(data, dict):
            return None
        vals = {str(k).lower(): v for k, v in data.items()}
    else:
        for part in text.split(","):
            k, eq, v = part.partition("=")
            if eq:
                vals[k.strip().lower()] = v.strip()
    def one(*names):
        for n in names:
            if vals.get(n) is not None:
                s = urllib.parse.unquote(str(vals[n])).strip()
                if s:
                    return s
        return None
    xs = next((vals[n] for n in ("x", "extra", "extras") if n in vals), None)
    xs = list(xs) if isinstance(xs, (list, tuple)) else re.split(r"[+\s]+", str(xs or ""))
    xs = [urllib.parse.unquote(str(x)).strip() for x in xs]
    pick_ = {"v": one("v", "video"), "a": one("a", "audio", "track"), "x": [x for x in xs if x]}
    return pick_ if (pick_["v"] or pick_["a"] or pick_["x"]) else None
def split_formats(info):
    """(formatos, audios, videos) como los usa la lista de siempre (de peor a mejor calidad)."""
    formats = [normalize_format(f) for f in (info.get("formats") or [])
               if f.get("ext") != "mhtml" and "storyboard" not in (f.get("format_note") or "")]
    audios = [f for f in formats if has(f.get("acodec")) and not has(f.get("vcodec"))]
    videos = [f for f in formats if has(f.get("vcodec"))]
    audios.sort(key=abr_of)
    videos.sort(key=lambda f: (f.get("height") or 0, f.get("tbr") or 0))
    return formats, audios, videos
APPLE_MARK = "\uf8ff"
APPLE_MARK_UNSURE = APPLE_MARK + "?"
FLAG_MARKS["logo"], FLAG_COLORS["logo"], FLAG_TEXT["logo"] = APPLE_MARK, "mint", FLAG_TEXT["apple"]
FLAG_MARKS["logo?"], FLAG_COLORS["logo?"], FLAG_TEXT["logo?"] = APPLE_MARK_UNSURE, "amber", FLAG_TEXT["apple"]
def apple_row_mark(r):
    """1.9.9: la marca de manzana de una fila de la lista: compatible (), sin comprobar (?) o vacía."""
    return flag_mark("logo?") if "unsure" in r["flags"] else flag_mark("logo") if "apple" in r["flags"] else ""
def apple_col_width(rows):
    """1.9.9: ancho de la columna de manzana: 2 si alguna fila lleva «?», 1 si no."""
    return 2 if any("unsure" in r["flags"] for r in rows) else 1
def apple_tag(f, ok):
    """Manzana (compatible, `ok`), manzana con ? (códec sin determinar) o nada; con espacio delante si hay marca."""
    return " " + (APPLE_MARK_UNSURE if apple_unsure(f) else APPLE_MARK) if (ok or apple_unsure(f)) else ""
def shortcut_fps(f):
    try:
        v = float(f.get("fps") or 0)
    except (TypeError, ValueError):
        return 0
    return int(round(v)) if v > 0 else 0
def shortcut_quality_key(f):
    """Una entrada por resolución + fps (1080p 60fps y 1080p 30fps son distintas); el HDR o los más de 8 bits cuentan aparte, como en…"""
    bits = detect_bit_depth(f)
    return (f.get("height") or format_tag(f), shortcut_fps(f),
            detect_hdr(f) or "", bits if bits and bits > 8 else 0)
def shortcut_kbps(f):
    """Bitrate total en kbps (tbr, o vbr + abr) o None si el formato no lo informa."""
    try:
        v = float(f.get("tbr") or 0) or (float(f.get("vbr") or 0) + float(f.get("abr") or 0))
    except (TypeError, ValueError):
        return None
    return v if v > 0 else None
def size_estimate(kbps, secs):
    """«~12 MB»: tamaño aproximado = bitrate × duración. None si falta alguno de los dos."""
    try:
        if not kbps or not secs or float(secs) <= 0:
            return None
        return "~" + human_size(kbps * 1000 / 8 * float(secs))
    except (TypeError, ValueError):
        return None
def k_label(f):
    """«2K», «4K», «8K», «16K»"""
    try:
        h, w = int(f.get("height") or 0), int(f.get("width") or 0)
    except (TypeError, ValueError):
        return None
    m = min(h, w) if (h and w) else h
    for lim, name in ((8000, "16K"), (4000, "8K"), (2000, "4K"), (1400, "2K")):
        if m >= lim:
            return name
    return None
def shortcut_video_name(f):
    """«1080p 60fps», «4K 2160p 30fps HDR10»: (K) resolución + fps (+ rango si no es SDR de 8 bits)."""
    h = f.get("height")
    s = f"{h}p" if h else format_tag(f)
    k = k_label(f)
    if k:
        s = f"{k} {s}"
    if shortcut_fps(f):
        s += f" {shortcut_fps(f)}fps"
    hdr, bits = detect_hdr(f), detect_bit_depth(f)
    if hdr:
        s += f" {hdr}"
    elif bits and bits > 8:
        s += f" {bits}b"
    return s
def shortcut_track_name(t):
    f = t["fmt"]
    name = track_label(t)
    if t["original"]:
        name = re.sub(r"\s*\boriginal\b\s*$", "", name, flags=re.I) or name
    lead = name if name == t["lang"] else f"{name} · {t['lang']}"
    abr = abr_of(f)
    tech = f"{f.get('ext') or '?'} {acodec_short(f)}" + (f" {abr:.0f}k" if abr else "")
    return lead + (t_display(" · original") if t["original"] else "") + f" · {tech}" + apple_tag(f, apple_audio(f))
def best_audio(audios, orig_ids=()):
    """El audio de mejor calidad:"""
    pool = [f for f in audios if f.get("format_id") in orig_ids] or list(audios)
    return max(pool, key=lambda f: (abr_of(f), apple_audio(f)), default=None)
def shortcut_audio_items(audios, orig_ids, duration=None):
    """Todos los audios para el JSON:"""
    best = best_audio(audios, orig_ids)
    order = sorted(audios, key=lambda f: (f.get("format_id") not in orig_ids, str(f.get("language") or ""),
                                          -abr_of(f), not apple_audio(f), str(f.get("format_id"))))
    out = []
    for n, f in enumerate(order, 1):
        abr = abr_of(f)
        size = f.get("filesize") or f.get("filesize_approx")
        size_t = human_size(size) if size else size_estimate(abr, duration)
        lang = f.get("language") or ""
        is_best = f is best
        tech = f"{f.get('ext') or '?'} {acodec_short(f)}" + (f" {abr:.0f}k" if abr else "")
        parts = [("★ " if is_best else "") + (lang or t_display("audio")), tech, size_t]
        orig = f.get("format_id") in orig_ids
        if orig:
            parts.insert(2, t_display("original"))
        label = f"{n} · " + " · ".join(p for p in parts if p) + apple_tag(f, apple_audio(f))
        out.append({"n": n, "id": str(f.get("format_id")), "label": label, "lang": lang or None,
                    "ext": f.get("ext"), "codec": acodec_short(f),
                    "abr": round(abr) if abr else None, "size_bytes": size, "size": human_size(size) if size else None,
                    "size_est": None if size else size_t, "original": orig, "compatible": bool(apple_audio(f)),
                    "unsure": apple_unsure(f), "best": is_best})
    return out
def shortcut_error(code, msg, link=None, elapsed=None):
    msg = t_display(msg)
    out = {"dlpy": "shortcutmode", "schema": SHORTCUT_SCHEMA, "ok": False, "status": "error", "version": VERSION,
           "link": link, "error_code": code, "error": msg}
    if elapsed is not None:
        out["elapsed"] = elapsed
    return out
SC_TITLE_MAX = 60
def short_title(title, limit=SC_TITLE_MAX):
    """Título corto para el mensaje del menú de Atajos:"""
    t = re.sub(r"\s+", " ", str(title or "")).strip()
    t = re.sub(r"^[\d.,]+\s*[KMB]?\s*(?:views?|vistas|reproducciones|plays|likes)\b[^|]*\|\s*", "", t, flags=re.I)
    t = re.sub(r"https?://\S+", "", t)
    t = re.sub(r"\s*#\w+", "", t)
    t = re.sub(r"\s+", " ", t).strip(" |-·")
    first = re.split(r"(?<=[.!?])\s", t, maxsplit=1)[0].rstrip(".!? ")
    if 12 <= len(first) <= limit:
        return first
    if len(t) <= limit:
        return t or str(title or "video")[:limit]
    cut = t[:limit + 1]
    cut = cut[:cut.rfind(" ")] if " " in cut[:limit + 1] and cut.rfind(" ") > limit // 2 else t[:limit]
    return cut.rstrip(" ,;:.-·|") + "…"
def audio_desc(f):
    """«m4a mp4a 44k» (+ idioma si lo hay): lo que se baja de ese audio."""
    abr = abr_of(f)
    s = f"{f.get('ext') or '?'} {acodec_short(f)}" + (f" {abr:.0f}k" if abr else "")
    lang = f.get("language")
    return s + (f" {lang}" if lang else "")
def video_desc(f):
    """«1920p vp09», «1 mp4 con audio» (sin resolución: el id de yt-dlp tal cual): resolución/etiqueta + códec (o contenedor si no hay códec)."""
    name = shortcut_video_name(f)
    vc = str(f.get("vcodec") or "unknown").split(".")[0]
    if vc.lower() in ("unknown", "?", "none", ""):
        return f"{name} {f.get('ext') or '?'}" + (tr_fragment(" con audio") if has(f.get("acodec")) else "")
    return f"{name} {vc}"
def ytdlp_auto_pick(info, audios, videos):
    """Lo que bajaría yt-dlp con su formato por omisión «bv*+ba/b»:"""
    ids = []
    for x in (info.get("requested_formats") or []):
        ids.append(str(x.get("format_id")))
    if not ids and info.get("format_id"):
        ids = [p for p in str(info["format_id"]).split("+") if p]
    if not ids:
        return None
    vsel = next((f for i in ids for f in videos if str(f.get("format_id")) == i), None)
    if vsel is None:
        return None
    asel = None
    if not has(vsel.get("acodec")):
        asel = next((f for i in ids for f in audios if str(f.get("format_id")) == i), None)
    return vsel, asel
def _sc_pick_videos(videos, bk, bf, can_merge):
    """Un video por calidad (la mejor opción de cada grupo), de mayor a menor resolución."""
    groups = {}
    for f in videos:
        groups.setdefault(shortcut_quality_key(f), []).append(f)
    def rank(f):
        return (has(f.get("acodec")) if not can_merge else False, bool(apple_video(f)),
                f.get("tbr") or 0)
    picked = [bf if bk == "v" and any(x is bf for x in g) else max(g, key=rank) for g in groups.values()]
    return _sc_sort_videos(picked)
def _sc_sort_videos(vs):
    """Orden del menú del atajo: de mayor a menor resolución, fps y bitrate."""
    return sorted(vs, key=lambda f: (-(f.get("height") or 0), -shortcut_fps(f), bool(detect_hdr(f)),
                                     -(shortcut_kbps(f) or 0), str(f.get("format_id"))))
def _sc_history(old_file, old_entry, history):
    """Lo ya descargado de este video:"""
    old_meta = (old_entry or {}).get("meta") or {} if old_file else {}
    hist = list(history) if history is not None else ([(old_file, old_entry)] if old_file else [])
    got_video = {str(((e.get("meta") or {}).get("format_id") or "")).split("+")[0]
                 for _p, e in hist if ((e.get("meta") or {}).get("kind")) == "video"}
    got_audio = any(((e.get("meta") or {}).get("kind")) == "audio" for _p, e in hist)
    got_langs = {str(tr.get("lang")) for _p, e in hist for tr in ((e.get("meta") or {}).get("tracks") or [])
                 if tr.get("lang")}
    return old_meta, hist, got_video, got_audio, got_langs
def _sc_video_item(f, info, bk, bf, can_tracks, multi_lang, got_video):
    """Entrada de la lista de videos del atajo para un formato."""
    has_a = has(f.get("acodec"))
    size = f.get("filesize") or f.get("filesize_approx")
    kbps = shortcut_kbps(f)
    return {
        "id": str(f.get("format_id")), "name": shortcut_video_name(f), "height": f.get("height"),
        "fps": shortcut_fps(f) or None, "ext": f.get("ext"),
        "vcodec": ((f.get("vcodec") or "?").split(".")[0] if str(f.get("vcodec") or "unknown").lower()
                   not in ("unknown", "?")
                   else (f"{f.get('ext') or '?'} · {t('con audio')}" if has_a else (f.get("ext") or "?"))),
        "k": k_label(f), "range": range_label(f) or None, "hdr": detect_hdr(f), "size_bytes": size,
        "size": human_size(size) if size else None, "compatible": bool(apple_video(f)),
        "unsure": apple_unsure(f), "kbps": round(kbps) if kbps else None,
        "size_est": None if size else size_estimate(kbps, info.get("duration")),
        "audio": "included" if has_a else ("separate" if can_tracks else "none"),
        "audio_step": "none" if (has_a or not can_tracks or not multi_lang) else "full",
        "best": bk == "v" and f is bf,
        "have": str(f.get("format_id")) in got_video}
def _sc_auto_item(info, audios, videos, hist):
    """Opción «yt-dlp auto»: (entrada o None, extras_error)."""
    try:
        got_ids = {str((e.get("meta") or {}).get("format_id") or "") for _p, e in hist}
        auto = ytdlp_auto_pick(info, audios, videos)
    except Exception as e:
        return None, f"auto: {type(e).__name__}: {e}"
    if not auto:
        return None, None
    av, aa = auto
    aid = "+".join([str(av.get("format_id"))] + ([str(aa.get("format_id"))] if aa else []))
    desc = video_desc(av) + (f" + {audio_desc(aa)}" if aa else "")
    return {
        "id": "ytdlp", "name": "yt-dlp auto", "height": av.get("height"), "fps": shortcut_fps(av) or None,
        "ext": av.get("ext"), "vcodec": desc, "k": k_label(av), "range": range_label(av) or None, "hdr": detect_hdr(av),
        "size_bytes": None, "size": None,
        "compatible": bool(apple_video(av)) and (aa is None or bool(apple_audio(aa))),
        "unsure": apple_unsure(av) or (aa is not None and apple_unsure(aa)),
        "audio": "separate" if aa else "included", "audio_step": "none", "best": False,
        "have": aid in got_ids,
        "auto": {"video_id": str(av.get("format_id")), "audio_id": str(aa.get("format_id")) if aa else None,
                 "video": video_desc(av), "audio": audio_desc(aa) if aa else None, "formato": aid}}, None
def _sc_audio_items(audios, tracks, orig_ids, bk, multi_lang, got_audio, extras_error):
    """Opciones «Solo audio»"""
    if not audios:
        return [], extras_error
    items = []
    solo_audio = ""
    _ba = _ap = None
    try:
        _ba = best_audio(audios, orig_ids)
        _t = next((t for t in tracks if t["original"]), tracks[0] if tracks else None)
        _ap = _t["fmt"] if _t else None
        if _ba is not None and (_ap is None or (apple_audio(_ba) and not apple_audio(_ap))
                                or not any(apple_audio(f) for f in audios)):
            _ap = _ba
        solo_audio = audio_desc(_ap) if _ap else ""
    except Exception as e:
        extras_error = f"solo audio: {type(e).__name__}: {e}"
    _ap_ok = _ap is not None and bool(apple_audio(_ap))
    _same = _ba is None or _ap is None or _ba is _ap or (apple_audio(_ba) and _ap_ok)
    items.append({
        "id": "audio", "name": t_display("Solo audio"),
        "range": None, "hdr": None, "size_bytes": None, "size": None,
        "compatible": _ap_ok, "unsure": _ap is not None and apple_unsure(_ap), "audio": "only",
        "audio_step": "track" if multi_lang else "none", "best": bk == "a",
        "have": got_audio, "detail": solo_audio or None})
    if not _same:
        items.append({
            "id": "audio_best", "name": t_display("Solo audio (mejor)"),
            "vcodec": None, "range": None, "hdr": None, "size_bytes": None, "size": None,
            "compatible": bool(apple_audio(_ba)), "unsure": apple_unsure(_ba), "audio": "only",
            "audio_step": "track" if multi_lang else "none", "best": False, "ask_convert": True,
            "have": False, "detail": audio_desc(_ba)})
    return items, extras_error
def _sc_menu_label(n, it, v_items, audio_is_best):
    """Texto del menú de Atajos para la opción `it` (número, nombre y marcas 🔊 🔇 Apple ✅)."""
    marks = ((" 🔊" if it.get("audio") == "included" else " 🔇" if it.get("audio") == "none" else "")
             + (f" {APPLE_MARK_UNSURE}" if it.get("unsure") else f" {APPLE_MARK}" if it.get("compatible") else "")
             + (" ✅" if it.get("have") else ""))
    if it["id"] in ("audio", "audio_best"):
        two = any(o["id"] == "audio_best" for o in v_items)
        head = (t_display("Solo audio · Apple") if it["id"] == "audio" else t_display("★ Solo audio · mejor")) if two else (
            t_display("★ Solo audio · mejor") if audio_is_best else t_display("Solo audio"))
        return f"{n} · ♫ {head}" + (f" · {it['detail']}" if it.get("detail") else "") + marks
    if it["id"] == "ytdlp":
        same = next((o["n"] for o in v_items if o.get("n") and o["id"] == it["auto"]["video_id"]), None)
        return f"{n} · yt-dlp auto · {it['vcodec']}" + (f" (= {same})" if same else "") + marks
    vc = str(it["vcodec"] or "")
    vc = re.sub(r"\s*·\s*(?:" + re.escape(t("con audio")) + r"|con audio)$", "", vc)
    parts = [("★ " if it["best"] else "") + it["name"], vc]
    if not it.get("height") and it.get("kbps"):
        parts.append(kbps_text(it["kbps"]))
    parts.append(it["size"] or it.get("size_est"))
    return f"{n} · " + " · ".join(p for p in parts if p) + marks
def _sc_track_items(tracks, got_langs):
    """Pistas de audio del video (para elegir la predeterminada y las extra)."""
    t_items = []
    for n, t in enumerate(tracks, 1):
        f = t["fmt"]
        got = str(t["lang"]) in got_langs
        t_items.append({"n": n, "id": t["lang"], "lang": t["lang"], "have": got,
                        "label": f"{n} · {t_display(shortcut_track_name(t))}" + (" ✅" if got else ""),
                        "format_id": str(f.get("format_id")), "ext": f.get("ext"),
                        "codec": acodec_short(f),
                        "abr": round(abr_of(f)) if abr_of(f) else None,
                        "original": bool(t["original"]), "compatible": bool(apple_audio(f)), "unsure": apple_unsure(f)})
    return t_items
def _sc_duration(dur):
    """(segundos enteros o None, texto «m:ss» / «h:mm:ss» o None)."""
    try:
        d = int(dur) if dur else None
    except (TypeError, ValueError):
        d = None
    dur_text = (f"{d // 3600}:{d % 3600 // 60:02d}:{d % 60:02d}" if d and d >= 3600
                else f"{d // 60}:{d % 60:02d}" if d is not None else None)
    return d, dur_text
def _sc_number(items, audio_is_best):
    """Numera `items` (1…n) y les pone su etiqueta de menú."""
    for n, it in enumerate(items, 1):
        it["n"] = n
        it["label"] = t_display(_sc_menu_label(n, it, items, audio_is_best))
def _sc_view_all(info, videos, v_items, bk, bf, can_tracks, multi_lang, got_video, audio_is_best):
    """«Ver todos»:"""
    all_items = []
    more_n = len(videos) - sum(1 for it in v_items if it["id"] not in ("ytdlp", "audio", "audio_best"))
    if more_n <= 0:
        return all_items, more_n
    if len(videos) <= SC_ALL_MAX:
        all_items = [_sc_video_item(f, info, bk, bf, can_tracks, multi_lang, got_video)
                     for f in _sc_sort_videos(videos)]
        all_items += [dict(it) for it in v_items if it["id"] in ("ytdlp", "audio", "audio_best")]
        _sc_number(all_items, audio_is_best)
    n_more = len(v_items) + 1
    v_items.append({"id": "more", "name": t_display("Ver todos"),
                    "range": None, "hdr": None, "size_bytes": None, "size": None, "compatible": False, "unsure": False,
                    "audio": "none", "audio_step": "none", "best": False, "have": False, "more": True,
                    "n": n_more, "label": f"{n_more} \u00b7 \u25b8 {t_display('Ver todos')} (+{more_n})"})
    return all_items, more_n
def _sc_previous(old_file, old_entry, old_meta, hist):
    """(la copia ya descargada o None, lista de descargas anteriores) para el JSON del atajo."""
    old = ({"file": os.path.basename(old_file), "title": (old_entry or {}).get("title"),
            "date": (old_entry or {}).get("date"), "kind": old_meta.get("kind"), "format_id": old_meta.get("format_id")}
           if old_file else None)
    downloaded = [{"file": os.path.basename(pth), "kind": (e.get("meta") or {}).get("kind"),
                   "format_id": (e.get("meta") or {}).get("format_id"), "date": e.get("date")} for pth, e in hist]
    return old, downloaded
def _sc_pick_example(v_items, t_items, multi_lang):
    """Ejemplo de la elección que devuelve el atajo: v=<mejor video>,a=<pista>,x=<pista extra>."""
    return ("v=" + next((it["id"] for it in v_items if it["best"]), v_items[0]["id"])
            + (f",a={t_items[0]['id']}" if t_items and multi_lang else ",a=")
            + (f",x={t_items[1]['id']}" if len(t_items) > 1 and multi_lang else ",x="))
def build_shortcut_payload(info, link, can_merge, old_file=None, old_entry=None, history=None):
    """El JSON que lee el atajo."""
    _formats, audios, videos = split_formats(info)
    if not audios and not videos:
        _foto = _carousel_foto_fmt(info)
        if _foto:
            videos = [_foto]
            _formats = [_foto]
        else:
            return shortcut_error("no_formats", t_display("No se encontraron formatos."), link)
    orig_ids = mark_originals(audios)
    tracks, orig_lang = build_tracks(audios, orig_ids)
    multi_lang = len({t["lang"] for t in tracks if t["lang"] != "und"}) > 1
    bk, bf = auto_best(audios, videos, orig_ids, can_merge, quiet=True)
    can_tracks = bool(tracks) and bool(can_merge)
    picked = _sc_pick_videos(videos, bk, bf, can_merge)
    old_meta, hist, got_video, got_audio, got_langs = _sc_history(old_file, old_entry, history)
    v_items = [_sc_video_item(f, info, bk, bf, can_tracks, multi_lang, got_video) for f in picked]
    auto_item, extras_error = _sc_auto_item(info, audios, videos, hist)
    if auto_item:
        v_items.append(auto_item)
    a_extra, extras_error = _sc_audio_items(audios, tracks, orig_ids, bk, multi_lang, got_audio, extras_error)
    v_items.extend(a_extra)
    audio_is_best = bool(audios) and not any(o["id"] == "audio_best" for o in v_items)
    _sc_number(v_items, audio_is_best)
    all_items, more_n = _sc_view_all(info, videos, v_items, bk, bf, can_tracks, multi_lang, got_video, audio_is_best)
    t_items = _sc_track_items(tracks, got_langs)
    t_labels = [it["label"] for it in t_items]
    a_items = shortcut_audio_items(audios, orig_ids, info.get("duration"))
    extra_menu = {str(i): [lab for j, lab in enumerate(t_labels, 1) if j != i] for i in range(1, len(t_labels) + 1)}
    d, dur_text = _sc_duration(info.get("duration"))
    old, downloaded = _sc_previous(old_file, old_entry, old_meta, hist)
    return {
        **({"extras_error": extras_error} if extras_error else {}),
        "dlpy": "shortcutmode", "schema": SHORTCUT_SCHEMA, "ok": True, "status": "ok", "version": VERSION, "platform": PLATFORM,
        "link": link, "title": info.get("title") or "video", "title_short": short_title(info.get("title")),
        "id": info.get("id"),
        "extractor": info.get("extractor_key") or info.get("extractor"),
        "uploader": info.get("uploader") or info.get("channel"), "duration": d, "duration_text": dur_text,
        "thumbnail": info.get("thumbnail"), "key": video_key(info), "already_downloaded": old, "downloaded": downloaded,
        "can_merge": bool(can_merge), "multi_lang": multi_lang, "original_lang": orig_lang,
        "prompt": " · ".join(x for x in (short_title(info.get("title")), dur_text) if x),
        "default_video": next((it["n"] for it in v_items if it["best"]), 1),
        "default_track": next((it["n"] for it in t_items if it["original"]), 1) if t_items else None,
        "video_labels": [it["label"] for it in v_items], "video_ids": [it["id"] for it in v_items],
        "video_audio_step": [it["audio_step"] for it in v_items],
        "has_more": more_n > 0, "more_count": max(0, more_n), "more_id": "more",
        "more_label": f"\u25b8 {t_display('Ver todos')} (+{more_n})" if more_n > 0 else None,
        "all_in_script": more_n > 0 and not all_items,
        "all_video_labels": [it["label"] for it in all_items], "all_video_ids": [it["id"] for it in all_items],
        "all_video_audio_step": [it["audio_step"] for it in all_items],
        "all_default_video": next((it["n"] for it in all_items if it["best"]), 1) if all_items else None,
        "track_labels": t_labels, "track_ids": [it["id"] for it in t_items], "extra_menu": extra_menu,
        "audio_labels": [it["label"] for it in a_items], "audio_ids": [it["id"] for it in a_items],
        "default_audio": next((it["n"] for it in a_items if it["best"]), None),
        "ask_convert": any(it["best"] and not it["compatible"] for it in a_items),
        "videos": v_items, "tracks": t_items, "audios": a_items, "all_videos": all_items,
        "pick_format": "v=<video_ids[n]>,a=<track_ids[n]>,x=<track_ids[n]>+<track_ids[m]>"
                       + {"es": " (con v=audio, a=<audio_ids[n]> elige ese audio exacto; v=more abre la lista completa)", "en": " (with v=audio, a=<audio_ids[n]> picks that exact audio; v=more opens the full list)", "pt": " (com v=audio, a=<audio_ids[n]> escolhe esse áudio exato; v=more abre a lista completa)", "fr": " (avec v=audio, a=<audio_ids[n]> choisit cet audio exact ; v=more ouvre la liste complète)", "de": " (mit v=audio wählt a=<audio_ids[n]> genau dieses Audio; v=more öffnet die vollständige Liste)", "it": " (con v=audio, a=<audio_ids[n]> sceglie quell audio esatto; v=more apre elenco completo)", "pl": " (z v=audio, a=<audio_ids[n]> wybiera dokładnie to audio; v=more otwiera pełną listę)"}.get(LANG, " (con v=audio, a=<audio_ids[n]> elige ese audio exacto; v=more abre la lista completa)"),
        "pick_example": _sc_pick_example(v_items, t_items, multi_lang)}
def _sc_prepare(box):
    """1.2.1:"""
    t0 = time.time()
    with quiet("_sc_prepare argv"):
        box["argv"] = user_argv()
    _sc_add("prep", time.time() - t0)
SCM_DROP_KEYS = ("already_downloaded", "downloaded", "pick_format", "pick_example", "stage")
def slim_scm(data):
    """1.6.0: el JSON de --scm solo lleva lo que dice yt-dlp y lo que el atajo necesita para elegir (videos, pistas de idioma, extras, audios,
    «Ver todos»). Fuera: lo de descargas previas, las marcas «have» y los textos de ayuda del script."""
    for k in SCM_DROP_KEYS:
        data.pop(k, None)
    for lst in ("videos", "all_videos", "audios", "tracks"):
        for it in data.get(lst) or []:
            if isinstance(it, dict):
                it.pop("have", None)
    return data
def shortcut_collect(link):
    """Analiza `link` y devuelve el diccionario de salida (siempre uno, nunca lanza)."""
    t0 = time.time()
    def done(data):
        data["elapsed"] = round(time.time() - t0, 1)
        return data
    link = (link or "").strip()
    if is_idmm_link(link):
        link = idmm_normalize_link(link)
    if not link:
        return done(shortcut_error("no_link", "No hay enlace: usa --scb LINK o --scm LINK."))
    prep, pth = {}, None
    if SCM["on"]:
        pth = threading.Thread(target=_sc_prepare, args=(prep,), name="dlpy-scm-prep", daemon=True)
        pth.start()
    _sc_mark("import")
    _t_i = time.time()
    try:
        import yt_dlp
        net_wrap_ytdlp(yt_dlp)
    except Exception as e:
        err = shortcut_error("no_ytdlp", f"yt-dlp no está instalado ({e}). Usa --scb: lo instala.", link)
        err["use_scb"] = True
        return done(err)
    _sc_add("imp", time.time() - _t_i)
    ff = {}
    def _probe_ffmpeg():
        _t = time.time()
        with quiet("shortcut_collect ffmpeg"):
            ff["ok"] = bool(ffmpeg_available())
        _sc_add("ff", time.time() - _t)
    fth = threading.Thread(target=_probe_ffmpeg, name="dlpy-ffmpeg", daemon=True)
    fth.start()
    if not SCM["on"]:
        with quiet("shortcut_collect", OSError):
            os.makedirs(STATE_DIR, exist_ok=True)
    if pth is not None:
        pth.join()
    ANALYSIS["stage"] = None
    try:
        info, _base = analyze_link(yt_dlp, link, quick=True, argv=prep.get("argv"))
    except KeyboardInterrupt:
        raise
    except Exception as e:
        return done(shortcut_error("bot" if is_bot_error(e) else "analyze",
                                   str(e).strip()[:400] or "error al analizar", link))
    if info.get("_idmm"):
        return done(idmm_scm_json(link, site=idmm_site_name(link, info)))
    if info.get("entries"):
        info = next((e for e in info["entries"] if e), info)
    _sc_mark("build")
    _t_b = time.time()
    key = video_key(info)
    if SCM["on"]:
        old_file, old_entry, hist_ = None, None, []
    else:
        idx = load_json(INDEX_FILE)
        old_file, old_entry = lookup_downloaded(idx, key)
        hist_ = history_for(key, idx, None)
    fth.join(3.0)
    can_merge = ff["ok"] if "ok" in ff else bool(tool_executable("ffmpeg"))
    data = build_shortcut_payload(info, link, can_merge, old_file, old_entry, hist_)
    with quiet("shortcut_remember"):
        shortcut_remember(key, data)
    _sc_add("build", time.time() - _t_b)
    data["stage"] = ANALYSIS["stage"]
    if SCM["on"]:
        slim_scm(data)
    return done(data)
def collect_with_timeout(link, secs=None, fn=None):
    """shortcut_collect con tope de tiempo (SC_TIMEOUT):"""
    fn = fn or shortcut_collect
    secs = SC_TIMEOUT if secs is None else secs
    box = {}
    def work():
        try:
            box["data"] = fn(link)
        except BaseException as e:
            box["data"] = shortcut_error("crash", f"{type(e).__name__}: {e}", link)
    t0 = time.time()
    th = threading.Thread(target=work, daemon=True)
    SCM["thread"] = th
    th.start()
    th.join(secs if secs and secs > 0 else None)
    if th.is_alive():
        return shortcut_error("timeout", f"El análisis tardó más de {secs:g} s.", link, round(time.time() - t0, 1))
    return box.get("data") or shortcut_error("crash", "el análisis no devolvió nada", link)
def write_shortcut_json(data):
    """Copia legible de la última salida (state/shortcut_analysis.json)."""
    with quiet("write_shortcut_json", OSError):
        os.makedirs(STATE_DIR, exist_ok=True)
        with open(SHORTCUT_JSON, "w", encoding="utf-8") as fh:
            json.dump(json_clean(data), fh, ensure_ascii=False, indent=2)
def shortcut_mode(flags, pos):
    """`--scm LINK`:"""
    link = pos[0] if pos else None
    ensure_dirs()
    if sc_list_mode():
        sys.stdout.write(json.dumps(sc_list_scm_json(link), ensure_ascii=True, separators=(",", ":")) + "\n")
        sys.stdout.flush()
        return 0
    if not str(link or "").strip():
        # 2.0.8: el atajo no pasó enlace (p. ej. al compartir desde Facebook). --scm no toca el portapapeles (corre sin pantalla y el aviso de pegado de iOS
        # lo dejaría esperando): responde al instante que siga con --scb, que sí abre a-Shell y ahí lee el portapapeles.
        _nl = {"dlpy": "shortcutmode", "schema": 1, "ok": True, "status": "scb", "version": VERSION, "link": "",
               "error_code": "no_link_scb", "message": "Sin enlace: sigue con --scb (lee el portapapeles).", "use_scb": True}
        sys.stdout.write(json.dumps(_nl, ensure_ascii=True, separators=(",", ":")) + "\n")
        sys.stdout.flush()
        return 0
    real_out, real_err = sys.stdout, sys.stderr
    sink = open(os.devnull, "w", encoding="utf-8")
    sys.stdout = sys.stderr = sink
    SCM["on"] = True
    SC_TIMING["boot"] = round(time.time() - BOOT_T0, 2)
    data = None
    try:
        left = max(1.0, SCM_TIMEOUT - (time.time() - BOOT_T0)) if SCM_TIMEOUT > 0 else None
        data = collect_with_timeout(link, secs=left)
        if data and data.get("error_code") == "timeout":
            data["ok"] = True
            data["status"] = "scb"
            data["use_scb"] = True
            data["message"] = t_display("El análisis tardó demasiado para --scm; usa --scb.")
            data.pop("error", None)
    except KeyboardInterrupt:
        data = shortcut_error("cancelled", "Cancelado.", link)
    except BaseException as e:
        data = shortcut_error("crash", f"{type(e).__name__}: {e}", link)
    finally:
        sys.stdout, sys.stderr = real_out, real_err
        if data_is_final(data):
            sink.close()
    if isinstance(data, dict):
        SC_TIMING["total"] = round(time.time() - BOOT_T0, 2)
        data["timing"] = dict(SC_TIMING)
        if not data_is_final(data):
            data["phase"] = SC_PHASE[0]
    text = json.dumps(json_clean(data), ensure_ascii=True, separators=(",", ":"))
    if not data_is_final(data):
        real_out.write(text + "\n")
        real_out.flush()
        SCM["abort"].set()
        th = SCM.get("thread")
        if th is not None:
            th.join(_scm_unwind())
        return 0
    if flags.get("shortcutclip"):
        shortcut_copy(text)
    real_out.write(text + "\n")
    real_out.flush()
    if DEBUG or _flag_env("DLPY_SHORTCUT_JSON_SAVE", False):
        write_shortcut_json(data)
    return 0
def data_is_final(data):
    return bool(data) and data.get("error_code") != "timeout"
def shortcut_send(data, name=None):
    """Abre shortcuts://run-shortcut?name=… con el JSON como entrada (sin «videos», «tracks»"""
    name = name or SHORTCUT_NAME
    slim = {k: v for k, v in data.items() if k not in ("videos", "tracks", "audios", "all_videos")}
    text = json.dumps(json_clean(slim), ensure_ascii=True, separators=(",", ":"))
    url = ("shortcuts://run-shortcut?name=" + urllib.parse.quote(name)
           + "&input=text&text=" + urllib.parse.quote(text, safe=""))
    how = "url"
    if len(url) > SC_URL_MAX and shortcut_copy(text):
        url, how = shortcut_clip_url(name), "portapapeles"
    dbg("scb", {"via": how, "bytes": len(text), "url": url[:80]})
    sh_run("open " + ash_quote(url))
    return how
SCB_NOTES = ("El análisis rápido se quedó sin tiempo", "Seguimos sin límite de tiempo", "Analizando enlace · puede tardar más")
def scb_clear():
    """--scb nunca usa native_clear (la consola es del atajo): borra con la secuencia directa."""
    with quiet("scb_clear"):
        if sys.stdout.isatty():
            sys.stdout.write(RESET + "\x1b[2J" + PURGE_SEQ + "\x1b[H" + CURSOR_SHOW)
            sys.stdout.flush()
def scb_diag(**kw):
    """1.0.1: deja en state/scb_debug.json por qué la escena de --scb arrancó o no (si vuelve a verse en negro, ese archivo lo dice)."""
    with quiet("scb_diag"):
        os.makedirs(STATE_DIR, exist_ok=True)
        path, data = os.path.join(STATE_DIR, "scb_debug.json"), {}
        try:
            with open(path, encoding="utf-8") as fh:
                data = json.load(fh)
        except (OSError, ValueError):
            data = {}
        if kw.get("tries") is not None:
            data = {}
        data.update(kw)
        data["t"] = time.strftime("%Y-%m-%d %H:%M:%S")
        with open(path, "w", encoding="utf-8") as fh:
            json.dump(json_clean(data), fh, ensure_ascii=False, indent=1, default=str)
def scb_first_updates():
    """1.8.0: --scb, con la escena ya viva: lo primero es D L P Y buscando actualizaciones (DLpy, pip, yt-dlp) y, si hay un DLpy más nuevo, instalarlo y correr ya
    la versión nueva (que repite este arranque y sigue con normalidad). Sin escena, o con --noupdates, no hace nada (como antes de 1.8.0). Nunca rompe --scb:
    cualquier fallo se anota y el análisis sigue. True si corrió. antes que D L P Y va «Primera ejecución» (update_phase: check_version antes que check_update)."""
    if not updates_first():
        return False
    try:
        ensure_dirs()
        update_phase()
        return True
    except KeyboardInterrupt:
        return False
    except Exception as _ign:
        ignore("scb_first_updates", _ign)
        return False
def scb_scene_start(link):
    """Arranca la escena de --scb con el aviso en palabras sencillas."""
    try:
        if not link:
            return False
        from types import SimpleNamespace
        run = SimpleNamespace(link=str(link), info={}, spick=None)
        started, tries = False, 0
        for tries in (1, 2):
            wait_terminal_ready(timeout=3.0, force=True)
            if ux_start(run):
                started = True
                break
        try:
            rows = term_rows()
        except (OSError, ValueError):
            rows = None
        scb_diag(scene=started, tries=tries, tty=sys.stdout.isatty(), color=USE_COLOR, truecolor=TRUECOLOR,
                 anim=ANIM, debug=DEBUG, rows=rows, width=safe_width(), ui_lines=ui_lines())
        if not started:
            return False
        ux_lang_pick()
        scb_first_updates()
        ux_note(SCB_NOTES[0], hold=SCENE_DWELL + 0.5)
        ux_note(SCB_NOTES[1], hold=SCENE_DWELL + 0.3)
        return True
    except Exception as _ign:
        ignore("scb_scene_start", _ign)
        scb_diag(scene=False, error=f"{type(_ign).__name__}: {_ign}")
        return False
def shortcut_back(flags, pos):
    """`--scb LINK` (iOS):"""
    link = pos[0] if pos else None
    if not str(link or "").strip():
        link = shortcut_paste_link()
        dbg("atajo", "--scb sin enlace; portapapeles: " + (link or "sin enlace"))
        if link:
            pos = [link]
            sys.argv.append(link)
    val = flags.get("scb")
    name = val.strip() if isinstance(val, str) and val.strip() else SHORTCUT_NAME
    with quiet("shortcut_back", OSError):
        os.makedirs(STATE_DIR, exist_ok=True)
    scene = scb_scene_start(link)
    with quiet("shortcut_back", BaseException):
        if not is_installed("yt_dlp"):
            pip_install("yt-dlp")
            if scene:
                ux_note(f"yt-dlp {pkg_version('yt-dlp') or ''} · instalado".replace("  ", " ") if is_installed("yt_dlp", fresh=True)
                           else "No se pudo instalar yt-dlp", SCENE_DWELL)
    try:
        if scene:
            ux_note(SCB_NOTES[2])
        data = collect_with_timeout(link)
    except KeyboardInterrupt:
        data = shortcut_error("cancelled", "Cancelado.", link)
    if isinstance(data, dict) and data.get("error_code") in ("idmm_scb", "sc_list"):
        sys.argv[1:] = _drop_scb_arg(sys.argv[1:])
        try:
            RUNTIME["idmm_continue"] = True
        except Exception as _ign:
            diagnostic_report("A", f"shortcut_back: marcar idmm_continue: {type(_ign).__name__}: {_ign}")
            pass
        return IDMM_CONTINUE
    write_shortcut_json(data)
    CLEAN_LATE["on"] = True
    if ux_on() and ux_questions():
        ux_stop()
        scb_clear()
    with quiet("shortcut_back"):
        clean_old()
    if scene:
        scb_diag(scene=True, scene_alive=bool(ux_get("th") is not None and ux_get("th").is_alive()), scene_error=ux_get("err"),
                 json_ok=bool(data and data.get("ok", True)))
    if scene and ux_on() and isinstance(data, dict) and data.get("ok") is False:
        log_shortcutmode_error(f"{data.get('error_code') or 'error'}: {data.get('error') or data.get('message') or ''}")
        ux_set_error(data.get("error") or data.get("message") or "Error")
    if ux_end():
        scb_clear()
    shortcut_send(data, name)
    return 0
def shortcut_find_track(tracks, key):
    """Pista por idioma (o por format_id), sin distinguir mayúsculas; None si no existe."""
    if not key:
        return None
    k = str(key).strip().lower()
    return next((t for t in tracks
                 if t["lang"].lower() == k or str(t["fmt"].get("format_id")).lower() == k), None)
def shortcut_resolve_video(pick_, audios, videos, tracks, orig_ids, can_merge, auto=None):
    """(tipo, formato) de lo que eligió el atajo, o None si no hay elección / ya no existe."""
    v = str((pick_ or {}).get("v") or "")
    if not v:
        return None
    if v.lower() == "best":
        return auto_best(audios, videos, orig_ids, can_merge, quiet=True)
    if v.lower() == "ytdlp":
        return ("v", auto[0]) if auto else None
    if v.lower() in ("audio", "audio_best"):
        k = str((pick_ or {}).get("a") or "").strip().lower()
        exact = next((f for f in audios if str(f.get("format_id")).lower() == k), None) if k else None
        if exact is not None:
            return ("a", exact)
        if v.lower() == "audio_best":
            langs = [f for f in audios if k and str(f.get("language") or "und").lower() == k]
            f = best_audio(langs, ()) if langs else best_audio(audios, orig_ids)
            return ("a", f) if f is not None else None
        t = shortcut_find_track(tracks, pick_.get("a")) or (tracks[0] if tracks else None)
        return ("a", t["fmt"]) if t else None
    f = next((x for x in videos if str(x.get("format_id")) == v), None)
    return ("v", f) if f else None
SC_PICKS_MAX = 40
def shortcut_remember(key, data, path=None):
    """1.5.4: guarda de los formatos del JSON del atajo (videos y all_videos) lo que identifica su calidad, por video (los 40 más recientes)."""
    path = path or SHORTCUT_PICKS_FILE
    items, seen = [], set()
    for it in list(data.get("videos") or []) + list(data.get("all_videos") or []):
        i_ = str(it.get("id"))
        if i_ in seen or i_ in ("more", "ytdlp", "audio", "audio_best") or not it.get("height"):
            continue
        seen.add(i_)
        items.append({"id": i_, "height": it.get("height"), "fps": it.get("fps"), "hdr": bool(it.get("hdr")),
                      "compatible": bool(it.get("compatible"))})
    if not key or not items:
        return False
    db = load_json(path)
    db = db if isinstance(db, dict) else {}
    db[str(key)] = {"t": time.time(), "items": items}
    for old in sorted(db, key=lambda k_: (db[k_] or {}).get("t", 0))[:max(0, len(db) - SC_PICKS_MAX)]:
        db.pop(old, None)
    save_json(path, db, mkdir=True)
    return True
def shortcut_remembered(key, v, path=None):
    """1.5.4: lo guardado del formato `v` de ese video (id, resolución, fps, HDR, compatible) o None."""
    db = load_json(path or SHORTCUT_PICKS_FILE)
    ent = db.get(str(key)) if isinstance(db, dict) else None
    return next((it for it in ((ent or {}).get("items") or []) if str(it.get("id")) == str(v)), None)
def shortcut_similar_video(item, videos):
    """1.5.4: de `videos`, el más parecido a lo que se eligió (resolución, fps, HDR y compatibilidad, en ese orden); None si no hay datos o videos."""
    if not item or not item.get("height") or not videos:
        return None
    h, fps = int(item.get("height") or 0), int(item.get("fps") or 0)
    return min(videos, key=lambda f: (abs(int(f.get("height") or 0) - h), abs(shortcut_fps(f) - fps) if fps else 0,
                                      bool(detect_hdr(f)) != bool(item.get("hdr")), bool(apple_video(f)) != bool(item.get("compatible")),
                                      -(f.get("tbr") or 0)))
def shortcut_fallback_video(v, audios, videos, orig_ids, can_merge, item=None):
    """1.5.3: el format_id `v` del atajo ya no existe en esta consulta: (tipo, formato, cómo) del mismo formato con otra escritura (sin mayúsculas ni
    signos, o el mismo número con/sin letras; solo si es uno solo) o, 1.5.4, el más parecido al que se eligió (`item`, lo guardado del JSON) o, si
    no hay datos, el mejor compatible. None si no hay nada que ofrecer."""
    norm = lambda x: re.sub(r"[^a-z0-9]", "", str(x or "").lower())
    num = lambda x: re.sub(r"\D", "", str(x or ""))
    for key, label in ((norm, "mismo id"), (num, "mismo número")):
        k = key(v)
        if label == "mismo número" and len(k) < 4:
            continue
        hits = [f for f in videos if k and key(f.get("format_id")) == k]
        if len(hits) == 1:
            return ("v", hits[0], label)
    sim = shortcut_similar_video(item, videos)
    if sim is not None:
        same = int(sim.get("height") or 0) == int(item.get("height") or 0) and (not item.get("fps") or shortcut_fps(sim) == int(item["fps"]))
        return ("v", sim, "misma calidad" if same else "calidad más parecida")
    if not videos and not audios:
        return None
    kind, fmt = auto_best(audios, videos, orig_ids, can_merge, quiet=True)
    return (kind, fmt, "mejor compatible")
def shortcut_tracks(pick_, tracks, original):
    """(predeterminada, seleccionadas) según el atajo; sin «a» vale la original, sin «x» no hay adicionales."""
    primary = shortcut_find_track(tracks, pick_.get("a")) or original
    selected = [primary]
    for key in pick_.get("x") or []:
        t = shortcut_find_track(tracks, key)
        if t is not None and all(t is not s for s in selected):
            selected.append(t)
    return primary, selected
# ───────────────────────── [K1] Autoprueba ─────────────────────────
SELFTEST_MODULE, SELFTEST_REMOTE_DIR = "dlpy_selftest.py", "modules"
def selftest_dir():
    """Carpeta caché del módulo: DLPY_SELFTEST_CACHE_DIR (pruebas) o internal/modules."""
    return os.environ.get("DLPY_SELFTEST_CACHE_DIR") or os.path.join(INTERNAL_DIR, "modules")
def selftest_url(name):
    """URL fija en la carpeta modules/ de main (como languages/); no depende de VERSION."""
    repo = str(globals().get("UPDATE_REPO") or "ElDelDLpy/DLpy").strip().strip("/")
    if not re.fullmatch(r"[\w.-]+/[\w.-]+", repo):
        return None
    return "https://raw.githubusercontent.com/%s/%s/%s/%s" % (repo, urllib.parse.quote(LANG_BRANCH, safe=""), SELFTEST_REMOTE_DIR, name)
def selftest_module_text():
    """(texto, origen) del módulo de la autoprueba o (None, motivo). Orden: DLPY_SELFTEST_MODULE_FILE, junto a este archivo (modules/), caché verificada y, al final, descarga de main con SHA-256."""
    report_untrusted_repo_if_any()
    import hashlib
    local = [os.environ.get("DLPY_SELFTEST_MODULE_FILE") or "",
             os.path.join(os.path.dirname(os.path.abspath(__file__)), SELFTEST_REMOTE_DIR, SELFTEST_MODULE),
             os.path.join(selftest_dir(), SELFTEST_MODULE)]
    for path in local:
        if path and os.path.isfile(path):
            try:
                with open(path, "rb") as fh:
                    raw = fh.read()
            except OSError as _ign:
                ignore("selftest_module_text", _ign)
                continue
            if path == local[2]:
                try:
                    want = _lang_pack_sha_value(read_text(path + ".sha256"), SELFTEST_MODULE)
                except OSError as _ign:
                    ignore("selftest_module_text", _ign)
                    want = None
                if want != hashlib.sha256(raw).hexdigest():
                    continue
            return raw.decode("utf-8"), path
    url, sums = selftest_url(SELFTEST_MODULE), selftest_url(LANG_SUMS)
    if not url or not sums:
        return None, "repo"
    try:
        expected = _lang_pack_sha_value(fresh_bytes(sums, 8, limit=4096), SELFTEST_MODULE)
        raw = fresh_bytes(url, 8)
    except NET_ERRORS as _ign:
        ignore("selftest_module_text", _ign)
        return None, "red"
    if raw is None:
        return None, "red"
    if not expected or hashlib.sha256(raw).hexdigest() != expected:
        return None, "sha"
    path = os.path.join(selftest_dir(), SELFTEST_MODULE)
    try:
        write_text(path, raw.decode("utf-8"), mkdir=True)
        write_text(path + ".sha256", "%s  %s\n" % (expected, SELFTEST_MODULE))
    except (OSError, ValueError) as _ign:
        ignore("selftest_module_text", _ign)
    return raw.decode("utf-8"), url
def selftest():
    """`python dlpy.py --selftest`: carga modules/dlpy_selftest.py (verificado) y corre las pruebas. 2.0.8: sin autoprueba integrada; con el modulo de GitHub basta."""
    _ok_threads, _fallos_threads = check_is_threads_link()
    if not _ok_threads:
        print(t_display(f"Autoprueba: is_threads_link falló en {len(_fallos_threads)} caso(s): {_fallos_threads}. Sin esto no hay autoprueba verde."))
        return 1
    text, origin = selftest_module_text()
    if text is None:
        print(t_display("Autoprueba: no se pudo obtener %s/%s (%s). Sin módulo no hay autoprueba (la integrada se quitó; con la de GitHub basta)." % (SELFTEST_REMOTE_DIR, SELFTEST_MODULE, origin)))
        return 1
    found = re.search(r'(?m)^SELFTEST_FOR = "([^"]*)"', text)
    if not found or found.group(1) != VERSION:
        print(t_display("Autoprueba: el módulo es de la versión %s y dlpy.py es la %s; actualiza el módulo de GitHub (no hay autoprueba integrada)." % (found.group(1) if found else "?", VERSION)))
        return 1
    exec(compile(text, origin, "exec"), globals())
    return globals()["selftest_run"]()
