def config_validate(name, value):
    """1.8.4: (ok, normalized|None). ok=False → valor inválido (en runtime se usa el predeterminado)."""
    v = str(value if value is not None else "").strip()
    n = str(name or "")
    if v == "":
        return True, ""
    low = v.lower()
    def flag01():
        if low in ("0", "1"):
            return True, low
        if low in ("on", "yes", "true", "si", "sí"):
            return True, "1"
        if low in ("off", "no", "false"):
            return True, "0"
        return False, None
    def num(min_v=None, max_v=None, allow_float=True):
        try:
            x = float(v.replace(",", ".")) if allow_float else float(int(v))
        except Exception:
            return False, None
        if not math.isfinite(x):
            return False, None
        if min_v is not None and x < min_v:
            return False, None
        if max_v is not None and x > max_v:
            return False, None
        if allow_float and ("." in v or "," in v):
            s = ("%g" % x)
        else:
            s = str(int(x)) if x == int(x) else ("%g" % x)
        return True, s
    if n in ("DLPY_DEBUG", "DLPY_TRUECOLOR", "DLPY_ANIMATIONS", "DLPY_SITE_INTRO",
             "DLPY_PIP_IN_SCENE", "DLPY_GLITCH_EFFECT", "DLPY_CALM_SCENE", "DLPY_CONVERT_LIGHT", "DLPY_HIDE_SCRIPT_FILES",
             "DLPY_CLEAR_HISTORY", "DLPY_SCENE_OUTRO", "DLPY_INSTANCE_WATCHDOG", "DLPY_METADATA_TAGS",
             "DLPY_EMBED_CHAPTERS", "DLPY_REMOVE_SPONSORS", "DLPY_EMBED_THUMBNAIL", "DLPY_EMBED_SUBTITLES", "DLPY_VERIFY_FILE", "DLPY_BATCH_DOWNLOADS", "DLPY_CAROUSEL_DIRECT_DOWNLOAD", "DLPY_CAROUSEL_SUBFOLDER"):
        return flag01()
    if n == "DLPY_PARALLEL_FRAGMENTS":
        return num(1, 16, allow_float=False)
    if n == "DLPY_SUBTITLES":
        return (True, "0") if low in ("0", "no", "off", "") else ((True, "all") if low == "all" else (bool(subs_langs(low)), ",".join(subs_langs(low))))
    if n == "DLPY_SCENE_PACE":
        if low in ("wait", "real", "loop"):
            return True, "wait" if low == "loop" else low
        ok, s = num(0, 60)
        return ok, s
    if n == "DLPY_ANIMATION_LOOP_SECONDS":
        return num(0.2, 3)
    if n == "DLPY_CDN_EXPIRY_MARGIN":
        return num(0, 86400)
    if n == "DLPY_DEBUG_LOG_KEEP":
        return num(1, 1000, allow_float=False)
    if n == "DLPY_FPS":
        return num(24, 240, allow_float=False)
    if n == "DLPY_UI_LINES":
        return num(0, 200, allow_float=False)
    if n == "DLPY_UI_WIDTH":
        if low == "auto":
            return True, "auto"
        return num(20, 500, allow_float=False)
    if n == "DLPY_LIST_ROWS":
        if low == "auto":
            return True, "auto"
        return num(1, 200, allow_float=False)
    if n == "DLPY_CONVERSION_QUALITY":
        if low in ("fast", "high", "best", "prores"):
            return True, low
        return False, None
    if n == "DLPY_DIRECT_LIST":
        mode_ = sc_list_mode(v)
        if low in ("0", "off", "no", "false", "none"):
            return True, "0"
        return (True, {"short": "1", "all": "all"}[mode_]) if mode_ else (False, None)
    if n == "DLPY_DELIVERY_MODE":
        if low in ("view", "shortcut"):
            return True, low
        return False, None
    if n == "DLPY_INTERFACE":
        if low in ("auto", "automatic", "automático", "automatico"):
            return True, "auto"
        if low in ("minimal", "minima", "mínima", "min", "simple", "uim", "texto", "plano"):
            return True, "minimal"
        if low in ("scene", "escena", "ux", "scena", "escenas"):
            return True, "scene"
        return False, None
    if n in ("DLPY_CLEAR_MODE", "DLPY_CLEAR_AT_START"):
        if low in ("auto", "home", "down", "purge-first", "reset"):
            return True, low
        return False, None
    if n == "DLPY_TOP_BAR":
        if low in ("0", "off", "no", "false", "none", "oculto", "hide", "hidden"):
            return True, "0"
        if low in ("1", "on", "yes", "true", "all", "si", "sí"):
            return True, "1"
        letters = [c for c in v.upper() if c in "DTV"]
        if letters and all(c in "DTV, ·|_-;" for c in v.upper()):
            seen = []
            for c in v.upper():
                if c in "DTV" and c not in seen:
                    seen.append(c)
            return True, "".join(seen)
        return False, None
    if n == "DLPY_BOTTOM_BAR":
        if low in ("0", "off", "no", "false", "none", "oculto", "hide", "hidden"):
            return True, "0"
        if low in ("1", "on", "yes", "true", "all", "si", "sí"):
            return True, "1"
        if any(c in "EAN" for c in v.upper()) and all(c in "EAN, ·|_-;" for c in v.upper()):
            seen = []
            for c in v.upper():
                if c in "EAN" and c not in seen:
                    seen.append(c)
            return True, "".join(seen)
        return False, None
    if n == "DLPY_TRANSLATION_DEBUG":
        mode = lang_id_mode_parse(v)
        if mode == "off":
            return (True, "0") if low in ("0", "off", "no", "false", "none", "disabled", "") else (False, None)
        return True, mode
    if n == "DLPY_LANGUAGE":
        if low in ("ask", "auto", "es", "en", "pt", "fr", "de", "it", "ru", "zh", "hi", "ar", "ja", "ko", "pl"):
            return True, low
        if 1 <= len(v) <= 16:
            return True, v
        return False, None
    if n == "DLPY_UPDATE_INTERVAL":
        hrs = updates_parse_hours(v)
        if hrs is None:
            return False, None
        if hrs < 0:
            return True, "on"
        if hrs == 0:
            return True, "0"
        return True, re.sub(r"\s+", "", low.replace(",", "."))
    if n == "DLPY_FORMAT_PRESET":
        if low in ("", "musica", "music", "ligero", "light", "maximo", "max", "maximum"):
            _m = {"music": "musica", "light": "ligero", "max": "maximo", "maximum": "maximo"}.get(low, low)
            return True, _m
        return False, None
    if n == "DLPY_YOUTUBE_CLIENT":
        if low in ("", "auto"):
            return True, "auto"
        _allowed = {"android", "web", "ios", "tv", "music", "web_music", "web_safari", "android_music", "android_vr", "mweb", "web_embedded", "android_embedded"}
        _parts = [x.strip() for x in v.split(",") if x.strip()]
        if _parts and all(x.lower() in _allowed for x in _parts):
            return True, ",".join(x.lower() for x in _parts)
        return False, None
    if n in ("DLPY_SHORTCUT_TIMEOUT", "DLPY_SHORTCUT_JSON_TIMEOUT", "DLPY_SHORTCUT_HARD_TIMEOUT"):
        return num(0, 10_000_000)
    if n in ("DLPY_GITHUB_REPO", "DLPY_YTDLP_EXTRA_ARGS", "DLPY_COOKIES_FILE", "DLPY_YOUTUBE_PO_TOKEN"):
        return True, v
    return True, v
def config_mark(name, default, val):
    """1.8.4: símbolo de estado · ● guardada válida · ✗ guardada inválida · espacio = predeterminado."""
    if val is None:
        return " "
    ok, _ = config_validate(name, val)
    return "✗" if not ok else "●"
def config_rows(data):
    """1.3.2:"""
    rows = [(n, d, t, data.get(n)) for n, d, t in CONFIG_OPTIONS]
    known = {n for n, _d, _t in CONFIG_OPTIONS}
    rows += [(k, "", "variable guardada que no está en la lista de opciones conocidas", data[k]) for k in sorted(data) if k not in known]
    return rows
def config_choice(raw, rows):
    """1.3.2:"""
    s = str(raw or "").strip()
    low = s.lower()
    if low in ("", "q", "salir", "exit"):
        return ("quit",)
    if low in ("l", "lista", "list"):
        return ("list",)
    if low in ("o", "olvidar"):
        return ("forget",)
    if "=" in s:
        return ("set", s)
    if s.isdigit():
        n = int(s)
        return ("pick", rows[n - 1][0]) if 1 <= n <= len(rows) else ("bad", f"1-{len(rows)}")
    key = config_key(s)
    if key and key in {r[0] for r in rows}:
        return ("pick", key)
    return ("bad", "nº, nombre, NOMBRE=valor, l, o o q")
def config_list_rows(rows):
    """2.0.0: filas de la lista de --config en el formato de print_rows: «nº NOMBRE valor» y a la derecha ● guardada · ✗ guardada pero inválida ([predeterminado] si no hay guardada)."""
    out = []
    for i, (name, default, _text, val) in enumerate(rows, 1):
        mark, dflt = config_mark(name, default, val), f"[{default or '—'}]"
        out.append({"n": i, "flags": {"saved"} if mark == "●" else {"bad"} if mark == "✗" else set(),
                    "cols": [name, dflt if val is None else f"{val} → {dflt}" if mark == "✗" else val]})
    return out
def config_show_list(rows):
    """1.3.2 / 1.8.4 / 2.0.0: la lista de --config con el dibujo único de las listas (print_rows)."""
    print_rows(config_list_rows(rows), [("saved", "bad")], clip=1)
def config_redraw(msg=None):
    """1.8.4: limpia la terminal y pinta de nuevo archivo + lista + ayuda (menú config legible al cambiar varias)."""
    try:
        clear_screen()
    except Exception:
        print("\n" * 3)
    print(title_bar(f"DLpy v{VERSION}", paint("config", "gray")))
    print(rule())
    kv("Archivo", ENV_FILE)
    if msg:
        print()
        note(msg)
    print()
    legend_note("● guardada  ·  ✗ guardada inválida (se usa el predeterminado)  ·  [ ] predeterminado")
    config_show_list(config_rows(_read_env_json(ENV_FILE)))
    print()
    note("Nº o nombre: elegir · NOMBRE=valor: guardar · l: lista · o: olvidar todas · Enter: salir")
def config_interactive():
    """1.3.2 / 1.8.4: menú con redibujado al cambiar; la lista muestra ●/✗ al momento."""
    rc = 0
    config_redraw()
    prompt = paint("▸", "orange", True) + " "
    cur = prompt
    while True:
        rows = config_rows(_read_env_json(ENV_FILE))
        try:
            raw = ask_line(cur, True, "▸ ")
        except (EOFError, KeyboardInterrupt):
            break
        act = config_choice(raw, rows)
        if act[0] == "quit":
            break
        if act[0] == "bad":
            cur = retry_prompt(cur, raw, bad_prompt(act[1]), "Escribe " + act[1] + ".")
            continue
        cur = prompt
        try:
            if act[0] == "list":
                config_redraw()
                continue
            if act[0] == "forget":
                if ask("¿Borrar todas las variables guardadas?", default=False):
                    had = len(_read_env_json(ENV_FILE))
                    config_write({}, ENV_FILE)
                    hide_files_after_config()
                    config_redraw(f"Configuración borrada ({had} guardada(s))")
                else:
                    config_redraw()
                continue
            item = act[1]
            if act[0] == "pick":
                _n, default, text, val = next(r for r in rows if r[0] == act[1])
                try:
                    clear_screen()
                except Exception as _ign:
                    ignore('config: limpiar pantalla', _ign)
                print(title_bar(f"DLpy v{VERSION}", paint("config", "gray")))
                print(rule())
                print(paint("·", "orange") + paint(act[1], "white", True))
                note(text)
                mark = config_mark(act[1], default, val)
                if val is None:
                    kv("Guardado", "(ninguno)")
                elif mark == "✗":
                    kv("Guardado", paint(str(val), "red") + paint(t_display(" (inválido → predeterminado)"), "gray"))
                else:
                    kv("Guardado", val)
                kv("Por omisión", default or "—")
                note("Escribe el valor nuevo · Enter = dejarlo · - = borrar")
                try:
                    new = ask_line(prompt, True, "▸ ").strip()
                except (EOFError, KeyboardInterrupt):
                    break
                if not new:
                    config_redraw("Sin cambios.")
                    continue
                item = act[1] + "=" + ("" if new == "-" else new)
            changes, errors = config_edit([item], ENV_FILE)
            msg_parts = []
            for key, _old, new_v in changes:
                if new_v is None:
                    msg_parts.append(f"{key} borrada")
                else:
                    ok, _ = config_validate(key, new_v)
                    msg_parts.append(f"{key} = {new_v}" + ("" if ok else " (inválido → se usará el predeterminado)"))
            if not changes and not errors:
                msg_parts.append("Sin cambios.")
            for msg in errors:
                m_err(msg)
                rc = 1
            if changes and any(k == HIDE_FILES_KEY for k, _o, _n in changes):
                hide_files_after_config()
            config_redraw(" · ".join(msg_parts) if msg_parts else None)
        except OSError as e:
            m_err(f"No se pudo guardar en {ENV_FILE}: {e}")
            rc = 1
            config_redraw()
    print()
    note("Listo. Con --config NOMBRE=valor también se guarda sin menú; --config --lista muestra solo lo guardado.")
    return rc
def clear_test():
    """`python dlpy.py --cleartest` (1.3.2):"""
    if not (tty_both()):
        print(t_display("--cleartest necesita un terminal interactivo."))
        return 1
    print(title_bar(f"DLpy v{VERSION}", paint(t_display("prueba de borrado"), "gray")))
    print(rule())
    note("Se llena la pantalla, se borra con cada modo y eliges el que quede limpio sin deslizar.")
    prev, rc, saved = CLEAR_MODE, 0, None
    try:
        for name, text in CLEAR_MODES:
            if ask_line(paint(f"[{name}] ", "orange", True) + paint(t_display("Enter = probar ▸"), "gray"), True, f"[{name}] Enter ▸ ").strip().lower() == "q":
                break
            rows = term_rows()
            for i in range(rows + 8):
                print(t_display(f"Línea de prueba {i + 1}"))
            time.sleep(0.8)
            globals()["CLEAR_MODE"] = name
            native_clear()
            print(paint(t_display(f"Modo {name}"), "white", True))
            note(text)
            yes_key, no_key = _yn_keys()
            question = (t_display("¿Quedó limpia sin deslizar?") + f" {yes_key} = {t_display('guardar')} · "
                        + f"{no_key} = {t_display('siguiente')} · q = {t_display('salir')} ▸ ")
            ans = ask_line(paint(question, "gray"), True, "/".join((yes_key, no_key, "q")) + " ▸ ").strip().lower()
            yn = parse_yn(ans, default=None)
            if yn is True:
                saved = name
                break
            if ans == "q":
                break
    except (EOFError, KeyboardInterrupt):
        pass
    finally:
        globals()["CLEAR_MODE"] = prev
    if saved:
        try:
            config_edit([f"DLPY_CLEAR_MODE={saved}"], ENV_FILE)
            m_ok(f"DLPY_CLEAR_MODE = {saved} (guardado; vale desde el siguiente comando)")
        except OSError as e:
            m_err(f"No se pudo guardar en {ENV_FILE}: {e}")
            rc = 1
    else:
        note("No se guardó ningún modo.")
    return rc
def print_config(args=None):
    """`python dlpy.py --config` (1.3.0):"""
    args = list(sys.argv[1:] if args is None else args)
    flags, pos = parse_cli(args)
    items = list(pos)
    if isinstance(flags.get("config"), str) and flags["config"]:
        items.insert(0, flags["config"])
    print(title_bar(f"DLpy v{VERSION}", paint("config", "gray")))
    print(rule())
    rc = 0
    if (not items and not flags.get("olvidar") and not flags.get("opciones") and not flags.get("lista")
            and tty_both()):
        return config_interactive()
    try:
        if flags.get("olvidar"):
            had = len(_read_env_json(ENV_FILE))
            config_write({}, ENV_FILE)
            m_ok(f"Configuración borrada ({had} guardada(s))")
        changes, errors = config_edit(items, ENV_FILE)
    except OSError as e:
        m_err(f"No se pudo guardar en {ENV_FILE}: {e}")
        return 1
    for key, _old, new in changes:
        m_ok(f"{key} = {new}" if new is not None else f"{key} borrada")
    for msg in errors:
        m_err(msg)
        rc = 1
    if flags.get("olvidar") or any(k == HIDE_FILES_KEY for k, _o, _n in changes):
        hide_files_after_config()
    data = _read_env_json(ENV_FILE)
    kv("Archivo", ENV_FILE)
    print()
    print(paint("Guardadas", "white", True))
    if data:
        for k in sorted(data):
            print("  " + paint(k, "gray") + " = " + data[k])
    else:
        note("(ninguna)")
    if flags.get("opciones"):
        print()
        print(paint("Opciones conocidas", "white", True))
        for name, default, text in CONFIG_OPTIONS:
            print("  " + (paint("● ", "mint") if name in data else "  ") + name + paint(f"  [{default or '—'}]", "gray"))
            for ln in wrap_text(t_display(text), max(10, term_width() - 6)):
                print("    " + paint(ln, "gray"))
    print()
    note("Guardar: --config NOMBRE=valor · borrar una: --config NOMBRE= · borrar todas: --config --olvidar · opciones: --config --opciones")
    note("El nombre puede ir sin DLPY_ (list_rows = DLPY_LIST_ROWS). Un export manda en esa ejecución y también se guarda. DLPY_FORGET_SAVED y DLPY_SKIP_SHA_VERIFICATION son de una sola ejecución.")
    return rc
# ───────────────────────── [L1] Principal ─────────────────────────
class _Run:
    """Estado compartido entre los pasos de main(): cada paso lee y escribe aquí lo suyo (0.7.3)."""
def _end(rc):
    """Código de salida de un modo especial (los que devolvían None terminan con 0)."""
    return 0 if rc is None else rc
def _m_modes(run):
    """[M0a] Modos especiales (--selftest, --sistema, --perfil, --ios-check, --config, --2shortcuts, --scb, --scm:"""
    sys.argv[1:] = norm_args(sys.argv[1:])
    if "--ios-check" in sys.argv[1:]:
        return _end(print_ios_check())
    if "--selftest" in sys.argv[1:]:
        return _end(selftest())
    if "--sistema" in sys.argv[1:]:
        return _end(print_capabilities())
    if "--perfil" in sys.argv[1:]:
        return _end(print_profile())
    if _wants(sys.argv[1:], "config"):
        return _end(print_config(sys.argv[1:]))
    if wants_languages(sys.argv[1:]):
        return _end(print_languages())
    if wants_shortcut_texts(sys.argv[1:]):
        return _end(print_shortcut_texts(sys.argv[1:]))
    if _wants(sys.argv[1:], "cleartest"):
        return _end(clear_test())
    if wants_2shortcuts(sys.argv[1:]):
        return _end(send_code_to_shortcut())
    cli_flags, cli_args = parse_cli(sys.argv[1:])
    apply_output_flags(cli_flags)
    if SC_LIST_RUN["on"]:
        dbg("DLPY_DIRECT_LIST", {"modo": sc_list_mode(), "argumentos": sys.argv[1:]})
    NO_UPDATES["on"] = bool(cli_flags.get("noupdates") or cli_flags.get("no-updates") or UPDATE_HOURS == 0)
    LATE_UPDATES["on"] = cli_flags.get("shortcutpick") is not None and not NO_UPDATES["on"]
    if wants_scb(sys.argv[1:]):
        _scb_rc = shortcut_back(cli_flags, cli_args)
        if _scb_rc == IDMM_CONTINUE:
            cli_flags, cli_args = parse_cli(sys.argv[1:])
        else:
            return _end(_scb_rc)
    if wants_scm(sys.argv[1:]):
        return _end(shortcut_mode(cli_flags, cli_args))
    run.cli_args = cli_args
    if cli_flags.get("view") is not None:
        VIEW_RUN["mode"] = "view" if cli_flags["view"] is True else str(cli_flags["view"]).strip().lower() or "view"
    _sp = cli_flags.get("shortcutpick")
    if isinstance(_sp, str) and "://" in _sp and "=" not in _sp.split("://", 1)[0]:
        cli_args = [_sp] + list(cli_args)
        cli_flags["shortcutpick"] = ""
        run.cli_args = cli_args
    run.spick = parse_shortcut_pick(cli_flags.get("shortcutpick"))
    if run.spick is None and cli_flags.get("shortcutpick") is not None:
        run.spick = {}
    if run.spick is not None and not any(str(a or "").strip() for a in (cli_args or [])):
        _pl = shortcut_paste_link()
        dbg("atajo", "el atajo no pasó enlace; portapapeles: " + (_pl or "sin enlace"))
        if _pl:
            cli_args = [_pl]
            run.cli_args = cli_args
    if run.spick is not None:
        quiet_set(True)
    input_lock()
    return None
def _m_prepare(run):
    """[M0b] Preparación: carpetas."""
    ux_early_site_intro(run)
    ux_lang_pick()
    os.makedirs(FILES_DIR, exist_ok=True)
    drop_internal_leftovers()
    os.makedirs(INTERNAL_DIR, exist_ok=True)
    ensure_dirs()
    lang_ensure()
    clear_screen()
    if ENV_STATE["error"]:
        m_warn(f"No se pudieron guardar las variables DLPY_* en {ENV_STATE['path']}")
        note(ENV_STATE["error"])
    with quiet("clean_trash 0.9.9"):
        _gone = clean_trash()
        ux_set(trash_gone=_gone)
        if _gone and not ux_on():
            m_ok(f"Papelera: {_gone} archivo(s) borrado(s) definitivamente (más de {TRASH_EXPIRE_DAYS:g} días en ella).")
        if _gone and ux_on():
            ux_set(clean=_gone)
            ux_status(clean_label("Vaciando", None, _gone))
            ux_hold(SCENE_CLEAN_SECS)
    if QUIET["on"]:
        CLEAN_LATE["on"] = True
    else:
        with quiet("clean_old"):
            clean_old()
    return None
def _debug_environment():
    """Con DLPY_DEBUG: ancho del terminal y datos del entorno."""
    try:
        env_cols = _ORIG_GTS((0, 0)).columns
    except Exception as _ign:
        ignore("main", _ign)
        env_cols = 0
    m_info(f"{t_display('Ancho del terminal')}: {t_display('variable')}={env_cols or '?'} · ioctl={_ioctl_cols() or '?'} · {t_display('medido')}={_PROBE['cols'] or '?'}"
           f" · {t_display('texto')}={term_width()} · {t_display('barras')}={safe_width()}")
    dbg("entorno", {"python": sys.version.split()[0], "plataforma": sys.platform, "modo": PLATFORM,
                    "maquina": getattr(os.uname(), "machine", "?") if hasattr(os, "uname") else "?",
                    "script": SCRIPT_PATH, "ffmpeg": tool_executable("ffmpeg"),
                    "files": FILES_DIR,
                    "internal": INTERNAL_DIR, "env": dict(ENV_STATE)})
def updates_first():
    """1.8.0: ¿las actualizaciones van PRIMERO en esta ejecución? Con la escena viva, sí: --shortcutpick y --scb abren D L P Y y buscan DLpy, pip y yt-dlp antes de seguir
    (si hay un DLpy más nuevo, lo instala y corre ya la versión nueva). Sin escena (la terminal no la admite) no hay dónde animar ni preguntar:
    --shortcutpick las deja para el final (LATE_UPDATES) y --scb no las busca. Tampoco con --noupdates / DLPY_UPDATE_INTERVAL=0."""
    return ux_on() and not NO_UPDATES["on"]
def update_phase():
    """1.8.0: lo de _m_update tras --actualizar (lo comparten _m_update y --scb): busca DLpy, pip y yt-dlp, instala y corre un DLpy más nuevo
    (reexec_script no vuelve), revisa la versión instalada y las dependencias. Sin escena, las búsquedas salen a la vez (prefetch_phase). Con la escena viva
    van UNA A UNA, cada una con su comando real en D L P Y (GET api.github.com/…/releases, GET pypi.org/pypi/pip/json…), como en 1.7.9: la búsqueda en paralelo
    solo tenía un comando de resumen («GET pypi.org x2 · github.com») que no es lo que el script ejecuta. None si todo siguió bien; 1 si hay que parar.
    la versión local va ANTES que la remota: check_version (primera ejecución) sale antes que check_update / check_dependencies, que son los que
    encienden D L P Y. Así «Primera ejecución» no queda detrás de D L P Y."""
    reexec = getattr(sys, "_dlpy_reexec", False)
    script_due = (not NO_UPDATES["on"] and not LATE_UPDATES["on"] and not reexec
                  and check_due("script", script_sig()))
    deps_due = not NO_UPDATES["on"] and not LATE_UPDATES["on"] and check_due("deps")
    if not ux_on():
        prefetch_phase(script_due, deps_due)
    if reexec:
        UPDATE_CHECKED["ok"] = True
    if not check_version():
        return 1
    if script_due:
        if check_update():
            return 0
    if (script_due or reexec) and UPDATE_CHECKED["ok"]:
        check_mark("script", script_sig())
    if not LATE_UPDATES["on"] and LANG in PACK_LANGS:
        lang_pack_sync(LANG)
    if not check_dependencies(updates=not (NO_UPDATES["on"] or LATE_UPDATES["on"])):
        return 1
    prefetch_summary()
    cleanup_internal()
    if DEBUG:
        _debug_environment()
    return None
def _m_update(run):
    """[M0c] Actualización del script, versión instalada y dependencias."""
    reexec = getattr(sys, "_dlpy_reexec", False)
    if "--actualizar" in sys.argv[1:]:
        if not reexec:
            check_update(force=True)
        if UPDATE_CHECKED["ok"] or reexec:
            check_mark("script", script_sig())
        if LANG in PACK_LANGS:
            lang_pack_sync(LANG, force=True)
        return 0 if check_dependencies(force=True) else 1
    if LATE_UPDATES["on"] and updates_first():
        LATE_UPDATES["on"] = False
    rc = update_phase()
    ux_brand_end()
    return rc
def resume_one(item):
    """Reanuda una descarga pendiente con su enlace y su elección guardados (los mismos pasos que una normal)."""
    ux_reset_site_state()
    run = _Run()
    run.cli_args, run.spick = [item["link"]], dict(item["pick"])
    clear_screen()
    for step in RESUME_STEPS:
        rc = step(run)
        if rc is not None:
            return rc
    return 0
def _m_resume(run):
    """[M0d] Menú de descargas pendientes:"""
    if idmm_direct() and (getattr(run, "cli_args", None) or []):
        return None
    if getattr(run, "spick", None) is not None or not (tty_both()):
        return None
    cli = getattr(run, "cli_args", None) or []
    try:
        items = resume_candidates(cli[0] if cli else None)
    except Exception as _ign:
        ignore("resume_candidates", _ign)
        return None
    picked = resume_menu(items) if items else []
    if not picked:
        return None
    results = []
    for k, it in enumerate(picked):
        rc = resume_one(it)
        results.append((it["title"], rc == 0))
        if rc != 0 and k < len(picked) - 1 and not ask_clean("¿Seguir con las demás descargas pendientes?", True):
            break
    print()
    for title, ok in results:
        (m_ok if ok else m_warn)(("Reanudada: " if ok else "No se completó: ") + title)
    if cli:
        return None
    return 0 if all(ok for _t, ok in results) else 1
def _m_link(run):
    """[M1] Enlace (1): yt_dlp se carga en segundo plano mientras se pide."""
    preload_ytdlp()
    drain_pending_input(0.12)
    run.link = get_link(run.cli_args)
    _batch_src = " ".join([str(a) for a in (run.cli_args or [])]) if (run.cli_args and len(run.cli_args) > 1) else (run.link or "")
    _batch = split_batch_links(_batch_src)
    if len(_batch) > 1 and batch_enabled():
        run.batch_queue = list(_batch[1:])
        run.batch_total = len(_batch)
        run.batch_index = 1
        run.link = _batch[0]
        m_info(t_display("Cola") + f": {len(_batch)} enlaces")
    else:
        run.batch_queue = []
        run.batch_total = 1
        run.batch_index = 1
        if _batch:
            run.link = _batch[0]
    if not run.link:
        m_err("Sin enlace.")
        return 1
    import yt_dlp
    net_wrap_ytdlp(yt_dlp)
    run.yt_dlp = yt_dlp
    warn_youtube_js(run.link)
    return None
def _m_analyze(run):
    """[M1] Análisis (1 · 1b): extrae la información y deja listos formatos, audios, videos y pistas."""
    link = run.link
    scene_brand_end()
    idmm_ensure_scene(run)
    _queued = bool(idmm_carousel_index(link))
    if not _queued:
        ux_status("Analizando enlace", frac=0.02)
    bar = Bar()
    if DEBUG:
        if not _queued:
            m_info("Analizando enlace...")
    elif not _queued:
        bar.start("Analizando enlace", indeterminate=False)
    try:
        _cached_parent = None
        if _queued:
            try:
                _cached_parent = _CAROUSEL_INFO_CACHE.get(_carousel_cache_key(link))
            except Exception:
                _cached_parent = None
        if _cached_parent and (_cached_parent.get('entries') or _cached_parent.get('formats')):
            _stamp_cdn_expiry(_cached_parent)
            info = _cached_parent
            run.base_opts = (cli_like_opts(run.yt_dlp, ['--no-playlist'] + list(user_argv())) or {})
            ANALYSIS['stage'] = 'Carrusel (caché)'
            ANALYSIS['t'] = time.monotonic()
        else:
            info, run.base_opts = analyze_link_timed(run.yt_dlp, link)
        try:
            if info and (info.get('entries') or info.get('formats')):
                _CAROUSEL_INFO_CACHE[_carousel_cache_key(link)] = info
        except Exception as _ign:
            diagnostic_report("A", f"_m_analyze: guardar info padre en caché: {type(_ign).__name__}: {_ign}")
            pass
    except KeyboardInterrupt:
        bar.stop()
        print()
        m_err("Cancelado.")
        return 1
    except Exception as e:
        bar.stop()
        if is_bot_error(e):
            explain_bot_error()
        elif is_threads_link(link) and ("unsupported" in str(e).lower() or is_threads_login_error(e)):
            m_err(f"Error al analizar: {e}")
            explain_threads_unsupported(link)
        else:
            m_err(f"Error al analizar: {e}")
        return 1
    bar.done(min_secs=0.5)
    _car_idx = idmm_carousel_index(link)
    run.carousel_queued = bool(_car_idx)
    _parent_info = info
    _carousel_items = carousel_items_from_info(info)
    run.carousel_items = _carousel_items
    run.carousel_index = _car_idx
    run.is_foto = False
    run.carousel_choice = None
    run.carousel_parent = None
    if _carousel_items:
        if _car_idx:
            _hit = next((it for it in _carousel_items if it.get("index") == _car_idx), None)
            _picked = [_hit] if _hit is not None else [_carousel_items[0]]
        elif idmm_direct():
            _picked = list(_carousel_items)
        elif (QUIET.get("on") or getattr(run, "spick", None) is not None) and not \
                (is_threads_link(link) and SC_LIST_RUN.get("on")):
            _picked = [_carousel_items[0]]
        else:
            _back = ux_list_enter("Carrusel") if ux_on() else None
            _was_quiet = QUIET.get("on") and _back is None
            if _was_quiet:
                quiet_set(False)
            try:
                _picked = carousel_pick(_carousel_items)
            finally:
                if _was_quiet:
                    quiet_set(True)
                if _back is not None:
                    ux_list_leave(run, _back)
            if not _picked:
                return 1
        if len(_picked) > 1:
            _base_link = str(link).split("#dlpy_carousel=")[0]
            _rest = [f"{_base_link}#dlpy_carousel={it['index']}" for it in _picked[1:]]
            run.batch_queue = _rest + list(getattr(run, "batch_queue", None) or [])
            run.batch_total = (getattr(run, "batch_total", 1) or 1) + len(_rest)
            ux_say(f"Carrusel: este es el medio {_picked[0]['index']} de {len(_carousel_items)}; los otros {len(_rest)} quedan en cola.")
        _item = _picked[0]
        run.carousel_choice = _item
        run.is_foto = (_item["kind"] == "foto")
        info = carousel_single_info(_item, _parent_info)
        run.carousel_parent = _parent_info
    else:
        if info.get("entries"):
            info = next((e for e in info["entries"] if e), info)
        if not _entry_has_video(info) and not _carousel_best_video_fmt(info) and _carousel_foto_fmt(info):
            run.is_foto = True
    run.info = info
    with quiet("main"):
        save_json(LAST_FILE, {"link": link, "date": int(time.time()), "title": info.get("title") or ""})
    run.title = info.get("title") or "video"
    if getattr(run, "carousel_choice", None) is not None:
        run.title = f"{run.title} · {run.carousel_choice['index']} de {len(_carousel_items)} · {run.carousel_choice['label']}"
    ux_title(run.title)
    ux_shape(info)
    run.key = video_key(info) + (f":carousel:{run.carousel_choice['index']}" if getattr(run, "carousel_choice", None) else "")
    run.index = load_json(INDEX_FILE)
    run.old_file, run.old_entry = lookup_downloaded(run.index, run.key)
    dbg("info", {"clave": run.key, "titulo": run.title, "id": info.get("id"),
                 "extractor": info.get("extractor_key"), "duracion": info.get("duration"),
                 "formatos": len(info.get("formats") or [])})
    dbg("ya descargado", {"archivo": run.old_file, "entrada": run.old_entry} if run.old_file else "no")
    if run.old_file:
        dbg("ya descargado", {"archivo": run.old_file, "se pregunta": "después de elegir"})
    if getattr(run, "is_foto", False):
        _foto_fmt = _carousel_foto_fmt(info)
        if not _foto_fmt:
            m_err("No se encontraron formatos.")
            return 1
        formats, audios, videos = [_foto_fmt], [], [_foto_fmt]
    else:
        formats, audios, videos = split_formats(info)
    run.formats, run.audios, run.videos = formats, audios, videos
    dbg("formatos sin códec (supuestos)", [f.get("format_id") for f in formats if f.get("_guess")])
    if not audios and not videos:
        m_err("No se encontraron formatos.")
        return 1
    run.orig_ids = mark_originals(audios)
    run.tracks, run.orig_lang = build_tracks(audios, run.orig_ids)
    tracks = run.tracks
    run.multi_lang = len({t["lang"] for t in tracks if t["lang"] != "und"}) > 1
    run.can_merge = ffmpeg_available()
    dbg("formatos", {"audio": len(audios), "video": len(videos), "ffmpeg": run.can_merge,
                     "ffmpeg_ruta": tool_executable("ffmpeg"), "idioma_original": run.orig_lang,
                     "originales": sorted(run.orig_ids)})
    dbg("pistas", [{"idioma": t["lang"], "format_id": t["fmt"].get("format_id"),
                    "original": t["original"], "apple": apple_audio(t["fmt"])}
                   for t in tracks])
    return None
def _ci_rows(run):
    """[M2] 2)"""
    from types import SimpleNamespace
    audios, videos, title = run.audios, run.videos, run.title
    orig_ids, can_merge, auto = run.orig_ids, run.can_merge, run.auto
    a_rows = [audio_row(i, f, orig_ids) for i, f in enumerate(audios, 1)]
    v_rows = [video_row(i, f) for i, f in enumerate(videos, len(audios) + 1)]
    choices = {r["n"]: ("a", audios[i]) for i, r in enumerate(a_rows)}
    choices.update({r["n"]: ("v", videos[i]) for i, r in enumerate(v_rows)})
    bk, bf = auto_best(audios, videos, orig_ids, can_merge, quiet=True)
    best_n = next((k for k, (_kd, ff) in choices.items() if ff is bf), None)
    auto_n = None
    if auto:
        auto_n = len(audios) + len(videos) + 1
        choices[auto_n] = ("v", auto[0])
    auto_line = ("yt-dlp auto → " + video_desc(auto[0]) + (f" + {audio_desc(auto[1])}" if auto[1] else "")
                 if auto else "")
    for r in a_rows + v_rows:
        if r["n"] == best_n:
            r["flags"].add("best")
    n_head = (3 if a_rows else 0) + (2 if v_rows else 0)
    cap = list_cap(banner_height() + len(title_lines(title, term_width() - 1))
                   + len(_legend_lines(["logo", "orig"])) + n_head + (1 if auto else 0) + 1
                   + len(wrap_text("n.º · b ★ mejor · m más · q salir", term_width() - 2)) + 1)
    a_keep = best_n - 1 if bk == "a" and best_n else None
    v_keep = best_n - len(audios) - 1 if bk == "v" and best_n else None
    a_uniq = best_per_quality(a_rows, audio_quality_keys(audios),
                              lambda i: ("apple" in a_rows[i]["flags"], "orig" in a_rows[i]["flags"], abr_of(audios[i])),
                              a_keep)
    v_uniq = best_per_quality(v_rows, video_quality_keys(videos),
                              lambda i: ("apple" in v_rows[i]["flags"],
                                         videos[i].get("tbr") or 0),
                              v_keep)
    a_pool = sum(1 for i in a_uniq if "apple" in a_rows[i]["flags"]) or len(a_uniq)
    v_pool = sum(1 for i in v_uniq if "apple" in v_rows[i]["flags"]) or len(v_uniq)
    a_take = min(a_pool, max(2, cap // 3))
    v_take = min(v_pool, cap - a_take)
    a_take = min(a_pool, cap - v_take)
    a_vis = short_pick(a_rows, a_take, a_keep, a_uniq)
    v_vis = short_pick(v_rows, v_take, v_keep, v_uniq)
    return SimpleNamespace(title=title, a_rows=a_rows, v_rows=v_rows, choices=choices, best_n=best_n,
                           auto_n=auto_n, auto_line=auto_line, a_flags=["logo", "orig"], v_flags=["logo"],
                           a_vis=a_vis, v_vis=v_vis,
                           can_more=len(a_vis) < len(a_rows) or len(v_vis) < len(v_rows))
def _ci_show_list(ls, full, scene_status_text=None):
    """Pantalla de la lista; devuelve True si quedan filas ocultas (se ven con «m»)."""
    if full:
        hide_keyboard(0.3)
    if scene_status_text is not None:
        native_clear()
        ux_list_top(ls.title, scene_status_text, animate=not getattr(ls, "top_seen", False))
        ls.top_seen = True
    else:
        clear_screen()
        show_title(ls.title)
    legend(["logo", "orig"])
    nwid = len(str(max(ls.choices))) if ls.choices else None
    a_show = ls.a_rows if full else [ls.a_rows[i] for i in ls.a_vis]
    v_show = ls.v_rows if full else [ls.v_rows[i] for i in ls.v_vis]
    asx, vsx = len(ls.a_rows) - len(a_show), len(ls.v_rows) - len(v_show)
    if ls.a_rows:
        header(t_display("AUDIO") + (f" · +{asx} " + t_display("más") if asx else ""))
        print_rows(a_show, ls.a_flags, [t_display(h) for h in AUDIO_HEAD], num_w=nwid)
    if ls.v_rows:
        header(t_display("VIDEO") + (f" · +{vsx} " + t_display("más") if vsx else ""), gap=False)
        rows, vhead = drop_empty_cols(v_show, VIDEO_HEAD)
        print_rows(rows, ls.v_flags, [t_display(h) for h in vhead], num_w=nwid)
    if ls.auto_n:
        print_rows([{"n": ls.auto_n, "flags": set(), "cols": [ls.auto_line]}], [], num_w=nwid)
    print()
    more = bool(asx or vsx)
    hint(t_display("n.º · b ★ mejor ·") + (" " + t_display("m más · ") if more else " ") + t_display("q salir") + " · " + t_display("escribe 1080, opus o mp4 para filtrar"))
    return more
def _ci_ask(run, ls):
    """3) Elegir. Devuelve (código de salida, None) si se sale (q, Ctrl-C) o (None, (kind, fmt, raw, use_auto))."""
    use_auto = run.use_auto
    full0 = bool(getattr(run, "show_full", False))
    back = ux_list_enter("Ver todos" if full0 else "Elige un formato") if ux_on() else None
    top = scene_list_status(ls, full0) if back is not None else None
    pal = _scene_palette() if back is not None else None
    try:
        return _ci_ask_loop(run, ls, use_auto, full0, top, back)
    finally:
        if pal is not None:
            PALETTE["orange"] = pal
def _scene_palette():
    """Pone el color del sitio como «orange» (números, flechas ▸, marca de predeterminada) y devuelve el original."""
    old = PALETTE["orange"]
    with quiet("_scene_palette"):
        PALETTE["orange"] = (mix(ux_get("a"), ux_get("b"), 0.35), old[1])
    return old
def scene_list_status(ls, full):
    """El estado gris bajo el título de la lista en la escena."""
    n = len(ls.a_rows) + len(ls.v_rows)
    return t_display("Ver todos ·") + f" {n} " + t_display("formatos") if full else t_display("Elige un formato")
def _ci_ask_loop(run, ls, use_auto, full0, top, back):
    choices, auto_n = ls.choices, ls.auto_n
    hidden = _ci_show_list(ls, full0, top)
    cur = PROMPT
    while True:
        try:
            typed = timed_input(cur, None)
            raw = typed.strip().lower()
        except (EOFError, KeyboardInterrupt, OSError):
            return 1, None
        if raw == "q":
            return 0, None
        if raw == "":
            cur = retry_prompt(cur, typed)
            continue
        if raw == "m" and hidden and ls.can_more:
            if top is not None:
                top = scene_list_status(ls, True)
            hidden = _ci_show_list(ls, True, top)
            cur = PROMPT
            continue
        if raw == "b":
            kind, fmt = auto_best(run.audios, run.videos, run.orig_ids, run.can_merge)
            break
        if not raw.isdecimal() and raw not in ("m", "q", "b"):
            _flt = raw.strip()
            _hits = [n for n, (_k, _f) in choices.items() if _flt in str(_f.get("ext") or "").lower() or _flt in str(_f.get("resolution") or "").lower() or _flt in str(_f.get("vcodec") or "").lower() or _flt in str(_f.get("acodec") or "").lower() or _flt in str(res_label(_f) or "").lower()]
            if _hits:
                m_info(f"Filtro «{_flt}»: {len(_hits)} formato(s) · escribe el n.º para elegir o «m» para ver todos")
                hidden = _ci_show_list(ls, True, top)
                cur = PROMPT
                continue
            cur = retry_prompt(cur, typed, bad_prompt(f"1-{len(choices)}, b" + (", m" if hidden else "") + " o q"), f"Sin resultados para «{_flt}»: escribe un número, b" + (", m" if hidden else "") + " o q.")
            continue
        if raw.isdecimal() and int(raw) in choices:
            kind, fmt = choices[int(raw)]
            use_auto = bool(auto_n and int(raw) == auto_n)
            break
        cur = retry_prompt(cur, typed, bad_prompt(f"1-{len(choices)}, b" + (", m" if hidden else "") + " o q"),
                           f"Opción inválida: escribe un número del 1 al {len(choices)}, b"
                           + (", m" if hidden else "") + " o q.")
    ux_list_leave(run, back)
    return None, (kind, fmt, raw, use_auto)
def _choose_interactive(run):
    """[M2] 2)"""
    ls = _ci_rows(run)
    code, pick = _ci_ask(run, ls)
    if pick is None:
        return code
    run.kind, run.fmt, run.raw, run.use_auto = pick
    return None
def _m_choose(run):
    """[M2] 2-3) Con --shortcutpick el atajo ya eligió (resolución/fps o solo audio): se salta la lista."""
    ux_status("Eligiendo formato", frac=0.05)
    if getattr(run, "is_foto", False):
        run.kind, run.fmt = "v", (run.videos[0] if run.videos else run.formats[0])
        run.raw = "foto"
        run.auto = None
        run.use_auto = False
        run.show_full = False
        dbg("elegido", {"entrada": run.raw, "tipo": run.kind, "formato": pick(run.fmt, FMT_KEYS)})
        ux_shape(run.fmt, run.info)
        return None
    audios, videos, spick = run.audios, run.videos, run.spick
    auto = ytdlp_auto_pick(run.info, audios, videos)
    run.auto = auto
    run.use_auto = False
    if getattr(run, "carousel_queued", False) and (run.videos or run.audios):
        _ap = idmm_auto_pick(run)
        if _ap is not None:
            run.kind, run.fmt = _ap[0], _ap[1]
            run.raw = _ap[2]
            dbg("elegido", {"entrada": run.raw, "tipo": run.kind, "formato": pick(run.fmt, FMT_KEYS)})
            ux_shape(run.fmt, run.info)
            return None
    if idmm_direct() and idmm_is_carousel(run) and (run.videos or run.audios):
        _ap = idmm_auto_pick(run)
        if _ap is not None:
            run.kind, run.fmt = _ap[0], _ap[1]
            run.raw = _ap[2]
            dbg("elegido", {"entrada": run.raw, "tipo": run.kind, "formato": pick(run.fmt, FMT_KEYS)})
            ux_shape(run.fmt, run.info)
            return None
    pre = (shortcut_resolve_video(spick, audios, videos, run.tracks, run.orig_ids, run.can_merge, auto)
           if spick else None)
    if pre is not None and spick and str(spick.get("v") or "").lower() == "ytdlp":
        run.use_auto = True
    run.show_full = bool(spick) and str(spick.get("v") or "").strip().lower() in SC_MORE_IDS
    if spick and spick.get("v") and pre is None and not run.show_full:
        item = None
        with quiet("shortcut_remembered"):
            item = shortcut_remembered(video_key(run.info), spick.get("v"))
        fb = shortcut_fallback_video(str(spick.get("v")), audios, videos, run.orig_ids, run.can_merge, item)
        dbg("atajo", {"v": spick.get("v"), "guardado": item, "respaldo": fb[2] if fb else None})
        if fb is not None:
            pre = (fb[0], fb[1])
            m_warn("El formato del atajo ya no está: se usa " + {"mismo id": "el mismo con otro id.", "mismo número": "el mismo con otro id.",
                   "misma calidad": "la misma calidad (otro id).", "calidad más parecida": "la calidad más parecida."}.get(fb[2], "el mejor compatible."))
    if pre is not None:
        run.kind, run.fmt = pre
        run.raw = "atajo"
    else:
        _pr = preset_name()
        _pre = preset_pick(_pr, run.info, audios, videos) if _pr and not spick else None
        if _pre is not None:
            run.kind, run.fmt = _pre
            run.raw = "preset:" + _pr
            m_info(t_display("Preset") + ": " + t_display({"musica": "Preset música", "ligero": "Preset ligero", "maximo": "Preset máximo"}.get(_pr, _pr)))
        else:
            dbg("lista", {"atajo": bool(spick), "v": (spick or {}).get("v"), "ver_todos": run.show_full, "preset": _pr})
            rc = _choose_interactive(run)
            if rc is not None:
                return rc
    dbg("elegido", {"entrada": run.raw, "tipo": run.kind, "formato": pick(run.fmt, FMT_KEYS)})
    ux_shape(run.fmt, run.info)
    return None
def _chosen_text(kind, fmt):
    """Texto de «Elegido»: resolución, contenedor, códec y rango (video) o idioma, códec y bitrate (audio)."""
    if (fmt or {}).get("_idmm_image"):
        return "Foto · " + (res_label(fmt) or "") + f" · {fmt.get('ext') or 'jpg'}"
    if kind == "v":
        bits = []
        bits.append(res_label(fmt) or "Video")
        if fmt.get("ext"):
            bits.append(str(fmt["ext"]))
        vc = (fmt.get("vcodec") or "?").split(".")[0]
        if fmt.get("_guess"):
            vc += "?"
        bits.append(vc)
        if range_label(fmt):
            bits.append(range_label(fmt))
        bits.append(t("con audio") if has(fmt.get("acodec")) else t("sin audio"))
        return " · ".join(bits)
    bits = [str(fmt.get("ext") or "?"),
            acodec_short(fmt),
            f"{abr_of(fmt):.0f}k"]
    lang = fmt.get("language")
    if lang:
        bits.insert(0, str(lang))
    return "audio · " + " · ".join(bits)
def _m_summary(run):
    """[M3] Resumen limpio tras la lista (evita teclado/prompt bajo decenas de filas)."""
    clear_screen()
    show_title(run.title)
    run.elegido = _chosen_text(run.kind, run.fmt)
    return None
def _m_tracks(run):
    """[M4] 4) Armar la selección de pistas (audio principal y extras) y el contenedor de salida."""
    if getattr(run, "is_foto", False):
        m_block("Elegido", [_chosen_text(run.kind, run.fmt)])
        run.fmt_id, run.merge_ext, run.selected = run.fmt["format_id"], None, []
        return None
    kind, fmt, audios, tracks = run.kind, run.fmt, run.audios, run.tracks
    auto, use_auto, spick = run.auto, run.use_auto, run.spick
    fmt_id, merge_ext = fmt["format_id"], None
    selected, audio_line = [], ""
    if kind == "v" and not has(fmt.get("acodec")):
        if not audios:
            m_warn("No hay audio disponible; se descargará solo el video.")
        elif not run.can_merge:
            m_warn("Este video no trae audio y no hay ffmpeg para unirlos.")
            m_info("Se descargará solo el video.")
        else:
            primary = next((t for t in tracks if t["original"]), tracks[0])
            auto_t = (next((t for t in tracks if str(t["fmt"].get("format_id")) == str(auto[1].get("format_id"))), None)
                      if use_auto and auto and auto[1] else None)
            if auto_t is not None:
                primary = auto_t
                selected = [primary]
            elif idmm_direct() and idmm_is_carousel(run):
                selected = [primary]
            elif run.multi_lang and spick:
                primary, selected = shortcut_tracks(spick, tracks, primary)
            elif run.multi_lang:
                primary, no_reply = ask_default_track(tracks, primary)
                selected = [primary] if no_reply else ask_extra_tracks(tracks, primary)
            else:
                selected = [primary]
            fmt_id = "+".join([fmt["format_id"]] + [t["fmt"]["format_id"] for t in selected])
            ok = fmt.get("ext") == "mp4" and all(
                t["fmt"].get("ext") in ("m4a", "mp4") for t in selected)
            merge_ext = "mp4" if ok else "mkv"
            audio_line = ("Audio: " + ", ".join(str(t["lang"]) for t in selected)
                          + (f" ({len(selected)} pistas)" if len(selected) > 1 else ""))
    elif kind == "v" and run.multi_lang:
        audio_line = "Audio: incluido; no admite pistas adicionales"
    m_block("Elegido", [run.elegido] + ([audio_line] if audio_line else []))
    run.fmt_id, run.merge_ext, run.selected = fmt_id, merge_ext, selected
    return None
def _m_convert_reuse(run):
    """[M4] 4b) Si el resultado no es nativo en Apple, ofrecer convertirlo; 4c) ¿ya está descargado así?"""
    kind, fmt, fmt_id, selected = run.kind, run.fmt, run.fmt_id, run.selected
    index, key = run.index, run.key
    plan = None if getattr(run, "is_foto", False) else apple_plan(kind, fmt, selected, run.merge_ext)
    dbg("selección", {"fmt_id": fmt_id, "merge_ext": run.merge_ext,
                      "pistas": [t["fmt"].get("format_id") for t in selected]})
    dbg("plan Apple", plan if plan else "no hace falta (ya es compatible)")
    if idmm_direct() and idmm_is_carousel(run):
        plan = idmm_apple_plan(plan, fmt) if plan else None
    elif plan and run.use_auto:
        m_info("yt-dlp auto: se descarga tal cual, sin convertir.")
        plan = None
    elif plan:
        plan = ask_apple_convert(plan, run.can_merge, guess_duration(run.info, fmt), fmt)
        dbg("conversión", "aceptada" if plan else "rechazada / no disponible")
    run.plan = plan
    run.conv_state = {}
    hist = history_for(key, index)
    old_file, old_entry = history_match(hist, fmt_id, conv_mode({}, plan or {}))
    run.old_file = old_file
    if hist and not old_file:
        m_info("Ya tienes este video con otra calidad o audio: se guarda con el nombre original.")
    if old_file and reuse_downloaded(old_file, old_entry, index, key, run.title, run.info, kind,
                                     fmt, fmt_id, selected, run.orig_ids, plan,
                                     dest_dir=idmm_subfolder_dir(run),
                                     idmm=idmm_direct() and idmm_is_carousel(run),
                                     skip_open=idmm_skip_open(run)):
        return 0
    return None
def _stream_specs(fmt, fmt_id, formats):
    """Especificaciones de streams a (posible) reutilizar desde caché y a reanudar: ([(id, ext)], [(id, ext, tamaño)])."""
    format_specs, resume_specs = [], []
    if "+" in str(fmt_id):
        for part in str(fmt_id).split("+"):
            match = next((f for f in formats if str(f.get("format_id")) == part), None)
            ext = (match.get("ext") if match else None) or "mp4"
            format_specs.append((part, ext))
            resume_specs.append((part, ext, (match or {}).get("filesize")))
    else:
        format_specs.append((str(fmt["format_id"]), fmt.get("ext") or "mp4"))
        resume_specs.append((str(fmt["format_id"]), fmt.get("ext") or "mp4", fmt.get("filesize")))
    return format_specs, resume_specs
class _QuietLog:
    """Logger silencioso de yt-dlp: los avisos y errores se separan en internal/logs y el contexto técnico también va al debug."""
    def debug(self, msg):
        pass
    def info(self, msg):
        pass
    def warning(self, msg):
        diagnostic_report("A", msg)
        dbg("yt-dlp aviso", msg)
    def error(self, msg):
        log_shortcutmode_error(msg)
        dbg("yt-dlp error", msg)
# ─────────── [M6b] 2.0.7: fragmentos en paralelo, subtítulos y etiquetas (mutagen) ───────────
def fragments_n():
    """2.0.7: fragmentos a la vez (DLPY_PARALLEL_FRAGMENTS, 1–16; 4 por omisión)."""
    return int(max(1, min(16, _env_num("DLPY_PARALLEL_FRAGMENTS", 4.0, 1.0))))
def user_set_fragments():
    """2.0.7: ¿el usuario ya pidió -N / --concurrent-fragments en DLPY_YTDLP_EXTRA_ARGS? Entonces no se toca."""
    return any(a == "-N" or a.startswith("-N") and a[2:].isdigit() or a.startswith("--concurrent-fragments")
               for a in user_argv())
def subs_langs(raw=None):
    """2.0.7: DLPY_SUBTITLES → lista de idiomas (['es', 'en']), ['all'] o [] si está apagado o no es válido."""
    v = str(os.environ.get("DLPY_SUBTITLES", "0") if raw is None else raw).strip().lower()
    if v in ("", "0", "no", "off", "false"):
        return []
    if v == "all":
        return ["all"]
    out = [x for x in re.split(r"[,\s;]+", v) if re.fullmatch(r"[a-z]{2,3}(?:-[a-z0-9]{2,8})*", x)]
    return out
YT_CLIENTS = ("android", "web", "ios", "tv", "music", "web_music", "web_safari", "android_music", "android_vr", "mweb")
YT_CLIENT_FALLBACK = ("tv", "android_vr")
def client_list(raw=None):
    """2.1.3: DLPY_YOUTUBE_CLIENT -> lista de clientes YouTube que se FUERZAN. auto (o vacío, o sin validar) = [] = no se fuerza ninguno:
    yt-dlp elige sus propios clientes y devuelve la lista completa de calidades. (2.0.8 forzaba android,web,ios y, con yt-dlp reciente,
    esos clientes devuelven solo 2 calidades.)"""
    v = str(os.environ.get("DLPY_YOUTUBE_CLIENT", "auto") if raw is None else raw).strip().lower()
    if v in ("", "auto", "automatic", "automático", "automatico"):
        return []
    parts = [x.strip() for x in re.split(r"[,\s;]+", v) if x.strip()]
    return [x for x in parts if x in YT_CLIENTS]
def client_attempts():
    """2.1.3: intentos de la descarga, en orden: auto = el predeterminado de yt-dlp (None) y, si lo bloquean, tv y android_vr; con clientes fijados, uno por intento."""
    forced = client_list()
    return forced if forced else [None] + list(YT_CLIENT_FALLBACK)
def youtube_extractor_args():
    """2.1.3: extractor_args de YouTube para el análisis y la descarga: solo lo que el usuario fijó (clientes, PO token); None si no hay nada que forzar,
    así no se pisan los extractor_args de DLPY_YTDLP_EXTRA_ARGS."""
    ea = {}
    cl = client_list()
    if cl:
        ea["player_client"] = list(cl)
    pt = po_token()
    if pt:
        ea["po_token"] = [pt]
    return {"youtube": ea} if ea else None
def cookies_path(raw=None):
    """2.0.8: DLPY_COOKIES_FILE -> ruta si el archivo existe, si no None (se ignora, no se rompe la descarga)."""
    v = str(os.environ.get("DLPY_COOKIES_FILE", "") if raw is None else raw).strip()
    if not v:
        return None
    cand = os.path.expanduser(os.path.expandvars(v))
    if os.path.isfile(cand):
        return cand
    dbg("cookies", "DLPY_COOKIES_FILE no existe, se ignora")
    return None
def po_token(raw=None):
    """2.0.8: DLPY_YOUTUBE_PO_TOKEN -> token o None."""
    v = str(os.environ.get("DLPY_YOUTUBE_PO_TOKEN", "") if raw is None else raw).strip()
    return v or None
def batch_enabled():
    """2.0.8: DLPY_BATCH_DOWNLOADS=1 acepta varios enlaces en cola."""
    return _flag_env("DLPY_BATCH_DOWNLOADS", True)
# ─────────── [M6c] 2.0.8: IDMM (carousel downloader manager) ───────────
def idmm_direct():
    """2.0.8 + IDMM: DLPY_CAROUSEL_DIRECT_DOWNLOAD=1 (predeterminado) = descarga directa del carrusel: sin preguntar ni listar nada."""
    return _flag_env("DLPY_CAROUSEL_DIRECT_DOWNLOAD", True)
def idmm_subfolder():
    """2.0.8 + IDMM: DLPY_CAROUSEL_SUBFOLDER=1 (predeterminado) = cada carrusel en su propia carpeta. 0 = todo plano."""
    return _flag_env("DLPY_CAROUSEL_SUBFOLDER", True)
def idmm_is_carousel(run):
    """2.0.8 + IDMM: True si este run es parte de un carrusel (varios medios). Un enlace solo no es IDMM."""
    try:
        return bool(getattr(run, "carousel_items", None)) or getattr(run, "carousel_choice", None) is not None
    except Exception:
        return False
def idmm_skip_open(run):
    """IDMM unificado: True si NO hay que abrir este archivo en view/Atajos.
    Solo el carrusel (IDMM) no abre, sea Threads o Instagram. Un enlace solo sin carrusel NO es IDMM
    y abre como cualquier solo (se quita la excepcion "Threads solo sigue sin abrir")."""
    try:
        return bool(idmm_is_carousel(run))
    except Exception:
        return False
def idmm_ensure_scene(run):
    """IDMM nunca cae a UIM: si el enlace es IDMM (Instagram/Threads) y la escena esta apagada,
    intenta arrancarla ANTES de analizar, para que "Analizando enlace" se vea en la escena (UX),
    no en UIM ("Analizando enlace..." en texto plano + barra). Sin escena (terminal sin color/anim,
    DEBUG, --scm) ux_start devuelve False y el analisis sigue en UIM como antes: nunca rompe.
    En --scb IDMM la escena ya esta viva (scb_scene_start), asi que es no-op. En terminal normal
    IDMM el primer medio ya no es UIM y la cola ya no es el primer momento en UX."""
    try:
        if ux_on():
            return False
        link = getattr(run, "link", "") or ""
        if not is_idmm_link(link):
            return False
        if DEBUG or _scm_run():
            return False
        return bool(ux_start(run))
    except Exception:
        return False
def idmm_subfolder_name(run):
    """2.0.8 + IDMM: nombre de la carpeta de este carrusel: titulo del POST (el del padre), sin el « · N de M · ...» del medio. '' si no es carrusel."""
    try:
        if not idmm_is_carousel(run):
            return ""
        parent = getattr(run, "carousel_parent", None) or {}
        title = (parent.get("title") if isinstance(parent, dict) else None) or getattr(run, "title", "") or ""
        title = str(title).split(" · ")[0].strip()
        return safe_name(title) or ""
    except Exception:
        return ""
def idmm_subfolder_dir(run):
    """2.0.8 + IDMM: carpeta donde se guarda este archivo (dlpy_files/<titulo del post> con subfolder, dlpy_files si no)."""
    try:
        if idmm_subfolder() and idmm_is_carousel(run):
            name = idmm_subfolder_name(run)
            if name:
                return os.path.join(FILES_DIR, name)
    except Exception:
        pass
    return FILES_DIR
IDMM_EXIT = {"files": [], "done": False}
def idmm_exit_track(run):
    """salida IDMM: anota run.final si es carrusel y el archivo existe. Sin duplicados."""
    try:
        if not idmm_is_carousel(run):
            return False
        final = getattr(run, "final", "") or ""
        if not final or not os.path.isfile(final):
            return False
        key = os.path.abspath(final)
        if key not in [os.path.abspath(f) for f in IDMM_EXIT["files"]]:
            IDMM_EXIT["files"].append(final)
        return True
    except Exception:
        return False
def idmm_exit_animation():
    """salida IDMM: animacion de salida, luego clear y notificacion, luego cerrar sin clear.
    Orden exacto que pidio el usuario:
    1) Animacion de salida (con escena: "Guardado" + outro hacia el centro; sin escena: "Cerrando..." con puntos).
    2) clear (clear_screen: borra y deja el banner).
    3) Notifica: "N archivo(s) guardado(s) en <directorio>" + lista de nombres.
    4) Marca done=True: el finally de main() ya NO vuelve a hacer clear, asi el mensaje queda fijo
       y el script cierra sin borrarlo. Sin carrusel (sin archivos) no hace nada: el flujo normal sigue igual.
    """
    try:
        files = [f for f in list(IDMM_EXIT.get("files") or []) if f]
        existing = [f for f in files if os.path.isfile(f)]
        if existing:
            files = existing
        if not files:
            return False
        n = len(files)
        dirs = sorted({os.path.dirname(os.path.abspath(f)) for f in files})
        dest = dirs[0] if len(dirs) == 1 else FILES_DIR
        if ux_on():
            try:
                ux_status("Guardado", frac=1.0)
                with quiet("idmm_exit_animation"):
                    scene_outro()
            except Exception:
                pass
            try:
                ux_stop(clear=False)
            except Exception as _ign:
                diagnostic_report("A", f"idmm_exit_animation: parar escena: {type(_ign).__name__}: {_ign}")
                pass
            if QUIET.get("on"):
                try:
                    quiet_set(False)
                except Exception:
                    pass
        else:
            try:
                if sys.stdout.isatty() and not DEBUG:
                    sys.stdout.write(t_display("Cerrando"))
                    sys.stdout.flush()
                    for _ in range(3):
                        time.sleep(0.25)
                        sys.stdout.write(".")
                        sys.stdout.flush()
                    sys.stdout.write("\n")
                    sys.stdout.flush()
                else:
                    time.sleep(0.2)
            except Exception:
                pass
        try:
            clear_screen()
        except Exception as _ign:
            diagnostic_report("A", f"idmm_exit_animation: limpiar pantalla: {type(_ign).__name__}: {_ign}")
            pass
        if n == 1:
            m_ok(t_display(f"1 archivo guardado en: {dest}"))
        else:
            m_ok(t_display(f"{n} archivos guardados en: {dest}"))
        shown = files[:20]
        for f in shown:
            try:
                note(os.path.basename(f))
            except Exception:
                pass
        if n > len(shown):
            try:
                note(t_display(f"... y {n - len(shown)} más"))
            except Exception:
                pass
        IDMM_EXIT["done"] = True
        IDMM_EXIT["files"] = []
        return True
    except Exception as _ign:
        try:
            ignore("idmm_exit_animation", _ign)
        except Exception:
            pass
        return False
def idmm_apple_plan(plan, fmt=None):
    """2.0.8 + IDMM: plan Apple sin preguntar (la version directa de ask_apple_convert). Bits: se sondean si faltan y se conservan hasta 10 (lo maximo de Apple). None si no hay ffmpeg (se baja tal cual)."""
    if not plan:
        return plan
    if not ffmpeg_available():
        return None
    try:
        plan.pop("ask_enter", None)
        if plan.get("venc") and not plan.get("bits") and fmt and stream_can_probe(fmt):
            got = probe_stream_bits_timed(_FfmpegShim().executable, fmt)
            if got:
                plan["bits"] = got
                plan["out_bits"] = min(encode_bits(got), 10)
        plan_target(plan, _FfmpegShim().executable)
        if plan.get("bits"):
            plan["out_bits"] = min(encode_bits(plan["bits"]), 10)
        plan["asked_bits"] = False
        return plan
    except Exception as _ign:
        ignore("idmm_apple_plan", _ign)
        return plan
IDMM_PHOTO_CONVERT = {"webp": "jpg", "avif": "jpg", "bmp": "jpg", "svg": "jpg"}
def idmm_convert_photo(path):
    """2.0.8 + IDMM: convierte una foto no nativa en Apple (webp/avif/bmp/svg) a jpg con ffmpeg. Devuelve la ruta nueva o None (se conserva el original). Sin ffmpeg o si falla, None: nunca se pierde el archivo."""
    try:
        ext = os.path.splitext(str(path or ""))[1].lower().lstrip(".")
        if ext not in IDMM_PHOTO_CONVERT:
            return None
        exe = tool_executable("ffmpeg")
        if not exe or not os.path.isfile(path):
            return None
        import subprocess
        out = os.path.splitext(path)[0] + ".jpg"
        if os.path.abspath(out) == os.path.abspath(path):
            return None
        r = run_tool([exe, "-y", "-hide_banner", "-loglevel", "error", "-i", "file:" + path, "file:" + out],
                           capture_output=True, timeout=60)
        if r.returncode == 0 and os.path.isfile(out) and os.path.getsize(out) > 0:
            return out
        with quiet("idmm_convert_photo", OSError):
            os.remove(out)
        return None
    except Exception as _ign:
        ignore("idmm_convert_photo", _ign)
        return None
def idmm_convert_native_video(path, plan, fmt=None, info=None, bar=None):
    """IDMM unificado: convierte un video nativo IDMM (Instagram o Threads, bajado por HTTP directo, sin yt-dlp) con el plan Apple ya aceptado. Devuelve (ruta nueva, codec usado) o None (se conserva el original). El camino yt-dlp ya lo hace con make_apple_pp; el nativo no tenia conversion."""
    try:
        if not plan or not os.path.isfile(path):
            return None
        ext = plan_ext(plan) or "mp4"
        out = os.path.splitext(path)[0] + "." + ext
        if os.path.abspath(out) == os.path.abspath(path):
            out = os.path.splitext(path)[0] + ".apple." + ext
        used = apple_convert_file(_FfmpegShim(), path, dict(plan), guess_duration(info, fmt), bar, out)
        if os.path.isfile(out) and os.path.getsize(out) > 0:
            return out, used
        return None
    except Exception as _ign:
        ignore("idmm_convert_native_video", _ign)
        return None
def sponsor_categories():
    """2.0.8: DLPY_REMOVE_SPONSORS=1 -> sponsor,intro,outro. Si no, []."""
    return ["sponsor", "intro", "outro"] if _flag_env("DLPY_REMOVE_SPONSORS", False) else []
def preset_name(raw=None):
    """2.0.8: DLPY_FORMAT_PRESET -> '' | musica | ligero | maximo. Aliases music/light/max. Invalido = ''."""
    v = str(os.environ.get("DLPY_FORMAT_PRESET", "") if raw is None else raw).strip().lower()
    if v in ("", "musica", "music"):
        return "musica" if v else ""
    if v in ("ligero", "light"):
        return "ligero"
    if v in ("maximo", "max", "maximum"):
        return "maximo"
    return ""
def preset_pick(preset, info, audios, videos):
    """2.0.8: (kind, fmt) del preset o None si no hay candidatos. musica = mejor audio; ligero = mejor video <=720p; maximo = mejor video."""
    preset = preset_name(preset) if isinstance(preset, str) else ""
    if not preset:
        return None
    if preset == "musica":
        cands = list(audios or [])
        if not cands:
            return None
        best = max(cands, key=lambda f: (abr_of(f), f.get("tbr") or 0, f.get("filesize") or 0))
        return ("a", best)
    cands = list(videos or [])
    if not cands:
        return None
    if preset == "ligero":
        low = [f for f in cands if (f.get("height") or 0) <= 720]
        pool = low or cands
    else:
        pool = cands
    best = max(pool, key=lambda f: ((f.get("height") or 0), (f.get("fps") or 0), (f.get("tbr") or 0)))
    return ("v", best)
def split_batch_links(raw):
    """2.0.8: varios enlaces -> lista unica en orden. Uno por linea, separados por coma + http, o por espacios + http."""
    s = str(raw or "")
    if not s.strip():
        return []
    parts = re.split(r"[\r\n]+", s)
    out = []
    for part in parts:
        for chunk in re.split(r",(?=https?://)", part):
            for tok in re.split(r"\s+(?=https?://)", chunk.strip()):
                tok = tok.strip().strip(",;")
                if re.match(r"^https?://\S+$", tok) and tok not in out:
                    out.append(tok)
    return out
def subs_langs_effective(info, raw=None):
    """2.0.8: DLPY_SUBTITLES con fallback. Si ninguno de los pedidos existe en el video, cae a en si esta disponible."""
    req = subs_langs(raw)
    if not req or req == ["all"]:
        return req
    info = info or {}
    avail = set()
    for key in ("subtitles", "automatic_captions"):
        try:
            for lang in (info.get(key) or {}).keys():
                avail.add(str(lang).lower())
                avail.add(str(lang).lower().split("-")[0])
        except AttributeError:
            pass
    if not avail:
        return req
    present = [l for l in req if l.lower() in avail or l.lower().split("-")[0] in avail]
    if present:
        return present
    if "en" in avail:
        dbg("subtitulos", "ninguno de los pedidos existe, se usa en")
        return ["en"]
    return req
def verify_file(path, info=None):
    """2.0.8: (ok, motivo). DLPY_VERIFY_FILE=0 -> siempre ok. Sin ffprobe, solo existe + tamano > 0. Con ffprobe, ademas duracion coherente."""
    if not _flag_env("DLPY_VERIFY_FILE", True):
        return True, "sin verificar"
    if not path or not os.path.isfile(path):
        return False, "no existe"
    try:
        size = os.path.getsize(path)
    except OSError:
        return False, "no se puede leer"
    if size <= 0:
        return False, "tamano 0"
    if str(path or "").lower().endswith((".jpg", ".jpeg", ".png", ".webp", ".avif")):
        return True, "foto"
    pr = tool_executable("ffprobe")
    if not pr:
        return True, "sin ffprobe"
    try:
        import subprocess
        r = run_tool([pr, "-v", "error", "-show_entries", "format=duration", "-of", "json", "file:" + path],
                           capture_output=True, text=True, timeout=20)
        if r.returncode != 0:
            return False, "ffprobe no lo abre"
        dur = float((json.loads(r.stdout or "{}").get("format") or {}).get("duration") or 0)
    except Exception as _ign:
        ignore("verify_file", _ign)
        return True, "sin verificar (ffprobe fallo)"
    if dur <= 0:
        return True, "sin duracion"
    want = None
    try:
        want = float((info or {}).get("duration") or 0)
    except (TypeError, ValueError):
        want = None
    if want and want > 0 and dur < want * 0.9 and abs(want - dur) > 5:
        return False, f"duracion {dur:.0f}s < esperada {want:.0f}s"
    return True, "ok"
def _is_youtube(info):
    """2.0.8: True si el extractor es YouTube (solo ahi aplican cliente / cookies / PO token)."""
    ext = str((info or {}).get("extractor_key") or (info or {}).get("extractor") or "").lower()
    return "youtube" in ext or "youtu" in ext
def sub_files(res):
    """2.0.7: rutas de los subtítulos que yt-dlp dejó (requested_subtitles con filepath), que existan."""
    out = []
    try:
        for lang, d in sorted(((res or {}).get("requested_subtitles") or {}).items()):
            fp = (d or {}).get("filepath")
            if fp and os.path.isfile(fp):
                out.append((str(lang), fp))
    except AttributeError:
        pass
    return out
def store_subs(subs, final):
    """2.0.7: copia los subtítulos junto a `final` como «<nombre>.<idioma>.<ext>». Devuelve cuántos. Un fallo no detiene nada."""
    n = 0
    root = os.path.splitext(final)[0]
    for lang, fp in subs or []:
        try:
            ext = os.path.splitext(fp)[1] or ".vtt"
            dst = f"{root}.{lang}{ext}"
            if os.path.isfile(dst):
                os.remove(dst)
            move_file(fp, dst)
            n += 1
        except Exception as _ign:
            ignore("store_subs", _ign)
    return n
def _cover_bytes(thumb):
    """2.0.7: (bytes, 'jpeg'|'png') de la miniatura; webp/avif se pasa a jpg con ffmpeg (Pillow eliminado,
    opcion A: en a-Shell no se instala, y la conversion ya tenia respaldo con ffmpeg). None si no se puede."""
    ext = os.path.splitext(thumb)[1].lower()
    if ext in (".jpg", ".jpeg", ".png"):
        with open(thumb, "rb") as fh:
            return fh.read(), ("png" if ext == ".png" else "jpeg")
    exe = tool_executable("ffmpeg")
    if exe and ext in (".webp", ".avif", ".bmp", ".gif"):
        import subprocess
        tmp = thumb + ".dlpy-cover.jpg"
        try:
            r = run_tool([exe, "-y", "-hide_banner", "-loglevel", "error", "-i", "file:" + thumb, "file:" + tmp],
                               capture_output=True, timeout=20)
            if r.returncode == 0 and os.path.isfile(tmp):
                with open(tmp, "rb") as fh:
                    return fh.read(), "jpeg"
        except Exception as _ign:
            ignore("_cover_bytes ffmpeg", _ign)
        finally:
            with quiet("_cover_bytes", OSError):
                os.remove(tmp)
    return None
def _tag_extra(info):
    """2.0.8: album, fecha, genero, pista y letra que yt-dlp trae (si los trae)."""
    info = info or {}
    album = str(info.get("album") or "")
    date = str(info.get("release_date") or info.get("upload_date") or info.get("release_year") or "")
    if len(date) >= 8 and date[:8].isdigit():
        date = f"{date[:4]}-{date[4:6]}-{date[6:]}"
    genre = ""
    g = info.get("genre") or info.get("genres") or ""
    if isinstance(g, (list, tuple)) and g:
        genre = str(g[0])
    elif g:
        genre = str(g)
    track = ""
    try:
        track = str(int(info.get("track_number") or info.get("track") or 0) or "")
        if track == "0":
            track = ""
    except (TypeError, ValueError):
        track = ""
    lyrics = str(info.get("lyrics") or "")
    return {"album": album, "date": date, "genre": genre, "track": track, "lyrics": lyrics}
def _strip_dlpy(text):
    """Quita un sufijo/prefijo DLpy de un Software/Comentario viejo, sin anidar.
    Acepta las dos formas que el script ha escrito: "DLpy 2.0.8 (Lavf...)" (MP4, 2.0.8
    viejo) y "Lavf... (DLpy 2.0.8)" (forma nueva) y "nota · DLpy 2.0.8" (comentarios).
    Devuelve el texto original limpio ("" si solo era DLpy). Se aplica en bucle para
    no dejar "DLpy ... (DLpy ...)" si el archivo ya paso por dos versiones.
    """
    try:
        out = str(text or "").strip().strip("\x00").strip()
        for _ in range(3):
            if not out:
                break
            m = re.match(r"^DLpy \d+\.\d+\.\d+\s*\((.*)\)\s*$", out, flags=re.S)
            if m:
                out = str(m.group(1) or "").strip()
                continue
            m = re.match(r"^(.*)\s*\(DLpy \d+\.\d+\.\d+\)\s*$", out, flags=re.S)
            if m:
                out = str(m.group(1) or "").strip()
                continue
            m = re.match(r"^(.*)\s*[·|]\s*DLpy \d+\.\d+\.\d+\s*$", out, flags=re.S)
            if m:
                out = str(m.group(1) or "").strip()
                continue
            if re.match(r"^DLpy \d+\.\d+\.\d+$", out):
                out = ""
                break
            break
        return out
    except Exception:
        return str(text or "")
def _image_software_final(artist, orig_software):
    """Software (305) final SOLO para imagenes: el autor original puro, sin DLpy.
    Por spec Software es el programa, y en Apple "Creador del contenido"
    (kMDItemCreator) es la aplicacion, no la persona; el campo de la persona es
    IPTC Creator / XMP dc:creator / EXIF Artist. PERO Archivos de iOS solo muestra
    Software como renglon de creador en fotos (no muestra Artist), asi que en
    imagenes ese campo lleva el autor original: es lo que el usuario ve como
    "Creador del contenido". La version DLpy NUNCA va aqui (en una foto de Threads,
    que llega sin Software, "software original + DLpy" caia a "DLpy" solo y tapaba
    al autor: la captura "Creador del contenido: DLpy 2.0.8" con autor "有傑克 (@_yujak)").
    Si no hay autor, se conserva el software original tal cual; si tampoco hay
    software, "" (no se inventa "DLpy" como creador: _build_tiff_exif omite 305 vacio).
    Solo imagenes: en video/audio, ©too/TENC/ENCODER siguen usando _merge_software
    (codificador original + DLpy), porque ahi Archivos si muestra autor y software
    en filas separadas.
    """
    _a = _strip_dlpy(artist)
    if _a:
        return _a
    return _strip_dlpy(orig_software)
def _image_comment_final(orig_comment, orig_software, artist, usercomment=None):
    """UserComment/Comment final para imagenes: comentario + DLpy + software original.
    Base = _merge_comment(comentario original o usercomment): "comentario · DLpy 2.0.8"
    o "DLpy 2.0.8". Si habia un software original distinto del autor (p. ej. "Adobe
    Photoshop"), se conserva aqui como "(Software original: ...)" porque el campo
    Software ya lo ocupa el autor y no se puede perder. Si el software original ERA
    el autor (bajada anterior correcta) o era solo "DLpy" (bajada con el bug), no se
    anade nota: no hay nada que preservar. Si una bajada anterior ya metio la nota
    en el comentario, se extrae y se vuelve a poner una sola vez (sin duplicar).
    """
    _cmt = str(orig_comment or usercomment or "")
    _soft_note = ""
    _m = re.search(r"\(Software original: ([^)]+)\)", _cmt)
    if _m:
        _soft_note = _m.group(1).strip()
        _cmt = (_cmt[:_m.start()] + _cmt[_m.end():]).strip().strip("·").strip()
    _a = _strip_dlpy(artist)
    _s_orig = _strip_dlpy(orig_software)
    if _s_orig and _s_orig != _a:
        _s = _s_orig
    else:
        _s = _soft_note
    base = _merge_comment(_cmt)
    if _s and _s != _a:
        base = f"{base} (Software original: {_s})"
    return base
def _merge_software(orig):
    """Software final: original + dato extra DLpy, respetando lo original.
    "Lavf61.7.100" -> "Lavf61.7.100 (DLpy 2.0.8)"; "" -> "DLpy 2.0.8" (DLpy es quien
    escribio los metadatos); "DLpy 2.0.7 (Lavf...)" -> "Lavf... (DLpy 2.0.8)".
    El autor NUNCA va aqui: va en Artist/Copyright.
    Solo video/audio (©too/TENC/ENCODER). Para imagenes, usar _image_software_final
    (Software = autor, porque Archivos solo muestra ese campo como Creador).
    """
    clean = _strip_dlpy(orig)
    if clean:
        return f"{clean} (DLpy {VERSION})"
    return f"DLpy {VERSION}"
def _merge_comment(orig):
    """Comentario final: comentario original + dato extra DLpy.
    "nota" -> "nota · DLpy 2.0.8"; "" -> "DLpy 2.0.8"; "nota · DLpy 2.0.7" ->
    "nota · DLpy 2.0.8" (sin anidar).
    """
    clean = _strip_dlpy(orig)
    if clean:
        return f"{clean} · DLpy {VERSION}"
    return f"DLpy {VERSION}"
def _tiff_read_software_comment(tiff):
    """Lee Software (305) y UserComment (37510) de un TIFF crudo. {} si no se entiende.
    Soporta II (little) y MM (big). UserComment viene con prefijo b"ASCII\\x00\\x00\\x00"
    (se quita). No lanza: si el TIFF esta roto, devuelve {} y el llamador usa "".
    """
    out = {}
    try:
        if not tiff or len(tiff) < 8:
            return out
        if tiff[:2] == b"II":
            bo = "little"
        elif tiff[:2] == b"MM":
            bo = "big"
        else:
            return out
        if int.from_bytes(tiff[2:4], bo) != 42:
            return out
        _sizes = {1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 6: 1, 7: 1, 8: 2, 9: 4, 10: 8, 11: 4, 12: 8}
        def _read_ifd(off):
            tags = {}
            if off <= 0 or off + 2 > len(tiff):
                return tags, None
            n = int.from_bytes(tiff[off:off + 2], bo)
            if off + 2 + n * 12 > len(tiff):
                return tags, None
            exif_off = None
            for i in range(n):
                e = tiff[off + 2 + i * 12: off + 2 + (i + 1) * 12]
                tag = int.from_bytes(e[0:2], bo)
                typ = int.from_bytes(e[2:4], bo)
                cnt = int.from_bytes(e[4:8], bo)
                field = e[8:12]
                if typ not in _sizes:
                    continue
                total = cnt * _sizes[typ]
                if total <= 4:
                    raw = field[:total]
                else:
                    doff = int.from_bytes(field, bo)
                    if doff < 0 or doff + total > len(tiff):
                        continue
                    raw = tiff[doff:doff + total]
                tags[tag] = (typ, raw)
                if tag == 34665 and typ == 4 and cnt == 1:
                    exif_off = int.from_bytes(field, bo)
            return tags, exif_off
        tags0, exif_off = _read_ifd(int.from_bytes(tiff[4:8], bo))
        if 305 in tags0:
            _typ, _raw = tags0[305]
            if _typ == 2:
                out["software"] = _raw.decode("utf-8", "replace").rstrip("\x00").strip()
        if exif_off:
            tags_e, _ = _read_ifd(exif_off)
            if 37510 in tags_e:
                _typ, _raw = tags_e[37510]
                raw = bytes(_raw)
                if raw.startswith(b"ASCII\x00\x00\x00"):
                    raw = raw[8:]
                out["usercomment"] = raw.decode("utf-8", "replace").rstrip("\x00").strip()
        return out
    except Exception:
        return out
def _png_text_decode(cdata, ctype):
    """(keyword, texto) de un chunk PNG tEXt / iTXt / zTXt. ("", "") si no se entiende."""
    try:
        if ctype == b"tEXt":
            key, _, val = bytes(cdata).partition(b"\x00")
            return key.decode("latin-1", "replace"), val.decode("latin-1", "replace")
        if ctype == b"zTXt":
            import zlib as _zlib
            key, _, rest = bytes(cdata).partition(b"\x00")
            if not rest:
                return key.decode("latin-1", "replace"), ""
            val = _zlib.decompress(rest[1:])
            return key.decode("latin-1", "replace"), val.decode("latin-1", "replace")
        if ctype == b"iTXt":
            raw = bytes(cdata)
            k_end = raw.find(b"\x00")
            if k_end < 0 or len(raw) < k_end + 3:
                return "", ""
            key = raw[:k_end].decode("latin-1", "replace")
            flag = raw[k_end + 1]
            rest = raw[k_end + 3:]
            l_end = rest.find(b"\x00")
            if l_end < 0:
                return key, ""
            rest = rest[l_end + 1:]
            t_end = rest.find(b"\x00")
            if t_end < 0:
                return key, ""
            text = rest[t_end + 1:]
            if flag == 1:
                import zlib as _zlib
                text = _zlib.decompress(text)
            return key, text.decode("utf-8", "replace")
        return "", ""
    except Exception:
        return "", ""
def _ffprobe_tags(path):
    """Tags de formato con ffprobe (dict con claves en minusculas). {} si no hay ffprobe."""
    try:
        import subprocess as _sp
        exe = tool_executable("ffprobe")
        if not exe:
            return {}
        r = run_tool([exe, "-v", "error", "-show_entries", "format_tags", "-of", "json", "file:" + path],
                     capture_output=True, text=True, timeout=20)
        if r.returncode != 0:
            return {}
        tags = (json.loads(r.stdout or "{}").get("format") or {}).get("tags") or {}
        return {str(k).lower(): str(v) for k, v in tags.items()}
    except Exception:
        return {}
def _ffmpeg_copy_with_tags(path, tags):
    """Reescribe SOLO metadatos con ffmpeg -c copy (sin re-codificar). True si quedo.
    tags: {clave ffmpeg: valor} (title, artist, album, date, genre, tracknumber,
    comment, encoder, lyrics...). Las claves vacias no se pasan. Escribe a un
    temporal y solo reemplaza si ffmpeg salio bien y el temporal existe y no esta
    vacio: el archivo original nunca se pierde por unas etiquetas.
    OJO: el temporal conserva la extension del original (sin ella ffmpeg no sabe
    que muxer usar y falla). Y ffmpeg pisa `encoder` con su propio Lavf aunque se
    le pase -metadata encoder (probado en WAV/MKV): la version queda en `comment`
    (que si se escribe), y el encoder queda el Lavf original.
    """
    try:
        import subprocess as _sp
        exe = tool_executable("ffmpeg")
        if not exe or not path or not os.path.isfile(path):
            return False
        clean = {str(k): str(v) for k, v in (tags or {}).items() if str(v or "").strip()}
        if not clean:
            return False
        _ext = os.path.splitext(path)[1] or ""
        tmp = path + ".dlpy_tags_tmp" + _ext
        cmd = [exe, "-y", "-hide_banner", "-loglevel", "error", "-i", "file:" + path,
               "-map", "0", "-c", "copy"]
        for k, v in clean.items():
            cmd += ["-metadata", f"{k}={v}"]
        cmd += ["file:" + tmp]
        r = run_tool(cmd, capture_output=True, timeout=60)
        if r.returncode != 0 or not os.path.isfile(tmp) or os.path.getsize(tmp) <= 0:
            with quiet("_ffmpeg_copy_with_tags", OSError):
                os.remove(tmp)
            dbg("ffmpeg -c copy metadatos fallo", (r.stderr or b"")[:300] if r.stderr else "")
            return False
        os.replace(tmp, path)
        return True
    except Exception as e:
        dbg("ffmpeg -c copy metadatos fallo", f"{type(e).__name__}: {e}")
        try:
            with quiet("_ffmpeg_copy_with_tags", OSError):
                os.remove(path + ".dlpy_tags_tmp" + (os.path.splitext(path)[1] or ""))
        except Exception:
            pass
        return False
def _tiff_ifd_entries(fields, data_base):
    """Entradas de un IFD TIFF: [(tag, tipo, valor)]. Tipo 4 (LONG) con valor int va en linea; lo demas
    (ASCII/UNDEFINED) va en linea si cabe en 4 bytes, si no por offset en el blob. Devuelve (entradas, blob)."""
    entries = b""
    blob = b""
    for tag, typ, val in fields:
        if typ == 4:
            entries += tag.to_bytes(2, "little") + typ.to_bytes(2, "little") + (1).to_bytes(4, "little")
            entries += int(val).to_bytes(4, "little")
        else:
            raw = bytes(val)
            if len(raw) <= 4:
                entries += tag.to_bytes(2, "little") + typ.to_bytes(2, "little") + len(raw).to_bytes(4, "little")
                entries += raw.ljust(4, b"\x00")
            else:
                off = data_base + len(blob)
                entries += tag.to_bytes(2, "little") + typ.to_bytes(2, "little") + len(raw).to_bytes(4, "little")
                entries += off.to_bytes(4, "little")
                blob += raw
    return entries, blob
def _build_tiff_exif(title, artist, date, software, usercomment):
    """TIFF EXIF: IFD0 (titulo 270, software 305, fecha 306, autor 315, copyright 33432, puntero 34665
    a ExifIFD) + ExifIFD (UserComment 37510, la version del script). Entradas ordenadas por tag (lo exige
    el TIFF). Devuelve los bytes del TIFF crudo (sin "Exif\\0\\0": el WebP lo lleva crudo y el JPEG lo
    envuelve en APP1)."""
    ifd0 = []
    if title:
        ifd0.append((270, 2, str(title).encode("utf-8") + b"\x00"))
    if software:
        ifd0.append((305, 2, str(software).encode("utf-8") + b"\x00"))
    if date:
        ifd0.append((306, 2, str(date).encode("utf-8") + b"\x00"))
    if artist:
        ifd0.append((315, 2, str(artist).encode("utf-8") + b"\x00"))
        ifd0.append((33432, 2, str(artist).encode("utf-8") + b"\x00"))
    exif = []
    if usercomment:
        exif.append((37510, 7, b"ASCII\x00\x00\x00" + str(usercomment).encode("utf-8") + b"\x00"))
    ifd0.sort(key=lambda kv: kv[0])
    exif.sort(key=lambda kv: kv[0])
    n0 = len(ifd0) + (1 if exif else 0)
    exif_off = 14 + 12 * n0 if exif else 0
    data_base = (exif_off + 2 + 12 * len(exif) + 4) if exif else (14 + 12 * n0)
    ifd0_fields = list(ifd0)
    if exif:
        ifd0_fields.append((34665, 4, exif_off))
    ifd0_entries, blob0 = _tiff_ifd_entries(ifd0_fields, data_base)
    exif_entries, blob1 = _tiff_ifd_entries(exif, data_base + len(blob0))
    tiff = b"II" + (42).to_bytes(2, "little") + (8).to_bytes(4, "little")
    tiff += n0.to_bytes(2, "little") + ifd0_entries + (0).to_bytes(4, "little")
    if exif:
        tiff += len(exif).to_bytes(2, "little") + exif_entries + (0).to_bytes(4, "little")
    tiff += blob0 + blob1
    return tiff
def _embed_webp_exif_pure(final, title, artist, date, software=None, usercomment=None):
    """EXIF (chunk EXIF) en un WebP: sin tocar los datos de imagen. Devuelve (ok, motivo).
    Si ya hay VP8X, se marca su flag EXIF y se sustituye el chunk EXIF viejo; si no hay VP8X, se crea
    (con las dimensiones del VP8/VP8L) y se inserta el chunk EXIF tras el. Sin esto, el WebP salia sin
    metadatos (el panel de Archivos no mostraba ni creador). Software = AUTOR original (lo que
    Archivos muestra como Creador); UserComment = comentario original + DLpy + software
    original preservado. DLpy NUNCA va en Software en imagenes."""
    try:
        with open(final, "rb") as fh:
            data = fh.read()
        if len(data) < 12 or data[:4] != b"RIFF" or data[8:12] != b"WEBP":
            return False, "no es WebP"
        chunks = []
        pos = 12
        end = len(data)
        vp8x_idx = None
        exif_idx = None
        while pos + 8 <= end:
            ln = int.from_bytes(data[pos + 4:pos + 8], "little")
            ctype = data[pos:pos + 4]
            if pos + 8 + ln > end:
                return False, "WebP corrupto"
            cdata = data[pos + 8:pos + 8 + ln]
            chunks.append([ctype, cdata])
            if ctype == b"VP8X":
                vp8x_idx = len(chunks) - 1
            if ctype == b"EXIF":
                exif_idx = len(chunks) - 1
            pos += 8 + ln + (ln & 1)
        _orig_soft, _orig_cmt = "", ""
        if exif_idx is not None:
            _parsed = _tiff_read_software_comment(chunks[exif_idx][1])
            _orig_soft = _parsed.get("software") or ""
            _orig_cmt = _parsed.get("usercomment") or ""
            chunks.pop(exif_idx)
            if vp8x_idx is not None and exif_idx < vp8x_idx:
                vp8x_idx -= 1
        _soft_final = _image_software_final(artist, _orig_soft or software)
        _cmt_final = _image_comment_final(_orig_cmt, _orig_soft or software, artist, usercomment)
        tiff = _build_tiff_exif(title, artist, date, _soft_final, _cmt_final)
        if vp8x_idx is None:
            w = h = None
            alpha = False
            for ctype, cdata in chunks:
                if ctype == b"VP8 " and len(cdata) >= 10:
                    w = int.from_bytes(cdata[6:8], "little") & 0x3FFF
                    h = int.from_bytes(cdata[8:10], "little") & 0x3FFF
                    break
                if ctype == b"VP8L" and len(cdata) >= 5:
                    v = int.from_bytes(cdata[1:5], "little")
                    w = (v & 0x3FFF) + 1
                    h = ((v >> 14) & 0x3FFF) + 1
                    alpha = bool((v >> 28) & 1)
                    break
            if not w or not h:
                return False, "WebP sin dimensiones"
            flags = 0x08 | (0x04 if alpha else 0)
            vp8x = bytes([flags]) + b"\x00\x00\x00" + (w - 1).to_bytes(3, "little") + (h - 1).to_bytes(3, "little")
            chunks.insert(0, [b"VP8X", vp8x])
            vp8x_idx = 0
        else:
            cdata = bytearray(chunks[vp8x_idx][1])
            if len(cdata) >= 1:
                cdata[0] |= 0x08
            chunks[vp8x_idx][1] = bytes(cdata)
        chunks.insert(vp8x_idx + 1, [b"EXIF", tiff])
        out = bytearray(b"RIFF" + (0).to_bytes(4, "little") + b"WEBP")
        for ctype, cdata in chunks:
            out += ctype + len(cdata).to_bytes(4, "little") + cdata
            if len(cdata) & 1:
                out += b"\x00"
        out[4:8] = (len(out) - 8).to_bytes(4, "little")
        tmp = final + ".dlpy_exif_tmp"
        with open(tmp, "wb") as fh:
            fh.write(bytes(out))
        os.replace(tmp, final)
        return True, "ok"
    except Exception as e:
        dbg("exif webp puro fallo", f"{type(e).__name__}: {e}")
        return False, str(e)
def _bplist_tags_decode(raw):
    """[etiquetas] del bplist de com.apple.metadata:_kMDItemUserTags. None si no es un bplist que se
    entienda (entonces no se toca: nunca se destruye un valor que no se sabe leer). Solo se usan arrays
    de strings ASCII (0x5x) y UTF-16 (0x6x), que es lo que escribe Archivos."""
    try:
        if not raw or raw[:8] != b"bplist00" or len(raw) < 32:
            return None
        trailer = raw[-32:]
        off_size, ref_size = trailer[6], trailer[7]
        n_obj = int.from_bytes(trailer[8:16], "big")
        top = int.from_bytes(trailer[16:24], "big")
        off_tab = int.from_bytes(trailer[24:32], "big")
        if not off_size or not ref_size or n_obj <= 0 or off_tab + n_obj * off_size > len(raw) - 32:
            return None
        offsets = [int.from_bytes(raw[off_tab + i * off_size: off_tab + (i + 1) * off_size], "big")
                   for i in range(n_obj)]
        def read_len(off, info):
            if info != 0x0F:
                return info, 1
            m = raw[off + 1]
            n = 1 << (m & 0x0F)
            return int.from_bytes(raw[off + 2:off + 2 + n], "big"), 2 + n
        def read_obj(idx):
            if idx < 0 or idx >= n_obj:
                return None
            off = offsets[idx]
            if off < 0 or off >= len(raw):
                return None
            marker = raw[off]
            typ, info = marker >> 4, marker & 0x0F
            if typ == 0x0A:
                count, n = read_len(off, info)
                refs = [int.from_bytes(raw[off + n + k * ref_size: off + n + (k + 1) * ref_size], "big")
                        for k in range(count)]
                return [read_obj(r) for r in refs]
            if typ == 0x05:
                ln, n = read_len(off, info)
                return raw[off + n:off + n + ln].decode("ascii", "replace")
            if typ == 0x06:
                ln, n = read_len(off, info)
                return raw[off + n:off + n + ln * 2].decode("utf-16-be", "replace")
            if typ == 0x01:
                n = 1 << info
                return int.from_bytes(raw[off + 1:off + 1 + n], "big")
            return None
        out = read_obj(top)
        if not isinstance(out, list):
            return None
        return [str(x) for x in out if isinstance(x, str)]
    except Exception as _ign:
        ignore("bplist tags decode", _ign)
        return None
def _bplist_tags_encode(tags):
    """[etiquetas] -> bplist00 con un array de strings (lo que espera _kMDItemUserTags). ASCII si la
    etiqueta es ASCII; si no, UTF-16BE (la longitud se cuenta en unidades UTF-16)."""
    tags = [str(t) for t in tags]
    def len_prefix(base, ln):
        if ln < 15:
            return bytes([base | ln])
        if ln < 256:
            return bytes([base | 0x0F, 0x10, ln])
        if ln < 65536:
            return bytes([base | 0x0F, 0x11]) + ln.to_bytes(2, "big")
        return bytes([base | 0x0F, 0x12]) + ln.to_bytes(4, "big")
    ref_size = 1 if len(tags) + 1 <= 255 else 2
    refs = b"".join(i.to_bytes(ref_size, "big") for i in range(1, len(tags) + 1))
    objs = [len_prefix(0xA0, len(tags)) + refs]
    for t in tags:
        try:
            raw = t.encode("ascii")
            objs.append(len_prefix(0x50, len(t)) + raw)
        except UnicodeEncodeError:
            raw = t.encode("utf-16-be")
            objs.append(len_prefix(0x60, len(raw) // 2) + raw)
    body = bytearray(b"bplist00")
    offsets = []
    for o in objs:
        offsets.append(len(body))
        body += o
    off_tab = len(body)
    off_size = 1 if max(offsets + [off_tab]) < 256 else (2 if max(offsets + [off_tab]) < 65536 else 4)
    for o in offsets:
        body += o.to_bytes(off_size, "big")
    body += b"\x00" * 6 + bytes([off_size, ref_size]) + len(objs).to_bytes(8, "big")
    body += (0).to_bytes(8, "big") + off_tab.to_bytes(8, "big")
    return bytes(body)
def _xattr_cli_read(path, key):
    """Lee un xattr con la CLI `xattr` de a-Shell (respaldo si el Python no trae os.getxattr).
    Devuelve los bytes, b"" si el xattr aun no existe, o None si no se pudo leer (sin CLI)."""
    try:
        import subprocess
        r = run_tool(["xattr", "-p", "-x", key, path], capture_output=True, timeout=10)
        if r.returncode != 0:
            return b""
        return bytes.fromhex(r.stdout.decode("ascii", "ignore").strip())
    except Exception as _ign:
        ignore("xattr cli read", _ign)
        return None
def _xattr_cli_write(path, key, blob):
    """Escribe un xattr con la CLI `xattr` de a-Shell. True si quedo."""
    try:
        import subprocess
        r = run_tool(["xattr", "-w", "-x", key, blob.hex(), path], capture_output=True, timeout=10)
        return r.returncode == 0
    except Exception as _ign:
        ignore("xattr cli write", _ign)
        return False
def _tag_version(path):
    """2.0.8: etiqueta visible de la version en Archivos (Informacion > Etiquetas).
    El panel de Archivos NO muestra UserComment/Comment/©cmt (por eso la version no se veia aunque si
    estaba escrita), y en la foto el unico campo visible de creador es "Creador del contenido"
    (Software 305: en imagenes lleva el AUTOR original, nunca DLpy; el software original,
    si lo hay, se conserva en UserComment/Comment). La etiqueta SI se ve en el panel para CUALQUIER archivo (foto,
    video, audio, subtitulos): es el xattr com.apple.metadata:_kMDItemUserTags (bplist en Python puro).
    Se combina con las etiquetas que ya tenga el archivo (no las borra) y sustituye una etiqueta "DLpy X.Y"
    vieja por la actual. DLPY_VERSION_FILE_TAG=0 lo apaga. Nunca lanza: si a-Shell no deja escribir xattrs,
    el archivo se guarda igual y la etiqueta solo se omite. True si la etiqueta quedo puesta.
    2.0.8 + respaldo CLI: el Python de a-Shell puede no traer os.setxattr (o el sandbox lo puede
    bloquear); entonces se intenta la CLI `xattr` de a-Shell (mismo xattr, otro camino). La captura del
    MP4 muestra Etiquetas vacia: el xattr no quedo escrito, asi que el respaldo importa."""
    if not _flag_env("DLPY_VERSION_FILE_TAG", True):
        return False
    if not path or not os.path.isfile(path):
        return False
    tag = f"DLpy {VERSION}"
    try:
        key = "com.apple.metadata:_kMDItemUserTags"
        getxattr = getattr(os, "getxattr", None)
        if getxattr:
            try:
                raw = getxattr(path, key)
            except OSError:
                raw = b""
            can_read = True
        else:
            raw = _xattr_cli_read(path, key)
            can_read = raw is not None
        if not can_read:
            return False
        tags = _bplist_tags_decode(raw) if raw else []
        if tags is None:
            return False
        tags = [t for t in tags if not re.match(r"^DLpy \d", t.split("\n", 1)[0])]
        if tag not in [t.split("\n", 1)[0] for t in tags]:
            tags.append(tag)
        blob = _bplist_tags_encode(tags)
        setxattr = getattr(os, "setxattr", None)
        if setxattr:
            try:
                setxattr(path, key, blob)
                return True
            except Exception as _e1:
                dbg("etiqueta version (os.setxattr) fallo", f"{type(_e1).__name__}: {_e1}")
        if _xattr_cli_write(path, key, blob):
            return True
        return False
    except Exception as e:
        dbg("etiqueta version fallo", f"{type(e).__name__}: {e}")
        return False
def _tag_subs(subs, final):
    """2.0.8: etiqueta de version en los subtitulos guardados junto a `final` (<nombre>.<idioma>.<ext>).
    Ademas de la Etiqueta de Archivos, la version queda DENTRO del subtitulo cuando su sintaxis
    lo permite (NOTE en VTT, "; DLpy" en ASS/SSA, <!-- DLpy --> en TTML); SRT no tiene
    sintaxis de comentario: solo Etiquetas."""
    root = os.path.splitext(final)[0]
    for lang, fp in subs or []:
        try:
            ext = os.path.splitext(fp)[1] or ".vtt"
            dst = f"{root}.{lang}{ext}"
            if os.path.isfile(dst):
                _tag_version(dst)
                _embed_subtitle_version(dst)
        except Exception as _ign:
            ignore("etiqueta version subs", _ign)
def _embed_jpeg_exif_pure(final, title, artist, date, software=None, usercomment=None):
    """EXIF minimo (APP1) en un JPEG: ImageDescription, Artist, Copyright, DateTime, Software
    (= AUTOR original: es lo que Archivos de iOS muestra como "Creador del contenido";
    Artist/Copyright tambien llevan el autor) y UserComment (comentario original + DLpy +
    software original preservado, en ExifIFD). Devuelve (ok, motivo). Sin tocar los datos
    de imagen: solo inserta el segmento tras SOI y quita un APP1 EXIF viejo. Las entradas
    van ordenadas por tag (lo exige el TIFF). DLpy NUNCA va en Software en imagenes."""
    try:
        with open(final, "rb") as fh:
            data = fh.read()
        if not data.startswith(b"\xff\xd8"):
            return False, "no es JPEG"
        _orig_soft, _orig_cmt = "", ""
        out_parts = []
        pos = 2
        end = len(data)
        saw_sos = False
        while pos + 2 <= end:
            if data[pos] != 0xFF:
                out_parts.append(data[pos:])
                pos = end
                break
            marker = data[pos + 1]
            if marker == 0xDA:
                saw_sos = True
                out_parts.append(data[pos:])
                pos = end
                break
            if marker == 0xD9:
                out_parts.append(data[pos:])
                pos = end
                break
            if marker == 0x01 or 0xD0 <= marker <= 0xD7:
                out_parts.append(data[pos:pos + 2])
                pos += 2
                continue
            if pos + 4 > end:
                out_parts.append(data[pos:])
                pos = end
                break
            seg_len = (data[pos + 2] << 8) | data[pos + 3]
            seg_end = pos + 2 + seg_len
            if seg_end > end:
                out_parts.append(data[pos:])
                pos = end
                break
            seg = data[pos:seg_end]
            if marker == 0xE1 and len(seg) >= 10 and seg[4:10] == b"Exif\x00\x00":
                _parsed = _tiff_read_software_comment(seg[10:])
                if _parsed.get("software"):
                    _orig_soft = _parsed["software"]
                if _parsed.get("usercomment"):
                    _orig_cmt = _parsed["usercomment"]
                pos = seg_end
                continue
            out_parts.append(seg)
            pos = seg_end
        if pos < end:
            out_parts.append(data[pos:])
        if not saw_sos:
            return False, "JPEG sin datos de imagen"
        rest = b"".join(out_parts)
        _soft_final = _image_software_final(artist, _orig_soft or software)
        _cmt_final = _image_comment_final(_orig_cmt, _orig_soft or software, artist, usercomment)
        tiff = _build_tiff_exif(title, artist, date, _soft_final, _cmt_final)
        app1 = b"\xff\xe1" + (len(b"Exif\x00\x00") + len(tiff) + 2).to_bytes(2, "big") + b"Exif\x00\x00" + tiff
        new_data = data[:2] + app1 + rest
        tmp = final + ".dlpy_exif_tmp"
        with open(tmp, "wb") as fh:
            fh.write(new_data)
        os.replace(tmp, final)
        return True, "ok"
    except Exception as e:
        dbg("exif puro fallo", f"{type(e).__name__}: {e}")
        return False, str(e)
def _embed_png_text_pure(final, title, artist, desc, software=None, usercomment=None):
    """Texto (Title/Author/Description/Software/Comment) en un PNG: chunks iTXt UTF-8. Devuelve
    (ok, motivo). Software = AUTOR original (lo que Archivos muestra como Creador; el autor
    tambien va en Author); Comment = comentario original + DLpy + software original
    preservado. DLpy NUNCA va en Software en imagenes. Si el PNG trae chunk eXIf, su
    EXIF lleva el mismo Software/UserComment que el iTXt."""
    try:
        import zlib
        with open(final, "rb") as fh:
            data = fh.read()
        if not data.startswith(b"\x89PNG\r\n\x1a\n"):
            return False, "no es PNG"
        _orig_soft, _orig_cmt, _exif_idx = "", "", None
        pos = 8
        end = len(data)
        chunks = []
        saw_iend = False
        while pos + 8 <= end:
            length = int.from_bytes(data[pos:pos + 4], "big")
            ctype = data[pos + 4:pos + 8]
            if pos + 12 + length > end:
                return False, "PNG corrupto"
            cdata = data[pos + 8:pos + 8 + length]
            if ctype in (b"iTXt", b"tEXt", b"zTXt"):
                _k, _v = _png_text_decode(cdata, ctype)
                if _k in ("Software", "Comment"):
                    if _k == "Software":
                        _orig_soft = _v
                    else:
                        _orig_cmt = _v
                key = cdata.split(b"\x00", 1)[0] if cdata else b""
                if key in (b"Title", b"Author", b"Description", b"Software", b"Comment"):
                    pos += 12 + length
                    continue
            if ctype == b"eXIf":
                _parsed = _tiff_read_software_comment(cdata)
                if not _orig_soft and _parsed.get("software"):
                    _orig_soft = _parsed["software"]
                if not _orig_cmt and _parsed.get("usercomment"):
                    _orig_cmt = _parsed["usercomment"]
                _exif_idx = len(chunks)
            chunks.append((ctype, cdata))
            pos += 12 + length
            if ctype == b"IEND":
                saw_iend = True
                break
        if not saw_iend:
            return False, "PNG sin IEND"
        _soft_final = _image_software_final(artist, _orig_soft or software)
        _cmt_final = _image_comment_final(_orig_cmt, _orig_soft or software, artist, usercomment)
        if _exif_idx is not None:
            _tiff = _build_tiff_exif(title, artist, date, _soft_final, _cmt_final)
            chunks[_exif_idx] = (b"eXIf", _tiff)
        new_chunks = []
        for key, val in (("Title", title), ("Author", artist), ("Description", desc),
                         ("Software", _soft_final), ("Comment", _cmt_final)):
            if not val:
                continue
            payload = key.encode("ascii") + b"\x00" + b"\x00\x00" + b"\x00" + b"\x00" + str(val).encode("utf-8")
            new_chunks.append((b"iTXt", payload))
        out = bytearray(data[:8])
        inserted = False
        for ctype, cdata in chunks:
            out += len(cdata).to_bytes(4, "big") + ctype + cdata + (zlib.crc32(ctype + cdata) & 0xFFFFFFFF).to_bytes(4, "big")
            if ctype == b"IHDR" and not inserted:
                for ntype, ndata in new_chunks:
                    out += len(ndata).to_bytes(4, "big") + ntype + ndata + (zlib.crc32(ntype + ndata) & 0xFFFFFFFF).to_bytes(4, "big")
                inserted = True
        if not inserted:
            return False, "PNG sin IHDR"
        tmp = final + ".dlpy_exif_tmp"
        with open(tmp, "wb") as fh:
            fh.write(bytes(out))
        os.replace(tmp, final)
        return True, "ok"
    except Exception as e:
        dbg("png puro fallo", f"{type(e).__name__}: {e}")
        return False, str(e)
def _embed_gif_comment_pure(final, title, artist, date, software=None, usercomment=None):
    """Comment Extension en un GIF89a: "DLpy 2.0.8". Devuelve (ok, motivo).
    GIF no tiene campo Software (ExifTool mapea Software/Comment a Comment Extensions):
    la version va como una Comment Extension aparte, SIN tocar los comentarios ni las
    Application Extensions originales (NETSCAPE de bucle, Adobe...). Si el archivo ya
    trae una Comment Extension con "DLpy", se sustituye sin duplicar. No toca ni un
    byte de imagen: solo inserta la extension antes del trailer (0x3B).
    """
    try:
        with open(final, "rb") as fh:
            data = fh.read()
        if len(data) < 13 or data[:6] not in (b"GIF87a", b"GIF89a"):
            return False, "no es GIF"
        packed = data[10]
        pos = 13 + (3 * (1 << ((packed & 0x07) + 1)) if packed & 0x80 else 0)
        dlpy_ranges = []
        trailer = None
        while pos < len(data):
            b = data[pos]
            if b == 0x3B:
                trailer = pos
                break
            if b == 0x21:
                if pos + 1 >= len(data):
                    return False, "GIF corrupto"
                label = data[pos + 1]
                if label == 0xFE:
                    q = pos + 2
                    txt = bytearray()
                    while q < len(data) and data[q] != 0:
                        sz = data[q]
                        if q + 1 + sz > len(data):
                            return False, "GIF corrupto"
                        txt += data[q + 1:q + 1 + sz]
                        q += 1 + sz
                    q += 1
                    if b"DLpy " in bytes(txt):
                        dlpy_ranges.append((pos, q))
                    pos = q
                    continue
                if label == 0xFF:
                    if pos + 2 >= len(data):
                        return False, "GIF corrupto"
                    q = pos + 2 + 1 + int(data[pos + 2])
                    while q < len(data) and data[q] != 0:
                        q += 1 + int(data[q])
                    pos = q + 1
                    continue
                if label == 0xF9:
                    pos += 8
                    continue
                if label == 0x01:
                    if pos + 2 >= len(data):
                        return False, "GIF corrupto"
                    q = pos + 2 + 1 + int(data[pos + 2])
                    while q < len(data) and data[q] != 0:
                        q += 1 + int(data[q])
                    pos = q + 1
                    continue
                return False, "extension GIF desconocida"
            if b == 0x2C:
                if pos + 10 > len(data):
                    return False, "GIF corrupto"
                ipack = data[pos + 9]
                pos += 10 + (3 * (1 << ((ipack & 0x07) + 1)) if ipack & 0x80 else 0)
                if pos >= len(data):
                    return False, "GIF corrupto"
                pos += 1
                while pos < len(data) and data[pos] != 0:
                    pos += 1 + int(data[pos])
                pos += 1
                continue
            return False, "GIF corrupto"
        if trailer is None:
            return False, "GIF sin trailer"
        _orig_trailer = trailer
        out = bytearray()
        last = 0
        for s, e in sorted(dlpy_ranges):
            out += data[last:s]
            last = e
        out += data[last:_orig_trailer]
        trailer = _orig_trailer
        comment = _merge_comment(usercomment or "") if False else f"DLpy {VERSION}"
        raw = comment.encode("utf-8")
        ext = bytearray(b"\x21\xfe")
        for i in range(0, len(raw), 255):
            chunk = raw[i:i + 255]
            ext += bytes([len(chunk)]) + chunk
        ext += b"\x00"
        out += ext + data[trailer:]
        tmp = final + ".dlpy_exif_tmp"
        with open(tmp, "wb") as fh:
            fh.write(bytes(out))
        os.replace(tmp, final)
        return True, "ok"
    except Exception as e:
        dbg("gif puro fallo", f"{type(e).__name__}: {e}")
        return False, str(e)
def _embed_tiff_pure(final, title, artist, date, software=None, usercomment=None):
    """Software/UserComment in-place en un TIFF. Devuelve (ok, motivo).
    TIFF no tiene "hueco" para anadir entradas sin mover los datos de imagen (los
    offsets de strips / XMP / ExifIFD se romperian), asi que solo se sobrescribe
    EN EL SITIO si el valor nuevo cabe en el espacio ya asignado a Software (305,
    IFD0) o UserComment (37510, ExifIFD): se rellena con NUL y el count se deja
    tal cual (el lector corta en el primer NUL). Si no cabe o la entrada no existe,
    NO se reescribe el archivo: la version queda en Etiquetas. Nunca se pierde el
    TIFF por unas etiquetas.
    """
    try:
        with open(final, "rb") as fh:
            data = bytearray(fh.read())
        if len(data) < 8 or data[:2] not in (b"II", b"MM"):
            return False, "no es TIFF"
        bo = "little" if data[:2] == b"II" else "big"
        if int.from_bytes(data[2:4], bo) != 42:
            return False, "no es TIFF"
        _sizes = {1: 1, 2: 1, 3: 2, 4: 4, 5: 8, 6: 1, 7: 1, 8: 2, 9: 4, 10: 8, 11: 4, 12: 8}
        def _ifd_entries(off):
            if off <= 0 or off + 2 > len(data):
                return None, None
            n = int.from_bytes(data[off:off + 2], bo)
            if off + 2 + n * 12 > len(data):
                return None, None
            entries = {}
            exif_off = None
            for i in range(n):
                s = off + 2 + i * 12
                tag = int.from_bytes(data[s:s + 2], bo)
                typ = int.from_bytes(data[s + 2:s + 4], bo)
                cnt = int.from_bytes(data[s + 4:s + 8], bo)
                entries[tag] = (s, typ, cnt)
                if tag == 34665 and typ == 4 and cnt == 1:
                    exif_off = int.from_bytes(data[s + 8:s + 12], bo)
            return entries, exif_off
        def _write_in_place(entries, tag, new_bytes):
            """True si el valor nuevo cupo y se escribio en el sitio."""
            if tag not in entries:
                return False
            s, typ, cnt = entries[tag]
            if typ not in _sizes:
                return False
            if len(new_bytes) > cnt * _sizes[typ]:
                return False
            total = cnt * _sizes[typ]
            if total <= 4:
                data[s + 8:s + 8 + total] = new_bytes.ljust(total, b"\x00")
            else:
                doff = int.from_bytes(data[s + 8:s + 12], bo)
                if doff < 0 or doff + total > len(data):
                    return False
                data[doff:doff + total] = new_bytes.ljust(total, b"\x00")
            return True
        entries0, exif_off = _ifd_entries(int.from_bytes(data[4:8], bo))
        if entries0 is None:
            return False, "TIFF sin IFD0"
        changed = False
        if 305 in entries0:
            _cur = b""
            _s, _t, _c = entries0[305]
            _tot = _c * _sizes.get(_t, 1)
            if _tot <= 4:
                _cur = bytes(data[_s + 8:_s + 8 + _tot])
            else:
                _do = int.from_bytes(data[_s + 8:_s + 12], bo)
                _cur = bytes(data[_do:_do + _tot])
            _orig = _cur.decode("utf-8", "replace").rstrip("\x00").strip()
            _new = (_image_software_final(artist, _orig or software) + "\x00").encode("utf-8")
            if _write_in_place(entries0, 305, _new):
                changed = True
        if exif_off:
            entries_e, _ = _ifd_entries(exif_off)
            if entries_e and 37510 in entries_e:
                _s, _t, _c = entries_e[37510]
                _tot = _c * _sizes.get(_t, 1)
                if _tot <= 4:
                    _cur = bytes(data[_s + 8:_s + 8 + _tot])
                else:
                    _do = int.from_bytes(data[_s + 8:_s + 12], bo)
                    _cur = bytes(data[_do:_do + _tot])
                _raw = bytes(_cur)
                if _raw.startswith(b"ASCII\x00\x00\x00"):
                    _raw = _raw[8:]
                _orig_c = _raw.decode("utf-8", "replace").rstrip("\x00").strip()
                _new_c = (b"ASCII\x00\x00\x00" + _image_comment_final(_orig_c, _orig, artist, usercomment).encode("utf-8") + b"\x00")
                if _write_in_place(entries_e, 37510, _new_c):
                    changed = True
        if not changed:
            return False, "TIFF sin hueco para Software/Comment sin mover datos; version solo en Etiquetas"
        tmp = final + ".dlpy_exif_tmp"
        with open(tmp, "wb") as fh:
            fh.write(bytes(data))
        os.replace(tmp, final)
        return True, "ok"
    except Exception as e:
        dbg("tiff puro fallo", f"{type(e).__name__}: {e}")
        return False, str(e)
def _embed_svg_pure(final, title, artist, date, software=None, usercomment=None):
    """Comentario <!-- DLpy ... --> en un SVG (XML). Devuelve (ok, motivo).
    SVG es texto XML: no tiene campo EXIF. La version va como comentario XML, que
    los renderizadores ignoran. Si el SVG ya trae un comentario con el generador
    (Generator: Adobe Illustrator / Inkscape / Figma...), ese nombre se conserva
    como "Software original" dentro del comentario DLpy; los demas comentarios
    originales no se tocan. Si ya hay un <!-- DLpy ... -->, se sustituye.
    """
    try:
        with open(final, "rb") as fh:
            raw = fh.read()
        try:
            text = raw.decode("utf-8")
            enc = "utf-8"
        except UnicodeDecodeError:
            text = raw.decode("latin-1")
            enc = "latin-1"
        if "<svg" not in text.lower():
            return False, "no es SVG"
        orig = ""
        m = re.search(r"Generator:\s*([^\r\n<]+)", text)
        if m:
            orig = m.group(1).strip()
            orig = orig.split("-->")[0].strip()
        if not orig:
            m = re.search(r"<!--\s*[^>]*?(Adobe Illustrator|Adobe Photoshop|Inkscape|Figma|Canva|Sketch)[^>]*?-->",
                          text, flags=re.I)
            if m:
                orig = re.sub(r"\s+", " ", m.group(0).replace("<!--", "").replace("-->", "").strip())
        if orig:
            comment = f"<!-- DLpy {VERSION} (Software original: {orig}) -->"
        else:
            comment = f"<!-- DLpy {VERSION} -->"
        if re.search(r"<!--\s*DLpy \d", text):
            text = re.sub(r"<!--\s*DLpy \d[^>]*?-->", comment, text, count=1)
        else:
            m = re.search(r"<\?xml[^?]*\?>\s*", text)
            if m:
                pos = m.end()
                text = text[:pos] + comment + "\n" + text[pos:]
            else:
                m = re.search(r"<!DOCTYPE[^>]*>\s*", text)
                if m:
                    pos = m.end()
                    text = text[:pos] + comment + "\n" + text[pos:]
                else:
                    text = comment + "\n" + text
        tmp = final + ".dlpy_exif_tmp"
        with open(tmp, "wb") as fh:
            fh.write(text.encode(enc))
        os.replace(tmp, final)
        return True, "ok"
    except Exception as e:
        dbg("svg puro fallo", f"{type(e).__name__}: {e}")
        return False, str(e)
def _embed_heif_via_ffmpeg(final, title, artist, desc, version=None):
    """Version en AVIF/HEIC/HEIF con ffmpeg -c copy (sin re-codificar). (ok, motivo).
    AVIF/HEIC son ISOBMFF: su EXIF vive como item en el `meta` box y reescribirlo
    a mano exige recolocar todos los iloc (un error corrompe la foto del iPhone),
    asi que en a-Shell (sin libheif ni Pillow) no se toca el contenedor a mano.
    Si ffmpeg sabe muxar el formato, -c copy escribe comment (la version + software
    original preservado) sin tocar los pixeles (encoder lo pisa ffmpeg con Lavf, como
    en MKV/WAV; se le pasa el autor como encoder para que, si algun muxer lo respeta,
    el Creador sea el autor, no DLpy); si no lo sabe (HEIC sin libheif), no se toca
    el archivo y la version queda en Etiquetas.
    """
    try:
        if not tool_executable("ffmpeg"):
            return False, "sin ffmpeg; version solo en Etiquetas"
        tags = _ffprobe_tags(final)
        _enc = _image_software_final(artist, tags.get("encoder") or "")
        _cmt = _image_comment_final(tags.get("comment") or "", tags.get("encoder") or "", artist, "")
        ok = _ffmpeg_copy_with_tags(final, {
            "title": title or "", "artist": artist or "", "comment": _cmt,
            "encoder": _enc, "description": desc or "",
        })
        return (True, "ok") if ok else (False, "ffmpeg no pudo muxar AVIF/HEIC; version solo en Etiquetas")
    except Exception as e:
        return False, str(e)
def _embed_subtitle_version(path):
    """Version DLpy DENTRO del subtitulo, segun su sintaxis. True si quedo.
    VTT: "NOTE DLpy 2.0.8" tras la linea WEBVTT (NOTE es comentario oficial VTT).
    ASS/SSA: "; DLpy 2.0.8" en [Script Info] (; es comentario ASS). TTML/DFXP:
    <!-- DLpy ... --> (XML). SRT/SBV/TXT no tienen sintaxis de comentario: solo
    Etiquetas (un bloque extra romperia los tiempos). Los comentarios originales
    no se tocan; un NOTE/; DLpy viejo se sustituye.
    """
    try:
        if not path or not os.path.isfile(path):
            return False
        ext = os.path.splitext(path)[1].lower()
        if ext not in (".vtt", ".ass", ".ssa", ".ttml", ".dfxp"):
            return False
        with open(path, "rb") as fh:
            raw = fh.read()
        text = raw.decode("utf-8", "surrogateescape")
        tag = f"DLpy {VERSION}"
        if ext == ".vtt":
            lines = text.splitlines()
            if not lines or not lines[0].startswith("WEBVTT"):
                return False
            out = [lines[0]]
            done = False
            for ln in lines[1:]:
                if re.match(r"^NOTE\s+DLpy \d", ln):
                    if not done:
                        out.append(f"NOTE {tag}")
                        done = True
                    continue
                out.append(ln)
            if not done:
                out.insert(1, "")
                out.insert(2, f"NOTE {tag}")
            text = "\n".join(out) + ("\n" if text.endswith("\n") else "")
        elif ext in (".ass", ".ssa"):
            if re.search(r"^;\s*DLpy \d", text, flags=re.M):
                text = re.sub(r"^;\s*DLpy \d[^\r\n]*", f"; {tag}", text, count=1, flags=re.M)
            else:
                m = re.search(r"(?m)^\[Script Info\]\s*$", text)
                if m:
                    text = text[:m.end()] + f"\n; {tag}" + text[m.end():]
                else:
                    text = f"; {tag}\n" + text
        else:
            comment = f"<!-- {tag} -->"
            if re.search(r"<!--\s*DLpy \d", text):
                text = re.sub(r"<!--\s*DLpy \d[^>]*?-->", comment, text, count=1)
            else:
                m = re.search(r"<\?xml[^?]*\?>\s*", text)
                if m:
                    text = text[:m.end()] + comment + "\n" + text[m.end():]
                else:
                    text = comment + "\n" + text
        tmp = path + ".dlpy_sub_tmp"
        with open(tmp, "wb") as fh:
            fh.write(text.encode("utf-8", "surrogateescape"))
        os.replace(tmp, path)
        return True
    except Exception as e:
        dbg("subtitulo version fallo", f"{type(e).__name__}: {e}")
        return False
def _author_from_url(url):
    """2.0.8 + autor: @handle de una URL de Threads (threads.net/@handle/post/... o
    threads.com/@handle/post/...). "" si no trae @handle (p. ej. /t/ sin @). Se usa como ultimo
    respaldo en _embed_image_meta: sin uploader ni titulo con autor, el @handle de la URL es
    el autor, no DLpy (que es el programa, Software)."""
    try:
        m = re.search(r"threads\.(?:net|com)/@([^/\s?#]+)", str(url or ""))
        return ("@" + m.group(1)) if m else ""
    except Exception:
        return ""
def _embed_image_meta(final, info, title_hint=None, url_hint=None):
    """2.0.8 + metadatos en fotos: titulo, autor y fecha del post, por extension (iOS).
    La foto nunca pasaba por embed_tags (solo audio/video), asi que salia sin metadatos.
    Devuelve (ok, motivo). Todo en Python puro (Pillow eliminado, opcion A: en a-Shell no se instala, y el
    camino puro ya cubre los tres formatos sin re-codificar la imagen). El archivo nunca se pierde
    por unas etiquetas.
    Por extension: JPEG/WebP = EXIF (Software 305 = AUTOR original, UserComment 37510 =
    comentario original + DLpy + software original preservado); PNG = iTXt Software (= autor) /
    Comment (+ software original) + eXIf con lo mismo; GIF = Comment Extension con la version
    (sin campo Software); TIFF = Software (= autor) / UserComment in-place si caben, si no
    solo Etiquetas; SVG = <!-- DLpy ... --> (XML); AVIF/HEIC/HEIF = ffmpeg -c copy
    (comment con version + software original) si ffmpeg lo soporta, si no solo Etiquetas
    (el `meta` box ISOBMFF no se toca a mano: recolocar iloc corromperia la foto);
    BMP = sin contenedor, solo Etiquetas. En IMAGENES, Software SI es el autor: es el
    unico renglon de creador que Archivos muestra, y DLpy nunca va ahi.
    title_hint/url_hint (titulo y enlace del run): ultimo respaldo del autor si la info viene vacia
    (el titulo del run es el mismo del nombre del archivo: "Alice Chen (@sky5267) on Threads · 2 de 3 · ...").
    CREADOR = AUTOR EN IMAGENES (no DLpy en Software): Archivos de iOS muestra el EXIF Software (305)
    como "Creador del contenido", no Artist (315). Por spec Software es el programa, y en Apple
    "Creador del contenido" (kMDItemCreator) es la aplicacion, no la persona; el campo de la
    persona es IPTC Creator / XMP dc:creator / EXIF Artist, que Archivos NO muestra. Pero como
    Software es el UNICO renglon de creador que Archivos muestra en fotos, aqui Software =
    autor original puro (p. ej. "有傑克 (@_yujak)"), y tambien Artist/Copyright = autor. La
    regla anterior ("software original + DLpy") rompia esto: las fotos de Threads llegan
    sin Software, asi que caia a "DLpy 2.0.8" solo y la captura mostraba "Creador del
    contenido: DLpy 2.0.8" tapando al autor. La version DLpy va en UserComment (EXIF 37510,
    JPEG/WebP) y Comment (PNG): "comentario original · DLpy 2.0.8 (Software original: ...)"
    si habia software original que preservar. En VIDEO/AUDIO la regla es distinta (ver
    embed_tags): ahi Archivos si muestra autor y "Software de codificacion" en filas
    separadas, asi que ©too/TENC/ENCODER = codificador original + DLpy. (Y la version
    VISIBLE en Archivos es la etiqueta: _tag_version, en _m_store.)"""
    if not final or not os.path.isfile(final):
        return False, "sin archivo"
    info = info or {}
    version = f"DLpy {VERSION}"
    title = str(info.get("track") or info.get("title") or "")
    artist = str(info.get("artist") or info.get("creator") or info.get("uploader") or info.get("channel")
                   or info.get("author") or "")
    if not artist:
        _mt = re.match(r"^(.*?)\s+on Threads\b", title)
        if _mt and _mt.group(1).strip():
            artist = _mt.group(1).strip()
    if not artist:
        artist = _author_from_url(info.get("webpage_url") or info.get("original_url") or "")
    if not artist and title_hint:
        _mt = re.match(r"^(.*?)\s+on Threads\b", str(title_hint))
        if _mt and _mt.group(1).strip():
            artist = _mt.group(1).strip()
    if not artist and url_hint:
        artist = _author_from_url(url_hint)
    desc = str(info.get("description") or title or "")
    date = str(info.get("release_date") or info.get("upload_date") or "")
    if len(date) >= 8 and date[:8].isdigit():
        date = f"{date[:4]}:{date[4:6]}:{date[6:]} 00:00:00"
    ext = os.path.splitext(final)[1].lower()
    if ext in (".jpg", ".jpeg"):
        return _embed_jpeg_exif_pure(final, title, artist, date, None, version)
    if ext == ".png":
        return _embed_png_text_pure(final, title, artist, desc, None, version)
    if ext == ".webp":
        return _embed_webp_exif_pure(final, title, artist, date, None, version)
    if ext == ".gif":
        return _embed_gif_comment_pure(final, title, artist, date, None, version)
    if ext in (".tif", ".tiff"):
        return _embed_tiff_pure(final, title, artist, date, None, version)
    if ext == ".svg":
        return _embed_svg_pure(final, title, artist, date, None, version)
    if ext in (".avif", ".heic", ".heif"):
        return _embed_heif_via_ffmpeg(final, title, artist, desc, version)
    if ext == ".bmp":
        return False, "BMP sin contenedor de metadatos; la version queda en Etiquetas (Informacion > Etiquetas) en _m_store"
    return False, "formato sin EXIF"
def _tag_first(obj, key):
    """Primer valor (texto) de una clave de mutagen; \"\" si no existe o falla."""
    try:
        return str((obj.get(key) or [""])[0] or "")
    except Exception:
        return ""
def _tag_core(info):
    """(titulo, artista, extra) de un info de yt-dlp: una sola fuente para mutagen y ffmpeg."""
    info = info or {}
    title = str(info.get("track") or info.get("title") or "")
    artist = str(info.get("artist") or info.get("creator") or info.get("uploader") or info.get("channel") or "")
    return title, artist, _tag_extra(info)
def _write_mutagen_tags(final, ext, title, artist, extra, cover):
    """2.0.8: escribe las etiquetas con mutagen con una tabla por familia (MP3 / MP4 / Vorbis) en vez de un if por campo.
    Solo escribe lo que hay (nunca borra); el software y el comentario originales se conservan y DLpy va como dato extra."""
    if ext == ".mp3":
        from mutagen import id3
        try:
            tags = id3.ID3(final)
        except id3.ID3NoHeaderError:
            tags = id3.ID3()
        for frame, val in (("TIT2", title), ("TPE1", artist), ("TALB", extra["album"]), ("TDRC", extra["date"]),
                           ("TCON", extra["genre"]), ("TRCK", extra["track"])):
            if val:
                tags.setall(frame, [getattr(id3, frame)(encoding=3, text=val)])
        if extra["lyrics"]:
            tags.setall("USLT", [id3.USLT(encoding=3, lang="und", desc="", text=extra["lyrics"])])
        old_tenc = tags.get("TENC")
        tags.setall("TENC", [id3.TENC(encoding=3, text=_merge_software(str((old_tenc.text or [""])[0]) if old_tenc is not None else ""))])
        old_comm = tags.getall("COMM")
        tags.setall("COMM", [id3.COMM(encoding=3, lang="und", desc="", text=_merge_comment(str((old_comm[0].text or [""])[0]) if old_comm else ""))])
        if cover:
            tags.setall("APIC", [id3.APIC(encoding=3, mime="image/" + cover[1], type=3, desc="Cover", data=cover[0])])
        tags.save(final)
    elif ext in (".m4a", ".mp4", ".m4v", ".mov"):
        from mutagen.mp4 import MP4, MP4Cover
        mp = MP4(final)
        for key, val in (("\xa9nam", title), ("\xa9ART", artist), ("\xa9alb", extra["album"]), ("\xa9day", extra["date"]),
                         ("\xa9gen", extra["genre"]), ("\xa9lyr", extra["lyrics"])):
            if val:
                mp[key] = [val]
        if extra["track"]:
            with quiet("tags trkn", ValueError):
                mp["trkn"] = [(int(extra["track"]), 0)]
        mp["\xa9cmt"] = [_merge_comment(_tag_first(mp, "\xa9cmt"))]
        mp["\xa9too"] = [_merge_software(_tag_first(mp, "\xa9too"))]
        if cover:
            mp["covr"] = [MP4Cover(cover[0], MP4Cover.FORMAT_PNG if cover[1] == "png" else MP4Cover.FORMAT_JPEG)]
        mp.save()
    else:
        from mutagen.flac import Picture
        if ext == ".flac":
            from mutagen.flac import FLAC
            au = FLAC(final)
        elif ext == ".opus":
            from mutagen.oggopus import OggOpus
            au = OggOpus(final)
        else:
            from mutagen.oggvorbis import OggVorbis
            au = OggVorbis(final)
        for key, val in (("title", title), ("artist", artist), ("album", extra["album"]), ("date", extra["date"]),
                         ("genre", extra["genre"]), ("tracknumber", extra["track"]), ("lyrics", extra["lyrics"])):
            if val:
                au[key] = [val]
        au["encoder"] = [_merge_software(_tag_first(au, "encoder"))]
        au["comment"] = [_merge_comment(_tag_first(au, "comment"))]
        if cover:
            pic = Picture()
            pic.type, pic.mime, pic.desc, pic.data = 3, "image/" + cover[1], "Cover", cover[0]
            if ext == ".flac":
                au.clear_pictures()
                au.add_picture(pic)
            else:
                import base64
                au["metadata_block_picture"] = [base64.b64encode(pic.write()).decode("ascii")]
        au.save()
def embed_tags(final, info, work_dir):
    """2.0.7: título, artista y carátula con mutagen en m4a/mp4/m4v/mov/mp3. 2.0.8: + opus/flac/ogg y album, fecha, género, pista y letra; + versión con la que se bajó (©cmt en MP4/MOV, TENC en MP3, ENCODER en FLAC/Opus/Ogg) y en "Software de codificación" (©too en MP4/MOV, la fila que Archivos SÍ muestra). Solo si DLPY_METADATA_TAGS=1 y mutagen está instalado. True si escribió algo.
    2.0.8 + resto de formatos: MKV/WEBM/MKA/WAV/AIFF/AIF con ffmpeg -c copy (sin re-codificar):
    comment + titulo/artista/album/fecha/genero/pista/letra. En mutagen (MP4/MP3/FLAC/Opus/Ogg),
    el software/encoder y el comentario originales se conservan + DLpy como dato extra (nunca se
    pisan): ©too = "Lavf... (DLpy 2.0.8)", TENC/ENCODER igual, ©cmt/comment = "comentario
    original · DLpy 2.0.8". En ffmpeg -c copy, ffmpeg pisa `encoder` con su propio Lavf
    (no se puede forzar con -metadata): la version queda en `comment` ("comentario original
    · DLpy 2.0.8") y el encoder queda el Lavf original. AAC ADTS (.aac) no tiene contenedor:
    solo Etiquetas.
    Cualquier fallo se anota y se ignora: el archivo descargado nunca se pierde por unas etiquetas."""
    if not _flag_env("DLPY_METADATA_TAGS", True) or not final or not os.path.isfile(final):
        return False
    ext = os.path.splitext(final)[1].lower()
    if ext in (".mkv", ".webm", ".mka", ".wav", ".aiff", ".aif"):
        try:
            _title, _artist, _ex = _tag_core(info)
            _tags = _ffprobe_tags(final)
            _ok = _ffmpeg_copy_with_tags(final, {
                "title": _title, "artist": _artist, "album": _ex["album"], "date": _ex["date"],
                "genre": _ex["genre"], "tracknumber": _ex["track"], "lyrics": _ex["lyrics"],
                "comment": _merge_comment(_tags.get("comment") or ""),
                "encoder": _merge_software(_tags.get("encoder") or ""),
            })
            return bool(_ok)
        except Exception as e:
            dbg("etiquetas ffmpeg fallaron", f"{type(e).__name__}: {e}")
            return False
    if ext == ".aac":
        return False
    if not is_installed("mutagen"):
        return False
    if ext not in (".m4a", ".mp4", ".m4v", ".mov", ".mp3", ".opus", ".flac", ".ogg", ".oga"):
        return False
    title, artist, extra = _tag_core(info)
    cover = None
    with quiet("embed_tags", Exception):
        thumbs = sorted(glob.glob(os.path.join(work_dir, "*.jpg")) + glob.glob(os.path.join(work_dir, "*.jpeg")) +
                        glob.glob(os.path.join(work_dir, "*.png")) + glob.glob(os.path.join(work_dir, "*.webp")) +
                        glob.glob(os.path.join(work_dir, "*.avif")))
        if thumbs:
            cover = _cover_bytes(thumbs[0])
    try:
        _write_mutagen_tags(final, ext, title, artist, extra, cover)
        dbg("etiquetas mutagen", {"archivo": os.path.basename(final), "titulo": bool(title), "artista": bool(artist), "caratula": bool(cover),
                                  "album": bool(extra["album"]), "fecha": bool(extra["date"]), "genero": bool(extra["genre"]),
                                  "pista": bool(extra["track"]), "letra": bool(extra["lyrics"]), "version": True})
        return True
    except Exception as e:
        dbg("etiquetas mutagen fallaron", f"{type(e).__name__}: {e}")
        return False
def _ytdlp_options(run):
    """Opciones de yt-dlp para la descarga (con DLPY_DEBUG: yt-dlp tal cual, verbose y progreso nativo)."""
    ui = run.ui
    opts = {
        **run.base_opts,
        "ignoreerrors": False,
        "quiet": True,
        "no_warnings": True,
        "noplaylist": True,
        "format": run.fmt_id,
        "outtmpl": os.path.join(run.work_dir.replace("%", "%%"), run.base.replace("%", "%%") + ".%(ext)s"),
        "continuedl": True,
        "overwrites": False,
        "noprogress": True,
        "consoletitle": False,
        "progress_hooks": [ui.hook],
        "postprocessor_hooks": [ui.pp_hook],
        "logger": _QuietLog(),
    }
    if run.merge_ext:
        opts["merge_output_format"] = run.merge_ext
        opts["allow_multiple_audio_streams"] = True
    if not user_set_fragments():
        opts["concurrent_fragment_downloads"] = fragments_n()
    if _is_youtube(getattr(run, "info", None)):
        _ck = cookies_path()
        if _ck:
            opts["cookiefile"] = _ck
        _ea = youtube_extractor_args()
        if _ea:
            opts["extractor_args"] = _ea
    if _flag_env("DLPY_EMBED_CHAPTERS", True):
        opts["embedchapters"] = True
    _sp = sponsor_categories()
    if _sp:
        opts["sponsorblock_remove"] = list(_sp)
        opts["sponsorblock_mark"] = []
    if _flag_env("DLPY_EMBED_THUMBNAIL", False):
        opts["writethumbnail"] = True
        opts["embedthumbnail"] = True
    _sl = subs_langs_effective(getattr(run, "info", None))
    if _sl:
        opts.update({"writesubtitles": True, "writeautomaticsub": False, "subtitleslangs": _sl,
                     "subtitlesformat": "srt/vtt/best"})
        if _flag_env("DLPY_EMBED_SUBTITLES", False):
            opts["embedsubtitles"] = True
    if _flag_env("DLPY_METADATA_TAGS", True) and is_installed("mutagen"):
        opts["writethumbnail"] = True
    if DEBUG:
        opts.update({"quiet": False, "no_warnings": False, "verbose": True,
                     "noprogress": False})
        opts.pop("logger", None)
        dbg("opciones yt-dlp", {k: v for k, v in opts.items()
                                if k not in ("progress_hooks", "postprocessor_hooks")})
    return opts
def _m_workspace(run):
    """[M5] 5) Nombre de archivo, carpeta de trabajo (reanudable), caché de streams, panel y opciones de yt-dlp."""
    base = safe_name(run.title)
    format_specs, resume_specs = _stream_specs(run.fmt, run.fmt_id, run.formats)
    work_dir, base, resumed, discarded = prepare_resume_dir(resume_key(run.key, resume_specs), base)
    dbg("nombre / trabajo", {"base": base, "work_dir": work_dir, "specs": format_specs,
                             "reanudado": resumed})
    reused = seed_work_from_cache(work_dir, base, run.key, format_specs)
    remember_resume(work_dir, run)
    run.start_bytes = resume_data_bytes(work_dir)
    dbg("caché de streams", {"reutilizados": reused})
    if reused:
        m_info(f"Caché de streams: {reused} archivo(s) reutilizado(s) (< 24 h)")
    STREAM_KINDS.clear()
    for _f in (run.formats or []):
        _k = ux_format_kinds(_f)
        if _k:
            STREAM_KINDS[str(_f.get("format_id"))] = _k
    ui = DownloadUI(vkey=run.key, resumed=bool(resumed))
    ui.total = len(format_specs)
    run.ui, run.base, run.work_dir, run.resumed, run.discarded = ui, base, work_dir, resumed, discarded
    run.opts = _ytdlp_options(run)
    return None
def _photo_file_base(base, ext):
    """2.0.8 + carrusel: base del nombre de una foto, sin duplicar la extension."""
    try:
        return re.sub(r"\s*·\s*" + re.escape(str(ext or "")) + r"\s*$", "", str(base or ""), flags=re.I)
    except Exception:
        return str(base or "")
def idmm_ux_carousel_stream(run, kind):
    """2.0.8 + carrusel: la tarjeta de la escena varia por archivo (como la multi-audio).
    La escena se queda viva (no se reinicia entre archivos), pero su tarjeta/fila pasa a este
    archivo: "Descargando foto 2/4" / "Descargando video 1/4", con su proporcion y sus datos.
    Sin esto, la escena repetia la tarjeta del primer archivo (video) para todos los demas,
    porque las bajadas directas IDMM solo ponian la etiqueta con ux_status, sin actualizar
    stream_total/stream_seen/skind. Es el equivalente a ux_download_stream (hook de yt-dlp) para
    las bajadas directas IDMM, que no tienen hook. Solo para los caminos directos IDMM
    (foto y video nativo); las de yt-dlp ya las actualiza su hook."""
    try:
        if not ux_on():
            return
        _ci = getattr(run, "carousel_choice", None) or {}
        _ct = len(getattr(run, "carousel_items", None) or []) or 1
        _idx = int(_ci.get("index") or 1)
        _idx = min(max(1, _idx), _ct)
        scene_shape(getattr(run, "info", None))
        scene_stream(kind, _idx, _ct)
        try:
            _items = getattr(run, "carousel_items", None) or []
            if _items:
                _sk = _scene_bag("skind")
                for _it in _items:
                    _n = int((_it or {}).get("index") or 0)
                    _k = str((_it or {}).get("kind") or "").lower()
                    if 1 <= _n <= _ct and _k in ("video", "audio", "foto") and _n not in _sk:
                        _sk[_n] = _k
        except Exception:
            pass
    except Exception as _ign:
        ignore("escena carrusel stream", _ign)
def idmm_ux_stream_done(run, kind):
    """la bajada directa IDMM terminó: la tarjeta pasa a hecha AHORA, no cuando acabe
    verificar / metadatos / convertir. Antes nunca se marcaba done: la animación de descarga
    se quedaba en "activa" mientras el script ya hacía otra cosa. Es el equivalente a
    ux_download_stream_done para las bajadas directas, que no tienen hook de yt-dlp."""
    try:
        if not ux_on():
            return
        _k = str(kind or "").lower()
        if _k not in ("video", "audio", "foto"):
            return
        SCENE["speed_last"] = SCENE.get("speed")
        SCENE["speed"] = None
        SCENE["speed_end"] = time.time()
        SCENE["busy"] = False
        scene_progress(100.0)
        scene_stream_done(_k)
    except Exception as _ign:
        ignore("escena carrusel stream done", _ign)
def _idmm_expired_url(e):
    """True si el error es URL del CDN caducada (403/410/expirado/forbidden). Un 403 del CDN NO es login: la info en cache trae URLs
    que caducan mientras bajan las fotos anteriores; la siguiente da 403 y antes se reportaba como 'Ni yt-dlp ni DLpy pudieron leer'.
    El reintento con fetch fresco distingue: si tambien falla, entonces si es login/privado."""
    low = str(e or '').lower()
    return any(k in low for k in ('403', '410', 'expired', 'expir', 'forbidden', 'gone'))
def _idmm_refresh_media_url(run, kind):
    """re-fetch fresco (SIN cache) del mismo medio del carrusel, para URL caducada. Invalida los caches del carrusel de ese enlace
    (si no, analyze_link devolveria la misma URL caducada), re-analiza el enlace base y devuelve (url_nueva, ext) del mismo indice, o None.
    Solo se llama cuando el CDN dio 403/410; no es el reanalizar de antes (por cada medio), es una vez y solo cuando el CDN lo pide."""
    try:
        base = str(getattr(run, 'link', '') or '').split('#dlpy_carousel=')[0]
        try:
            _CAROUSEL_INFO_CACHE.pop(_carousel_cache_key(base), None)
        except Exception as _ign:
            diagnostic_report("A", f"refresco IDMM: vaciar caché carrusel: {type(_ign).__name__}: {_ign}")
            pass
        try:
            _IDMM_INFO_CACHE.pop(idmm_normalize_link(base), None)
        except Exception as _ign:
            diagnostic_report("A", f"refresco IDMM: vaciar caché IDMM: {type(_ign).__name__}: {_ign}")
            pass
        info, _ = analyze_link(run.yt_dlp, base)
        try:
            if info and (info.get('entries') or info.get('formats')):
                _CAROUSEL_INFO_CACHE[_carousel_cache_key(base)] = info
        except Exception as _ign:
            diagnostic_report("A", f"refresco IDMM: guardar info en caché: {type(_ign).__name__}: {_ign}")
            pass
        items = carousel_items_from_info(info)
        idx = int((getattr(run, 'carousel_choice', None) or {}).get('index') or getattr(run, 'carousel_index', 0) or 1)
        hit = next((it for it in items if int(it.get('index') or 0) == idx), None)
        if hit is None and items:
            hit = items[0]
        if hit is None:
            return None
        single = carousel_single_info(hit, info)
        for f in ((single or {}).get('formats') or []):
            if f.get('url'):
                return (f.get('url'), f.get('ext') or ('jpg' if str(kind or '').lower() == 'foto' else 'mp4'))
        return None
    except Exception:
        return None
def _idmm_proactive_refresh(run, kind):
    """PROACTIVO IDMM: si la URL del medio elegido declara caducidad `oe`/`ext` dentro del margen,
    pide la URL fresca de ESE medio (single-flight, via _idmm_refresh_media_url) y la devuelve como (url, ext).
    Sin caducidad declarada o fuera del margen: None (se baja con la URL que hay; el reactivo 403/410 cubre).
    Si la renovacion falla o agota la espera, None: se intenta con la URL previa, no se tumba la bajada."""
    try:
        fmt = getattr(run, "fmt", None) or {}
        url = fmt.get("url")
        if not isinstance(url, str) or not url:
            return None
        if not _cdn_needs_refresh_url(url):
            return None
        key = _cdn_refresh_key(getattr(run, "link", "") or "")
        try:
            fresh = _CDN_REFRESH_FLIGHT.run(key, lambda: _idmm_refresh_media_url(run, kind))
        except Exception as _ign:
            ignore("idmm_proactivo", _ign)
            return None
        if fresh is None:
            return None
        try:
            if isinstance(fresh, (list, tuple)) and len(fresh) >= 2 and isinstance(fresh[0], str) and fresh[0]:
                return (fresh[0], fresh[1])
        except Exception:
            pass
        return None
    except Exception:
        return None
def _m_download(run):
    """[M6] Descarga con yt-dlp (progreso, conversión y reanudación). Deja la ruta en run.final. 2.0.8: fallback por cliente YouTube + verificación con ffprobe."""
    ui, work_dir, plan, conv_state = run.ui, run.work_dir, run.plan, run.conv_state
    selected, merge_ext = run.selected, run.merge_ext
    if QUIET["on"]:
        quiet_set(False)
    try:
        if getattr(run, "spick", None) is not None:
            ux_site_theme_apply(run)
            if not getattr(run, "site_shown", False):
                ux_site_intro(run)
    except KeyboardInterrupt:
        raise
    except Exception as _ign:
        ignore("site_intro", _ign)
    try:
        if not ux_on():
            ux_start(run)
    except Exception as _ign:
        ignore("download_scene", _ign)
    clear_screen()
    hide_keyboard()
    settle_terminal()
    file_title(run.base)
    if run.resumed:
        m_ok(f"Reanudando: {human_size(run.resumed)} ya descargados")
    elif run.discarded:
        m_warn("Parcial descartado tras fallos repetidos; se empieza de cero.")
    ui.begin()
    final = None
    _fmt = getattr(run, "fmt", None) or {}
    if _fmt.get("_idmm_image") or getattr(run, "is_foto", False):
        _ext = str(_fmt.get("ext") or "jpg")
        _base = _photo_file_base(run.base, _ext)
        _orig_name = (_base or "threads_media") + "." + _ext
        _dest = idmm_unique_dest(work_dir, _orig_name)
        _ci = getattr(run, "carousel_choice", None) or {}
        _ct = len(getattr(run, "carousel_items", None) or []) or 1
        m_info(f"Bajando: {_orig_name}" + (f" (medio {_ci.get('index')} de {_ct})" if _ci.get("index") else ""))
        try:
            _fresh_foto = _idmm_proactive_refresh(run, "foto")
            if _fresh_foto:
                try:
                    _fmt["url"] = _fresh_foto[0]
                except Exception as _ign:
                    diagnostic_report("A", f"descarga foto: usar URL fresca: {type(_ign).__name__}: {_ign}")
                    pass
            idmm_ux_carousel_stream(run, "foto")
            _ok, _cd = idmm_download_media(_fmt.get("url"), _dest, cookies_path())
            idmm_ux_stream_done(run, "foto")
            if _cd:
                _cd_name = idmm_original_filename(_cd, run.base, _ext)
                _cdn_name = idmm_original_filename(_fmt.get("url"), run.base, _ext)
                if _cd_name != _cdn_name and _cd_name != os.path.basename(_dest):
                    _new = idmm_unique_dest(work_dir, _cd_name)
                    os.replace(_dest, _new)
                    _dest = _new
        except KeyboardInterrupt:
            ui.abort()
            m_err("Descarga cancelada.")
            return 1
        except Exception as e:
            _e = e
            if _idmm_expired_url(e):
                _fresh = _idmm_refresh_media_url(run, "foto")
                if _fresh:
                    try:
                        _ok, _cd = idmm_download_media(_fresh[0], _dest, cookies_path())
                        idmm_ux_stream_done(run, "foto")
                        if _cd:
                            _cd_name = idmm_original_filename(_cd, run.base, _ext)
                            _cdn_name = idmm_original_filename(_fresh[0], run.base, _ext)
                            if _cd_name != _cdn_name and _cd_name != os.path.basename(_dest):
                                _new = idmm_unique_dest(work_dir, _cd_name)
                                os.replace(_dest, _new)
                                _dest = _new
                    except Exception as e2:
                        _e = e2
                    else:
                        _e = None
            if _e is not None:
                ui.abort()
                if is_idmm_login_error(_e):
                    explain_threads_unsupported(getattr(run, "link", ""))
                else:
                    m_err(f"Error al descargar la foto: {_e}")
                return 1
        ui.finish()
        if not os.path.exists(_dest) or os.path.getsize(_dest) == 0:
            cleanup_work(work_dir)
            m_err("No se encontró la foto descargada.")
            return 1
        _mok, _mwhy = _embed_image_meta(_dest, getattr(run, "info", None),
                                      title_hint=getattr(run, "title", None), url_hint=getattr(run, "link", None))
        if not _mok:
            m_warn("Foto sin metadatos: " + str(_mwhy))
        if idmm_direct() and idmm_is_carousel(run):
            _conv = idmm_convert_photo(_dest)
            if _conv:
                _dest = _conv
                _mok2, _mwhy2 = _embed_image_meta(_dest, getattr(run, "info", None),
                                                  title_hint=getattr(run, "title", None), url_hint=getattr(run, "link", None))
                if not _mok2:
                    m_warn("Foto sin metadatos: " + str(_mwhy2))
            elif os.path.splitext(_dest)[1].lower().lstrip(".") in IDMM_PHOTO_CONVERT:
                m_warn("No se pudo convertir la foto a jpg: se guarda tal cual.")
        _ok, _why = verify_file(_dest, getattr(run, "info", None))
        if not _ok:
            m_err(t_display("Verificación falló") + f": {_why}")
            return 1
        run.subs = []
        run.final = _dest
        return None
    if _fmt.get("_idmm_native") and not _fmt.get("_idmm_image"):
        _ext = str(_fmt.get("ext") or "mp4")
        _orig_name = (run.base or "threads_media") + "." + _ext
        _dest = idmm_unique_dest(work_dir, _orig_name)
        _ci = getattr(run, "carousel_choice", None) or {}
        _ct = len(getattr(run, "carousel_items", None) or []) or 1
        m_info(f"Bajando: {_orig_name}" + (f" (medio {_ci.get('index')} de {_ct})" if _ci.get("index") else ""))
        try:
            _fresh_video = _idmm_proactive_refresh(run, "video")
            if _fresh_video:
                try:
                    _fmt["url"] = _fresh_video[0]
                except Exception as _ign:
                    diagnostic_report("A", f"descarga video: usar URL fresca: {type(_ign).__name__}: {_ign}")
                    pass
            idmm_ux_carousel_stream(run, "video")
            _ok, _cd = idmm_download_media(_fmt.get("url"), _dest, cookies_path())
            idmm_ux_stream_done(run, "video")
            if _cd:
                _cd_name = idmm_original_filename(_cd, run.base, _ext)
                _cdn_name = idmm_original_filename(_fmt.get("url"), run.base, _ext)
                if _cd_name != _cdn_name and _cd_name != os.path.basename(_dest):
                    _new = idmm_unique_dest(work_dir, _cd_name)
                    os.replace(_dest, _new)
                    _dest = _new
        except KeyboardInterrupt:
            ui.abort()
            m_err("Descarga cancelada.")
            return 1
        except Exception as e:
            _e = e
            if _idmm_expired_url(e):
                _fresh = _idmm_refresh_media_url(run, "video")
                if _fresh:
                    try:
                        _ok, _cd = idmm_download_media(_fresh[0], _dest, cookies_path())
                        idmm_ux_stream_done(run, "video")
                        if _cd:
                            _cd_name = idmm_original_filename(_cd, run.base, _ext)
                            _cdn_name = idmm_original_filename(_fresh[0], run.base, _ext)
                            if _cd_name != _cdn_name and _cd_name != os.path.basename(_dest):
                                _new = idmm_unique_dest(work_dir, _cd_name)
                                os.replace(_dest, _new)
                                _dest = _new
                    except Exception as e2:
                        _e = e2
                    else:
                        _e = None
            if _e is not None:
                ui.abort()
                if is_idmm_login_error(_e):
                    explain_threads_unsupported(getattr(run, "link", ""))
                else:
                    m_err(f"Error al descargar el video: {_e}")
                return 1
        ui.finish()
        if not os.path.exists(_dest) or os.path.getsize(_dest) == 0:
            cleanup_work(work_dir)
            m_err("No se encontró el video descargado.")
            return 1
        if idmm_direct() and idmm_is_carousel(run) and getattr(run, "plan", None):
            _conv = idmm_convert_native_video(_dest, run.plan, _fmt, getattr(run, "info", None), ui.bar)
            if _conv:
                _dest, _used = _conv
                run.conv_state.update(conv_info(run.plan, _used), path=_dest)
            else:
                m_warn("No se pudo convertir a compatible Apple: se guarda tal cual.")
        _ok, _why = verify_file(_dest, getattr(run, "info", None))
        if not _ok and "duracion" not in _why:
            m_err(t_display("Verificación falló") + f": {_why}")
            return 1
        if not _ok:
            m_warn(t_display("Verificación falló") + f": {_why} (se conserva el archivo)")
        with quiet("embed_tags", Exception):
            _tags_ok = embed_tags(_dest, run.info, work_dir)
        if not _tags_ok:
            if not is_installed("mutagen"):
                m_warn("Video sin metadatos: falta mutagen (pip install mutagen)")
            elif not _flag_env("DLPY_METADATA_TAGS", True):
                m_warn("Video sin metadatos: DLPY_METADATA_TAGS=0")
        run.subs = []
        run.final = _dest
        return None
    m_info(f"Bajando: {run.base}")
    _clients = client_attempts() if _is_youtube(getattr(run, "info", None)) else [None]
    _last_err = None
    try:
        for _ci, _client in enumerate(_clients):
            _opts = dict(run.opts)
            if _client:
                _ea = {"youtube": {"player_client": [_client]}}
                _pt = po_token()
                if _pt:
                    _ea["youtube"]["po_token"] = [_pt]
                _opts["extractor_args"] = _ea
            if _ci > 0:
                    m_info(t_display("Reintentando con otro cliente") + f": {_client}")
                    ux_status(t_display("Reintentando con otro cliente"), frac=0.1)
            try:
                with run.yt_dlp.YoutubeDL(_opts) as ydl:
                    if merge_ext and selected:
                        ydl.add_post_processor(
                            make_track_pp([track_label(t) for t in selected], ui.bar),
                            when="post_process")
                    if plan:
                        ydl.add_post_processor(make_apple_pp(plan, conv_state, ui.bar),
                                               when="post_process")
                    if getattr(run, 'is_foto', False):
                        ANALYSIS['t'] = time.monotonic()
                    res = run_download(ydl, run.yt_dlp, run.info, run.link, run.fmt_id, is_foto=getattr(run, 'is_foto', False))
                    rd = (res.get("requested_downloads") or [{}])[0]
                    run.subs = sub_files(res)
                    final = rd.get("filepath") or ydl.prepare_filename(res)
                    if conv_state.get("path"):
                        final = conv_state["path"]
                    dbg("resultado yt-dlp", {"final": final, "convertido": conv_state or None, "cliente": _client,
                                             "descargas": [pick(x, ("filepath", "format_id", "ext",
                                                                    "vcodec", "acodec"))
                                                           for x in (res.get("requested_downloads") or [])]})
                break
            except KeyboardInterrupt:
                raise
            except Exception as e:
                _last_err = e
                dbg("fallo con cliente", {"cliente": _client, "error": str(e)[:200]})
                _low = str(e).lower()
                _bot = is_bot_error(e) or "403" in _low or "410" in _low or "forbidden" in _low or "not available" in _low
                if _bot and _ci + 1 < len(_clients):
                    continue
                raise
        if final is None and _last_err is not None:
            raise _last_err
    except KeyboardInterrupt:
        ui.abort()
        saved = keep_for_resume(work_dir, run.start_bytes, failed=False)
        m_err("Descarga cancelada.")
        if saved:
            m_info(f"Avance guardado ({human_size(saved)}): repite el mismo enlace y formato para reanudar.")
        return 1
    except Exception as e:
        ui.abort()
        saved = keep_for_resume(work_dir, run.start_bytes, failed=True)
        m_err(f"Error al descargar: {e}")
        if saved:
            m_info(f"Avance guardado ({human_size(saved)}): al repetirlo se reanuda solo.")
        return 1
    ui.finish()
    if conv_state.get("path"):
        convert_done(plan, conv_state.get("vcodec"))
    if not final or not os.path.exists(final):
        cleanup_work(work_dir)
        m_err("No se encontró el archivo descargado.")
        return 1
    _ok, _why = verify_file(final, getattr(run, "info", None))
    if not _ok:
        if "duracion" in _why:
            m_warn(t_display("Verificación falló") + f": {_why} (se conserva el archivo)")
        else:
            m_err(t_display("Verificación falló") + f": {_why}")
            saved = keep_for_resume(work_dir, run.start_bytes, failed=True)
            if saved:
                m_info(f"Avance guardado ({human_size(saved)}): al repetirlo se reanuda solo.")
            return 1
    elif _flag_env("DLPY_VERIFY_FILE", True):
        dbg("verificado", _why)
    with quiet("embed_tags", Exception):
        embed_tags(final, run.info, work_dir)
    run.final = final
    return None
def _m_store(run):
    """[M7] Mover el resultado terminado a dlpy_files (solo procesos completados) y sustituir el anterior."""
    final, work_dir, old_file = run.final, run.work_dir, run.old_file
    dest_name = os.path.basename(final)
    dest_dir = idmm_subfolder_dir(run)
    os.makedirs(dest_dir, exist_ok=True)
    dest_path = os.path.join(dest_dir, dest_name)
    replacing = bool(old_file) or (os.path.isfile(dest_path) and os.path.abspath(final) != os.path.abspath(dest_path))
    if replacing:
        ux_status("Sustituyendo", frac=0.95)
    if os.path.abspath(final) != os.path.abspath(dest_path):
        tmp_dest = dest_path + ".tmp"
        try:
            drop_deliveries(dest_name)
            if os.path.isfile(dest_path):
                move_file(final, tmp_dest)
                os.replace(tmp_dest, dest_path)
            else:
                move_file(final, dest_path)
            final = dest_path
        except Exception as e:
            with quiet("_m_store", OSError):
                os.remove(tmp_dest)
            cleanup_work(work_dir)
            m_err(f"No se pudo guardar el archivo en {FILES_DIR}: {e}")
            return 1
    dbg("movido a", final)
    m_ok(f"Guardado en: {final}")
    if old_file and os.path.abspath(old_file) != os.path.abspath(final):
        with quiet("main", OSError):
            os.remove(old_file)
        drop_deliveries(os.path.basename(old_file))
        _root, _ext = os.path.splitext(os.path.basename(final))
        clean = os.path.join(os.path.dirname(final), re.sub(r" \(nuevo\)(?=(?:-\d+)?$)", "", _root) + _ext)
        if clean != final and not os.path.exists(clean):
            os.replace(final, clean)
            final = clean
    run.final = final
    idmm_exit_track(run)
    _ns = store_subs(getattr(run, "subs", None), final)
    if _ns:
        m_ok(f"Subtítulos: {_ns}")
    _tag_version(final)
    _tag_subs(getattr(run, "subs", None), final)
    cleanup_work(work_dir)
    if replacing:
        ux_hold(SCENE_REPLACE_SECS)
    ux_status("Guardado", frac=1.0)
    return None
def _m_register(run):
    """[M8] 6) Registrar (con datos técnicos) y enviar el archivo."""
    final, key, title = run.final, run.key, run.title
    index = load_json(INDEX_FILE)
    index[key] = {"file": _rel_files(final), "title": title,
                  "date": int(time.time()), "version": VERSION,
                  "meta": build_meta(run.kind, run.fmt, run.fmt_id, run.selected, run.orig_ids, final,
                                    run.conv_state or None, run.info)}
    dbg("índice", index[key])
    try:
        save_json(INDEX_FILE, index)
    except DISK_ERRORS as e:
        m_warn(f"No se pudo guardar el índice: {e}")
    history_add(key, index[key])
    idmm_exit_track(run)
    result_card(final, title, index[key]["meta"], run.info.get("duration"))
    deliver(final, title, skip_open=idmm_skip_open(run))
    return 0
RESUME_STEPS = (_m_link, _m_analyze, _m_choose, _m_summary, _m_tracks, _m_convert_reuse, _m_workspace, _m_download,
                _m_store, _m_register)
MAIN_STEPS = (_m_modes, _m_prepare, _m_update, _m_resume, _m_link, _m_analyze, _m_choose, _m_summary, _m_tracks,
              _m_convert_reuse, _m_workspace, _m_download, _m_store, _m_register)
BATCH_STEPS = (_m_analyze, _m_choose, _m_summary, _m_tracks, _m_convert_reuse, _m_workspace, _m_download,
                _m_store, _m_register)
def main():
    """Ejecuta los pasos de MAIN_STEPS en orden; el primero que devuelve un código (no None) termina main(). 2.0.8: luego vacía la cola (BATCH_STEPS por enlace)."""
    IDMM_EXIT["files"] = []
    IDMM_EXIT["done"] = False
    run = _Run()
    try:
        for step in MAIN_STEPS:
            rc = step(run)
            if rc is not None:
                if rc == 0 and step in (_m_register, _m_convert_reuse):
                    break
                return rc
        while getattr(run, "batch_queue", None):
            nxt = run.batch_queue.pop(0)
            run.batch_index = (run.batch_total - len(run.batch_queue)) if getattr(run, "batch_total", 0) else 1
            ux_say(t_display("Cola") + f": {run.batch_index} de {run.batch_total} · {nxt}")
            nxt_run = _Run()
            nxt_run.yt_dlp = getattr(run, "yt_dlp", None)
            nxt_run.cli_args = getattr(run, "cli_args", None)
            nxt_run.spick = None
            nxt_run.link = nxt
            nxt_run.batch_queue = run.batch_queue
            nxt_run.batch_total = getattr(run, "batch_total", 1)
            nxt_run.batch_index = run.batch_index
            nxt_run.site_shown = getattr(run, "site_shown", False)
            try:
                ux_start(nxt_run, resume=True)
            except Exception as _ign:
                diagnostic_report("A", f"cola: arrancar escena del siguiente enlace: {type(_ign).__name__}: {_ign}")
                pass
            for step in BATCH_STEPS:
                rc = step(nxt_run)
                if rc is not None:
                    break
        try:
            idmm_exit_animation()
        except Exception:
            pass
        return 0
    except Exception as exc:
        diagnostic_report("E", f"Error inesperado: {type(exc).__name__}: {exc}")
        raise
    finally:
        ux_error_end()
        ux_stop(clear=not bool(IDMM_EXIT.get("done")))
if __name__ == "__main__":
    sys.exit(run_main(main))